INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dr-seuss---how-the-grinch-stole-christmas!-europe-enfrdeesit', 'NDS', 'Dr. Seuss - How the Grinch Stole Christmas! (Europe) (En,Fr,De,Es,It)', '2007', 'Adventure', 'Artificial Mind & Movement', '1', 'Kids Adventure', '2D platforming and mini-games.', 'Stop the Grinch from stealing Christmas in Whoville.', 'Festive adventure based on the Dr. Seuss classic.', 'Play as the Grinch and his dog Max. Navigate through snowy levels, solve puzzles, and use stealth to sneak into houses and take back Christmas in this charming, holiday-themed platformer for NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dr-seuss---how-the-grinch-stole-christmas!-usa', 'NDS', 'Dr. Seuss - How the Grinch Stole Christmas! (USA)', '2007', 'Adventure', 'Artificial Mind & Movement', '1', 'Kids Adventure', '2D platforming and mini-games.', 'Stop the Grinch from stealing Christmas in Whoville.', 'Festive adventure based on the Dr. Seuss classic.', 'Play as the Grinch and his dog Max. Navigate through snowy levels, solve puzzles, and use stealth to sneak into houses and take back Christmas in this charming, holiday-themed platformer for NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dr-slump-arale-chan-japan', 'NDS', 'Dr. Slump Arale-chan (Japan)', '2007', 'Action', 'Alfa System', '1', 'Comedy Action', 'Action-adventure and mini-games.', 'Explore Penguin Village and interact with Arale’s friends.', 'Wacky anime adventure based on the hit manga.', 'Join Arale Norimaki in a series of hilarious and chaotic missions. Use her super strength to solve puzzles, play mini-games, and experience the unique humor of Akira Toriyama''s classic series on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('drachenzaehmen-leicht-gemacht-germany', 'NDS', 'Drachenzaehmen Leicht Gemacht (Germany)', '2010', 'Simulation', 'Behaviour Interactive', '1', 'Movie Tie-in', 'Action-adventure with dragon training.', 'Train your dragon and protect the Viking village of Berk.', 'German version of How to Train Your Dragon.', 'Fly into battle with Toothless! Customize your dragons, explore the Isle of Berk, and engage in arena combat against fierce rivals in this action-packed movie tie-in for the Nintendo DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('draglade-europe-enfrdeesit', 'NDS', 'Draglade (Europe) (En,Fr,De,Es,It)', '2007', 'Action', 'Racjin', '2', 'Action Duel', 'Rhythm-based fighting and combat.', 'Duel rivals using musical "G-Codes" and rhythmic beats.', 'Unique hybrid of fighting and rhythm games.', 'Draglade combines 2D fighting mechanics with a deep rhythm system. Customize your weapon''s sound and execute powerful musical combos to defeat opponents in a futuristic tournament setting.');
