INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball---origins-europe-enfrdeesit', 'NDS', 'Dragon Ball - Origins (Europe) (En,Fr,De,Es,It)', '2008', 'Action', 'Game Republic', '1', 'Anime Action', '3D action-adventure with touch controls.', 'Relive Goku''s early adventures and find the Dragon Balls.', 'Full-touch adventure of the original series.', 'Dragon Ball: Origins (Dragon Ball DS) covers the search for the Dragon Balls. Use the stylus to move Goku, perform the Kamehameha, and solve puzzles in a beautifully rendered 3D world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball---origins-usa', 'NDS', 'Dragon Ball - Origins (USA)', '2008', 'Action', 'Game Republic', '1', 'Anime Action', '3D action-adventure with touch controls.', 'Relive Goku''s early adventures and find the Dragon Balls.', 'Full-touch adventure of the original series.', 'Dragon Ball: Origins (Dragon Ball DS) covers the search for the Dragon Balls. Use the stylus to move Goku, perform the Kamehameha, and solve puzzles in a beautifully rendered 3D world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball---origins-2-europe-enfrdeesit', 'NDS', 'Dragon Ball - Origins 2 (Europe) (En,Fr,De,Es,It)', '2010', 'Action', 'Game Republic', '1', 'Anime Action', '3D action-adventure with platforming.', 'Defeat the Red Ribbon Army and find the Dragon Balls.', 'Action-packed sequel to the NDS original.', 'Origins 2 expands the gameplay with new playable characters and a focus on the Red Ribbon Army saga. Experience improved combat, massive boss fights, and 2-player co-op missions.');
