INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-kai---saiyajin-raishuu-japan', 'NDS', 'Dragon Ball Kai - Saiyajin Raishuu (Japan)', '2010', 'Fighting', 'Artdink', '1', 'Anime Fighting', 'Turn-based tactical RPG.', 'Defeat the Saiyan invaders Nappa and Vegeta.', 'Epic turn-based RPG with DBZ Kai branding.', 'Known as Attack of the Saiyans, this RPG features a deep combat system with combos and ultimate attacks. Explore the world, level up your favorite Z-Fighters, and experience a faithful retelling of the Saiyan Saga.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-kai---ultimate-butou-den-japan', 'NDS', 'Dragon Ball Kai - Ultimate Butou Den (Japan)', '2011', 'Fighting', 'Artdink', '1', 'Anime Fighting', '2D fighting and brawling.', 'Win the ultimate martial arts tournament.', 'High-speed 2D fighter with a massive roster.', 'Ultimate Butou Den features over 50 characters and a refined fighting engine. With cinematic special moves and a deep story mode, it''s one of the most complete Dragon Ball fighting experiences on the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---attack-of-the-saiyans-europe-enfrdeesit', 'NDS', 'Dragon Ball Z - Attack of the Saiyans (Europe) (En,Fr,De,Es,It)', '2009', 'RPG', 'Monolith Soft', '1', 'Anime RPG', 'Turn-based tactical RPG.', 'Defeat the Saiyan invaders Nappa and Vegeta.', 'Epic turn-based RPG with DBZ Kai branding.', 'Known as Attack of the Saiyans, this RPG features a deep combat system with combos and ultimate attacks. Explore the world, level up your favorite Z-Fighters, and experience a faithful retelling of the Saiyan Saga.');
