INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---bukuu-ressen-japan', 'NDS', 'Dragon Ball Z - Bukuu Ressen (Japan)', '2005', 'Action', 'Dimps', '1', 'Anime Action', '2D tag-team fighting.', 'Battle through the Dragon Ball Z storyline.', 'Fast-paced aerial combat and team battles.', 'Known as Supersonic Warriors 2, this fighter features intense 3v3 aerial combat. Utilize the touch screen to trigger character swaps and devastating team-up attacks in a variety of "What If" scenarios.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---goku-densetsu-europe-enfrdeesit', 'NDS', 'Dragon Ball Z - Goku Densetsu (Europe) (En,Fr,De,Es,It)', '2005', 'Action', 'Dimps', '1', 'Anime Action', 'Card-based RPG and strategy.', 'Use cards to move, defend, and attack through the Z-Saga.', 'Strategic card-battling Dragon Ball adventure.', 'Known as Harukanaru Densetsu, this title uses a unique card-based system for everything from exploration to combat. Master the card values to unleash powerful energy blasts and survive the series'' iconic battles.');
