INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-booster-europe-enfrdeesit', 'NDS', 'Dragon Booster (Europe) (En,Fr,De,Es,It)', '2005', 'Action', 'Activision', '1', 'Action', 'Side-scrolling dragon racing and combat.', 'Win races and defeat rivals using dragon abilities.', 'Intense dragon racing and combat based on the hit animated series.', 'Experience the thrill of Dragon Booster on NDS. Master dragon racing and tactical combat in this high-speed adventure. Upgrade your dragon''s gear and unleash powerful attacks to become the ultimate hero in the city of Dragon City.');
