INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-dance-japan', 'NDS', 'Dragon Dance (Japan)', '2004', 'Action', 'Taito', '1', 'Arcade', 'Puzzle-based dragon movement and strategy.', 'Navigate dragons through complex grid-based puzzles.', 'A classic Japanese puzzle game involving strategic dragon movements.', 'Dragon Dance for NDS offers a unique blend of puzzle-solving and strategy. Navigate through challenging levels, plan your moves carefully, and enjoy the classic Japanese aesthetics in this addictive handheld title perfect for puzzle lovers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-hunters-europe-enfrdeesit', 'NDS', 'Dragon Hunters (Europe) (En,Fr,De,Es,It)', '2006', 'Action-Adventure', 'Ubisoft', '1', 'Action', 'Action-platformer with character switching.', 'Hunt and defeat giant dragons across various levels.', 'Action-packed platforming based on the Dragon Hunters film and show.', 'Join Lian-Chu and Gwizdo in Dragon Hunters for NDS. Switch between characters to utilize unique skills, explore dangerous environments, and hunt down massive dragons in this engaging action-platformer inspired by the popular franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-master-europe-enfrdeesit', 'NDS', 'Dragon Master (Europe) (En,Fr,De,Es,It)', '2007', 'Action', '505 Games', '1', 'Action', 'Strategy and turn-based combat.', 'Train dragons and win tactical battles against opponents.', 'A tactical RPG focused on dragon training and strategic combat.', 'Dragon Master challenges players to become the ultimate dragon trainer on NDS. Build your team, master elemental affinities, and engage in deep tactical turn-based battles to rise through the ranks and prove your mastery in this fantasy world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-quest---the-chapters-of-the-chosen-europe-enfrdeesit', 'NDS', 'Dragon Quest - The Chapters of the Chosen (Europe) (En,Fr,De,Es,It)', '2008', 'RPG', 'Square Enix', '1', 'Turn-based', 'Turn-based RPG with party management.', 'Guide a group of chosen heroes to defeat the ultimate evil.', 'A legendary RPG epic spanning multiple chapters and unique characters.', 'Dragon Quest IV: Chapters of the Chosen is a definitive NDS RPG experience. Follow five distinct storylines that converge into one epic quest. Featuring turn-based combat, deep character development, and a vast world to explore.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-quest---the-hand-of-the-heavenly-bride-europe-enfrdeesit', 'NDS', 'Dragon Quest - The Hand of the Heavenly Bride (Europe) (En,Fr,De,Es,It)', '2009', 'RPG', 'Square Enix', '1', 'Turn-based', 'Turn-based RPG with monster recruitment.', 'Follow a hero''s life through three generations and save the world.', 'An emotional RPG journey following a hero from childhood to fatherhood.', 'Dragon Quest V: Hand of the Heavenly Bride brings a classic tale to NDS. Experience a generational story, recruit monsters to your party, and make life-altering choices. A must-play RPG known for its deep narrative and strategic combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-quest-heroes---rocket-slime-usa', 'NDS', 'Dragon Quest Heroes - Rocket Slime (USA)', '2005', 'Action RPG', 'Square Enix', '1', 'Action RPG', 'Action-adventure with tank battles.', 'Rescue kidnapped slimes and win massive tank duels.', 'A charming spin-off featuring Rocket the Slime in tank combat.', 'Dragon Quest Heroes: Rocket Slime delivers unique action on NDS. Control Rocket, collect items to use as ammo, and pilot giant mechanical tanks in explosive battles. Explore the world of Slimenia in this fun and creative Dragon Quest spin-off.');
