INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-quest-ix---hoshizora-no-mamoribito-japan', 'NDS', 'Dragon Quest IX - Hoshizora no Mamoribito (Japan)', '2009', 'RPG', 'Square Enix', '1', 'Turn-based', 'Turn-based RPG with deep customization.', 'Create a hero, protect the mortals, and find the fygg fruits.', 'A massive RPG featuring multiplayer support and endless customization.', 'Dragon Quest IX: Sentinels of the Starry Skies offers an expansive RPG world on NDS. Customize your character''s appearance and class, engage in strategic battles, and enjoy a story of celestial guardians. Includes deep post-game content and multiplayer.');
