INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-quest-monsters---joker-europe-enfrdeesit', 'NDS', 'Dragon Quest Monsters - Joker (Europe) (En,Fr,De,Es,It)', '2006', 'RPG', 'Square Enix', '1', 'Turn-based', 'Turn-based monster battling and breeding.', 'Capture, breed, and train monsters to win the tournament.', 'A monster-catching RPG set in the iconic Dragon Quest universe.', 'Dragon Quest Monsters: Joker brings high-stakes monster scouting to NDS. Explore 3D environments, capture hundreds of different creatures, and fuse them to create powerful new breeds. Compete in the Monster GP and become a legendary scout.');
