INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-quest-monsters---joker-usa', 'NDS', 'Dragon Quest Monsters - Joker (USA)', '2006', 'RPG', 'Square Enix', '1', 'Turn-based', 'Turn-based monster battling and breeding.', 'Capture, breed, and train monsters to win the tournament.', 'A monster-catching RPG set in the iconic Dragon Quest universe.', 'Dragon Quest Monsters: Joker brings high-stakes monster scouting to NDS. Explore 3D environments, capture hundreds of different creatures, and fuse them to create powerful new breeds. Compete in the Monster GP and become a legendary scout.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-quest-monsters---joker-2-japan', 'NDS', 'Dragon Quest Monsters - Joker 2 (Japan)', '2010', 'RPG', 'Square Enix', '1', 'Turn-based', 'Turn-based monster battling and breeding.', 'Explore a giant island and win the monster battling tournament.', 'The expanded sequel to the hit monster-catching RPG.', 'Dragon Quest Monsters: Joker 2 enhances the monster-catching formula on NDS. Discover a massive island filled with giant monsters, utilize a deeper fusion system, and engage in strategic turn-based combat with over 300 unique creatures to collect.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-quest-v---hand-of-the-heavenly-bride-usa-enfres', 'NDS', 'Dragon Quest V - Hand of the Heavenly Bride (USA) (En,Fr,Es)', '2009', 'RPG', 'Square Enix', '1', 'Turn-based', 'Turn-based RPG with monster recruitment.', 'Follow a hero''s life through three generations and save the world.', 'An emotional RPG journey following a hero from childhood to fatherhood.', 'Dragon Quest V: Hand of the Heavenly Bride brings a classic tale to NDS. Experience a generational story, recruit monsters to your party, and make life-altering choices. A must-play RPG known for its deep narrative and strategic combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-quest-v---tenkuu-no-hanayome-japan', 'NDS', 'Dragon Quest V - Tenkuu no Hanayome (Japan)', '2008', 'RPG', 'Square Enix', '1', 'Turn-based', 'Turn-based RPG with monster recruitment.', 'Follow a hero''s life through three generations and save the world.', 'An emotional RPG journey following a hero from childhood to fatherhood.', 'Dragon Quest V: Hand of the Heavenly Bride brings a classic tale to NDS. Experience a generational story, recruit monsters to your party, and make life-altering choices. A must-play RPG known for its deep narrative and strategic combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-quest-vi---maboroshi-no-daichi-japan', 'NDS', 'Dragon Quest VI - Maboroshi no Daichi (Japan)', '2010', 'RPG', 'Square Enix', '1', 'Turn-based', 'Turn-based RPG with world-shifting mechanics.', 'Travel between two parallel worlds to uncover the truth.', 'An epic RPG adventure featuring dual worlds and class systems.', 'Dragon Quest VI: Realms of Revelation is a classic NDS RPG. Journey between the Real World and the Dream World to defeat a dark force. Features a deep vocation system, challenging turn-based combat, and a vast, interconnected story.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-quest-vi---realms-of-revelation-usa-enfres', 'NDS', 'Dragon Quest VI - Realms of Revelation (USA) (En,Fr,Es)', '2011', 'RPG', 'Square Enix', '1', 'Turn-based', 'Turn-based RPG with world-shifting mechanics.', 'Travel between two parallel worlds to uncover the truth.', 'An epic RPG adventure featuring dual worlds and class systems.', 'Dragon Quest VI: Realms of Revelation is a classic NDS RPG. Journey between the Real World and the Dream World to defeat a dark force. Features a deep vocation system, challenging turn-based combat, and a vast, interconnected story.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-tamer---sound-spirit-japan', 'NDS', 'Dragon Tamer - Sound Spirit (Japan)', '2006', 'Action RPG', 'Neverland', '1', 'Action RPG', 'Rhythm-based monster battling.', 'Collect "Sound Spirits" and battle using rhythm mechanics.', 'A unique rhythm-based monster training game from Japan.', 'Dragon Tamer: Sound Spirit offers a musical twist on the monster-battling genre for NDS. Collect spirits born from sounds, train them through rhythm games, and engage in tactical battles. A creative and vibrant title for fans of music and RPGs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-thrills-with-magic-lilly-europe-enfrdeesit', 'NDS', 'Dragon Thrills with Magic Lilly (Europe) (En,Fr,De,Es,It)', '2008', 'Adventure', 'Magic Pockets', '1', 'Casual', 'Mini-game collection and exploration.', 'Complete magical tasks and puzzles with Lily and her dragon.', 'A charming adventure game for kids featuring dragons and magic.', 'Dragon Thrills with Magic Lilly on NDS is a delightful game for younger players. Join Lilly on a magical journey, solve simple puzzles, and complete fun mini-games while interacting with friendly dragons in a colorful world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-zakura-ds-japan', 'NDS', 'Dragon Zakura DS (Japan)', '2007', 'Simulation', 'Bandai Namco', '1', 'Simulation', 'Educational simulation and trivia.', 'Study and pass the prestigious university entrance exams.', 'An educational game based on the popular manga Dragon Zakura.', 'Dragon Zakura DS for NDS is a unique educational tool designed to help students study for exams. Featuring characters from the manga, it offers various mini-games and quizzes focused on real-world academic success and study techniques.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragonology-europe-enfrdeesitnl', 'NDS', 'Dragonology (Europe) (En,Fr,De,Es,It,Nl)', '2009', 'Educational', 'Eidos', '1', 'Educational', 'Adventure and encyclopedia simulation.', 'Study dragons and become a master of Dragonology.', 'An interactive adventure based on the best-selling Dragonology books.', 'Dive into the world of Dragonology on NDS. Track down elusive dragons, study their habits using the stylus, and complete your dragon encyclopedia. A perfect blend of educational exploration and adventure for fans of mythical creatures.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragonology-usa-enfrdeesit', 'NDS', 'Dragonology (USA) (En,Fr,De,Es,It)', '2009', 'Educational', 'Eidos', '1', 'Educational', 'Adventure and encyclopedia simulation.', 'Study dragons and become a master of Dragonology.', 'An interactive adventure based on the best-selling Dragonology books.', 'Dive into the world of Dragonology on NDS. Track down elusive dragons, study their habits using the stylus, and complete your dragon encyclopedia. A perfect blend of educational exploration and adventure for fans of mythical creatures.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('drake-&-josh---talent-showdown-usa-enfr', 'NDS', 'Drake & Josh - Talent Showdown (USA) (En,Fr)', '2007', 'Party', 'Game Factory', '4', 'Party', 'Action mini-games and adventure.', 'Compete in a series of challenges to win the talent show.', 'A fun adventure based on the Nickelodeon show Drake & Josh.', 'Join the brothers in Drake & Josh: Talent Showdown for NDS. Play through various mini-games, navigate school life, and help them win the big competition. Features the humor and characters from the hit TV series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('drama-queens-europe', 'NDS', 'Drama Queens (Europe)', '2008', 'Adventure', 'Mindscape', '1', 'Casual', 'Board game style strategy with social elements.', 'Win the board game while managing social drama.', 'A social board game focused on fashion, friends, and drama.', 'Drama Queens for NDS is a competitive board game where players navigate social circles and fashion trends. Use strategy to sabotage rivals and boost your own popularity in this fun, lighthearted title aimed at younger audiences.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('drama-queens-usa', 'NDS', 'Drama Queens (USA)', '2008', 'Adventure', 'Mindscape', '1', 'Casual', 'Board game style strategy with social elements.', 'Win the board game while managing social drama.', 'A social board game focused on fashion, friends, and drama.', 'Drama Queens for NDS is a competitive board game where players navigate social circles and fashion trends. Use strategy to sabotage rivals and boost your own popularity in this fun, lighthearted title aimed at younger audiences.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dramatic-dungeon---sakura-taisen---kimi-aru-ga-tame-japan', 'NDS', 'Dramatic Dungeon - Sakura Taisen - Kimi Aru ga Tame (Japan)', '2008', 'RPG', 'Red Company', '1', 'Turn-based', 'Tactical RPG with visual novel elements.', 'Lead the Sakura Wars cast through dungeon-crawling battles.', 'A crossover dungeon-crawler featuring the Sakura Taisen cast.', 'Dramatic Dungeon: Sakura Taisen for NDS combines tactical dungeon exploration with the beloved characters of the Sakura Wars series. Engage in strategic grid-based combat and enjoy story-heavy segments in this unique Japanese RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('drawn-to-life---kamisama-no-marionette-japan', 'NDS', 'Drawn to Life - Kamisama no Marionette (Japan)', '2010', 'Platform', 'Taito', '1', 'Action', 'Platforming with drawing mechanics.', 'Draw your own hero and objects to save the village.', 'A creative platformer where you draw your protagonist and tools.', 'Drawn to Life: Kamisama no Marionette brings creativity to NDS. Use the stylus to design your hero, weapons, and platforms. Explore vibrant levels and solve puzzles by drawing what you need to progress through this unique Japanese version.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('drawn-to-life---spongebob-squarepants-edition-europe-enfrdeitnl', 'NDS', 'Drawn to Life - SpongeBob SquarePants Edition (Europe) (En,Fr,De,It,Nl)', '2009', 'Platform', 'THQ', '1', 'Action', 'Platforming with drawing mechanics.', 'Create a custom hero to help SpongeBob save Bikini Bottom.', 'Draw your own character in the world of SpongeBob SquarePants.', 'Drawn to Life: SpongeBob SquarePants Edition for NDS combines creative drawing with Nickelodeon fun. Design your own citizen of Bikini Bottom and help SpongeBob defeat Patrick''s creations in this imaginative action-platformer.');
