INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('drawn-to-life---the-next-chapter-europe-enfrdeesitnl', 'NDS', 'Drawn to Life - The Next Chapter (Europe) (En,Fr,De,Es,It,Nl)', '2009', 'Platform', 'THQ', '1', 'Action', 'Action-platforming with transformation drawing.', 'Save the Raposa and the world from a new shadow threat.', 'The sequel featuring more drawing tools and hero transformations.', 'Drawn to Life: The Next Chapter on NDS expands the creative gameplay of the original. Draw multiple hero forms, customize your own vehicles, and travel across different realms to stop the shadows in this epic, emotional sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('drawn-to-life---the-next-chapter-usa-enfr', 'NDS', 'Drawn to Life - The Next Chapter (USA) (En,Fr)', '2009', 'Platform', 'THQ', '1', 'Action', 'Action-platforming with transformation drawing.', 'Save the Raposa and the world from a new shadow threat.', 'The sequel featuring more drawing tools and hero transformations.', 'Drawn to Life: The Next Chapter on NDS expands the creative gameplay of the original. Draw multiple hero forms, customize your own vehicles, and travel across different realms to stop the shadows in this epic, emotional sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('drawn-to-life-europe-enfrdeesit', 'NDS', 'Drawn to Life (Europe) (En,Fr,De,Es,It)', '2007', 'Platform', 'THQ', '1', 'Action', 'Platforming with drawing mechanics.', 'Draw your own hero and objects to save the village.', 'A creative platformer where you draw your protagonist and tools.', 'Drawn to Life for NDS is a revolutionary title where your imagination is the limit. Use the stylus to draw your hero and essential items. Explore levels, defeat enemies, and rebuild a dying village in this charming adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('drawn-to-life-usa-enfr', 'NDS', 'Drawn to Life (USA) (En,Fr)', '2007', 'Platform', 'THQ', '1', 'Action', 'Platforming with drawing mechanics.', 'Draw your own hero and objects to save the village.', 'A creative platformer where you draw your protagonist and tools.', 'Drawn to Life for NDS is a revolutionary title where your imagination is the limit. Use the stylus to draw your hero and essential items. Explore levels, defeat enemies, and rebuild a dying village in this charming adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('drawn-to-life-collection-europe-enfrdeesit', 'NDS', 'Drawn to Life Collection (Europe) (En,Fr,De,Es,It)', '2009', 'Platform', 'THQ', '1', 'Action', 'Platforming with drawing mechanics.', 'Complete the adventures of the first two Drawn to Life games.', 'A compilation of the first two acclaimed Drawn to Life titles.', 'The Drawn to Life Collection for NDS features both the original game and The Next Chapter on one cartridge. Experience the full saga of the Raposa, enjoy hours of drawing-based platforming, and unleash your inner artist.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dream-chronicles-usa', 'NDS', 'Dream Chronicles (USA)', '2009', 'Adventure', 'IPlay', '1', 'Casual', 'Hidden object and puzzle solving.', 'Solve puzzles to escape a dream world and find your husband.', 'A mystical hidden object adventure set in a dream realm.', 'Dream Chronicles on NDS brings the popular PC hidden object game to handhelds. Solve intricate puzzles, find hidden items, and explore a beautifully rendered dream world to uncover the mystery of Faye''s missing husband.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dream-day---wedding-destinations-usa', 'NDS', 'Dream Day - Wedding Destinations (USA)', '2009', 'Simulation', 'JoWooD', '1', 'Casual', 'Hidden object and time management.', 'Find items and plan the perfect wedding in exotic locations.', 'A wedding-themed hidden object game with global destinations.', 'Dream Day: Wedding Destinations for NDS lets you become a wedding planner. Search for hidden items across beautiful locations, manage wedding details, and solve puzzles to ensure the perfect ceremony for various couples.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dream-pinball-3d-europe-enfrdeesit', 'NDS', 'Dream Pinball 3D (Europe) (En,Fr,De,Es,It)', '2008', 'Pinball', 'Digital Extremes', '1', 'Arcade', 'Pinball simulation.', 'Score high points and master various pinball tables.', 'High-quality 3D pinball simulation with multiple themes.', 'Dream Pinball 3D for NDS features realistic physics and six uniquely themed tables, including Knight, Monsters, and Dino. Experience fast-paced arcade action with multiple camera angles and stunning 3D pinball graphics.');
