INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dream-salon-usa', 'NDS', 'Dream Salon (USA)', '2008', 'Simulation', 'Zoo Games', '1', 'Casual', 'Time management and simulation.', 'Manage a beauty salon and satisfy customer requests.', 'A salon management game focused on hair and makeup.', 'Dream Salon for NDS puts you in charge of your own beauty business. Wash, cut, and style hair, apply makeup, and keep your customers happy to grow your salon''s reputation in this fun lifestyle simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dreamer-series---babysitter-usa-enfres', 'NDS', 'Dreamer Series - Babysitter (USA) (En,Fr,Es)', '2009', 'Simulation', 'Zoo Games', '1', 'Casual', 'Simulation and mini-games.', 'Take care of babies and manage a successful nursery.', 'A babysitting simulation where you care for infants.', 'Dreamer Series: Babysitter on NDS tasks you with the responsibilities of child care. Feed, play with, and soothe babies while managing your schedule. Complete mini-games to earn rewards and become the ultimate babysitter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dreamer-series---pop-star-usa-enfrdeesitnl', 'NDS', 'Dreamer Series - Pop Star (USA) (En,Fr,De,Es,It,Nl)', '2009', 'Simulation', 'Zoo Games', '1', 'Casual', 'Rhythm and simulation.', 'Practice singing and dancing to become a world-famous pop star.', 'A career simulation game about becoming a music idol.', 'Dreamer Series: Pop Star for NDS lets you live out your musical dreams. Practice your performance skills through rhythm games, choose your stage outfits, and rise to fame in this engaging music career simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dreamer-series---puppy-trainer-usa-enes', 'NDS', 'Dreamer Series - Puppy Trainer (USA) (En,Es)', '2008', 'Simulation', 'Zoo Games', '1', 'Casual', 'Simulation and pet training.', 'Train puppies and enter them into talent competitions.', 'A puppy training sim focused on teaching tricks and care.', 'Dreamer Series: Puppy Trainer on NDS allows you to raise and train your own puppy. Teach your pet various commands using the stylus and microphone, enter competitions, and care for your furry friend''s every need.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dreamer-series---shop-owner-usa-enfres', 'NDS', 'Dreamer Series - Shop Owner (USA) (En,Fr,Es)', '2009', 'Simulation', 'Zoo Games', '1', 'Casual', 'Time management and simulation.', 'Run a successful boutique and manage inventory.', 'A retail simulation where you manage your own shop.', 'Dreamer Series: Shop Owner for NDS gives you the keys to your own store. Stock shelves, assist customers, and manage finances to expand your business. A perfect simulation for those who dream of running their own shop.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dreamer-series---teacher-usa-enfres', 'NDS', 'Dreamer Series - Teacher (USA) (En,Fr,Es)', '2009', 'Simulation', 'Zoo Games', '1', 'Casual', 'Simulation and educational mini-games.', 'Teach students and manage a classroom effectively.', 'A classroom simulation where you play as a teacher.', 'Dreamer Series: Teacher for NDS lets you step into the shoes of an educator. Grade papers, teach various subjects through mini-games, and help your students succeed in this fun and educational school simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dreamer-series---top-model-usa-enfrdeesit', 'NDS', 'Dreamer Series - Top Model (USA) (En,Fr,De,Es,It)', '2009', 'Simulation', 'Zoo Games', '1', 'Casual', 'Simulation and fashion mini-games.', 'Walk the runway and win fashion competitions.', 'A fashion career simulation about the world of modeling.', 'Dreamer Series: Top Model on NDS takes you to the catwalk. Choose your outfits, apply makeup, and master the runway to become a fashion icon. Compete in photo shoots and fashion shows to reach the top.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dreamer-series---zoo-keeper-usa-enfrdeesit', 'NDS', 'Dreamer Series - Zoo Keeper (USA) (En,Fr,De,Es,It)', '2009', 'Simulation', 'Zoo Games', '1', 'Casual', 'Simulation and animal care.', 'Manage a zoo and care for a variety of wild animals.', 'A zoo management simulation featuring animal interaction.', 'Dreamer Series: Zoo Keeper for NDS allows you to run your own wildlife park. Feed the animals, clean their enclosures, and ensure the visitors are happy. Learn about different species while managing a successful zoo.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dreamworks-2-in-1-party-pack-usa-enfr', 'NDS', 'DreamWorks 2-in-1 Party Pack (USA) (En,Fr)', '2009', 'Party', 'D3 Publisher', '4', 'Party', 'Mini-game collection.', 'Win various mini-games based on DreamWorks films.', 'A party game featuring characters from Shrek and Madagascar.', 'DreamWorks 2-in-1 Party Pack for NDS brings your favorite movie characters together. Compete in a variety of fun, family-friendly mini-games inspired by the hit films Shrek and Madagascar in this portable party experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('drei-fragezeichen-die---das-geheimnis-der-geisterinsel-germany', 'NDS', 'Drei Fragezeichen, Die - Das Geheimnis der Geisterinsel (Germany)', '2007', 'Adventure', 'Phenomedia', '1', 'Adventure', 'Adventure and point-and-click.', 'Solve the mystery of Ghost Island with the three detectives.', 'A mystery adventure based on "The Three Investigators."', 'Die Drei Fragezeichen: Das Geheimnis der Geisterinsel for NDS is a German-language adventure. Join Justus, Peter, and Bob as they solve puzzles and search for clues to uncover the secrets of a mysterious island.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('drei-fragezeichen-die---das-geheimnis-der-toten-germany', 'NDS', 'Drei Fragezeichen, Die - Das Geheimnis der Toten (Germany)', '2009', 'Adventure', 'Phenomedia', '1', 'Adventure', 'Adventure and point-and-click.', 'Uncover the truth behind a series of mysterious deaths.', 'A detective adventure featuring the famous German trio.', 'Die Drei Fragezeichen: Das Geheimnis der Toten on NDS challenges you to solve a dark mystery. Use your detective skills to interview witnesses, collect evidence, and solve complex puzzles in this immersive adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('driver-license-trainer-espana-spain', 'NDS', 'Driver License Trainer Espana (Spain)', '2008', 'Educational', 'Nintendo', '1', 'Educational', 'Educational and driving simulation.', 'Pass the Spanish driving theory and practical exams.', 'A driving school simulator tailored for the Spanish market.', 'Driver License Trainer Espana for NDS is a comprehensive tool for aspiring drivers. Practice Spanish traffic rules, take mock theory tests, and simulate driving scenarios to prepare for your real-world driving license.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('driver-license-trainer-italia-italy', 'NDS', 'Driver License Trainer Italia (Italy)', '2008', 'Educational', 'Nintendo', '1', 'Educational', 'Educational and driving simulation.', 'Pass the Italian driving theory and practical exams.', 'A driving school simulator tailored for the Italian market.', 'Driver License Trainer Italia for NDS helps you prepare for the Italian driving test. Learn local road signs, study traffic laws, and test your knowledge with interactive quizzes designed for the Italian license system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('drivers-ed-portable-usa', 'NDS', 'Drivers Ed Portable (USA)', '2008', 'Educational', 'Vivid Games', '1', 'Educational', 'Educational and driving simulation.', 'Learn traffic rules and practice for the driving exam.', 'A portable driving school and theory trainer.', 'Drivers Ed Portable for NDS is the perfect study companion for new drivers. It features comprehensive theory lessons, practice tests, and driving simulations to help you gain confidence before taking your official exam.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('drivers-ed-portable-europe-enfrdeesit', 'NDS', 'Drivers'' Ed Portable (Europe) (En,Fr,De,Es,It)', '2008', 'Educational', 'Vivid Games', '1', 'Educational', 'Educational and driving simulation.', 'Learn traffic rules and practice for the driving exam.', 'A portable driving school and theory trainer.', 'Drivers Ed Portable for NDS is the perfect study companion for new drivers. It features comprehensive theory lessons, practice tests, and driving simulations to help you gain confidence before taking your official exam.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('driving-theory-training-europe', 'NDS', 'Driving Theory Training (Europe)', '2009', 'Educational', 'Oximeter', '1', 'Educational', 'Educational and driving simulation.', 'Study for the European driving theory test.', 'A driving theory trainer for various European countries.', 'Driving Theory Training for NDS provides a portable way to study for your driver''s license. Includes multiple-choice questions, hazard perception tips, and mock exams based on European traffic regulations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('drone-tactics-usa', 'NDS', 'Drone Tactics (USA)', '2009', 'Strategy', 'Game Factory', '1', 'Tactical', 'Turn-based strategy with mechs.', 'Lead a squad of insect-themed mechs to victory.', 'A deep tactical RPG featuring customizable mechs.', 'Drone Tactics for NDS is a hidden gem of strategy. Customize your insect-like "Drones" with various weapons, manage your squad on a grid-based battlefield, and experience an engaging story with high-quality tactical combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dropcast-europe-enfrdees', 'NDS', 'Dropcast (Europe) (En,Fr,De,Es)', '2009', 'Arcade', 'Rastersoft', '1', 'Arcade', 'Puzzle and action.', 'Clear the board by matching and dropping blocks.', 'A fast-paced puzzle game with competitive elements.', 'Dropcast for NDS offers an addictive puzzle experience. Match falling blocks to clear the screen and send obstacles to your opponent. Featuring various game modes and a focus on quick reflexes and strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dropcast-usa', 'NDS', 'Dropcast (USA)', '2009', 'Arcade', 'Rastersoft', '1', 'Arcade', 'Puzzle and action.', 'Clear the board by matching and dropping blocks.', 'A fast-paced puzzle game with competitive elements.', 'Dropcast for NDS offers an addictive puzzle experience. Match falling blocks to clear the screen and send obstacles to your opponent. Featuring various game modes and a focus on quick reflexes and strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ds-bimoji-training-japan', 'NDS', 'DS Bimoji Training (Japan)', '2007', 'Educational', 'Nintendo', '1', 'Educational', 'Stylus-based calligraphy practice.', 'Master the art of Japanese beautiful writing (Bimoji).', 'A professional calligraphy trainer using the NDS stylus.', 'DS Bimoji Training transforms your NDS into a digital canvas for Japanese calligraphy. Learn proper stroke order and balance with real-time feedback. Perfect for users looking to improve their handwriting and master traditional Japanese characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ds-bungaku-zenshuu-japan', 'NDS', 'DS Bungaku Zenshuu (Japan)', '2006', 'Educational', 'Nintendo', '1', 'Educational', 'E-book reader with touch navigation.', 'Read classic works of Japanese literature.', 'A digital collection of Japan''s most famous literary works.', 'DS Bungaku Zenshuu offers a library of over 100 classic Japanese novels on one cartridge. Featuring a comfortable vertical reading mode and bookmarking functions, it is the ultimate portable library for fans of traditional Japanese literature.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ds-chueogui-donghwa---touch-ro-puzzle-korea', 'NDS', 'DS Chueogui Donghwa - Touch RO Puzzle (Korea)', '2007', 'Puzzle', 'Digital Touch', '1', 'Puzzle', 'Touch-based puzzle solving.', 'Solve tile and logic puzzles based on fairy tales.', 'A charming puzzle collection inspired by classic folk stories.', 'DS Chueogui Donghwa - Touch RO Puzzle brings beloved fairy tales to life through engaging touch puzzles. Solve colorful logic challenges and progress through illustrated stories in this Korean-exclusive handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ds-de-yomu-series---tezuka-osamu---hi-no-tori---daiikkan-japan', 'NDS', 'DS de Yomu Series - Tezuka Osamu - Hi no Tori - Daiikkan (Japan)', '2009', 'Adventure', 'Nintendo', '1', 'Visual Novel', 'Digital manga reader.', 'Read the first volume of the legendary manga Phoenix.', 'An interactive manga experience of Osamu Tezuka’s masterpiece.', 'Experience Osamu Tezuka''s "Hi no Tori" (Phoenix) on NDS. This digital reader offers high-quality scans of Volume 1, optimized for the dual screens, allowing manga fans to enjoy this philosophical epic anywhere they go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ds-de-yomu-series---tezuka-osamu---hi-no-tori---dainikan-japan', 'NDS', 'DS de Yomu Series - Tezuka Osamu - Hi no Tori - Dainikan (Japan)', '2009', 'Adventure', 'Nintendo', '1', 'Visual Novel', 'Digital manga reader.', 'Read the second volume of the legendary manga Phoenix.', 'An interactive manga experience of Osamu Tezuka’s masterpiece.', 'Experience Osamu Tezuka''s "Hi no Tori" (Phoenix) on NDS. This digital reader offers high-quality scans of Volume 2, optimized for the dual screens, allowing manga fans to enjoy this philosophical epic anywhere they go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ds-de-yomu-series---tezuka-osamu---hi-no-tori---daisankan-japan', 'NDS', 'DS de Yomu Series - Tezuka Osamu - Hi no Tori - Daisankan (Japan)', '2009', 'Adventure', 'Nintendo', '1', 'Visual Novel', 'Digital manga reader.', 'Read the third volume of the legendary manga Phoenix.', 'An interactive manga experience of Osamu Tezuka’s masterpiece.', 'Experience Osamu Tezuka''s "Hi no Tori" (Phoenix) on NDS. This digital reader offers high-quality scans of Volume 3, optimized for the dual screens, allowing manga fans to enjoy this philosophical epic anywhere they go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ds-dengeki-bunko---allison-japan', 'NDS', 'DS Dengeki Bunko - Allison (Japan)', '2008', 'Adventure', 'Kadokawa Shoten', '1', 'Visual Novel', 'Visual novel with decision making.', 'Navigate the story of Allison and make key choices.', 'A light novel adaptation featuring an epic adventure story.', 'DS Dengeki Bunko: Allison brings the popular light novel series to the NDS. Players follow the journey of Allison and Will through beautiful illustrations and branching paths, making it a must-play for fans of immersive storytelling.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ds-dengeki-bunko---inukami!-feat-animation-japan', 'NDS', 'DS Dengeki Bunko - Inukami! feat. Animation (Japan)', '2007', 'Adventure', 'Kadokawa Shoten', '1', 'Visual Novel', 'Visual novel with comedy elements.', 'Interact with characters from the Inukami! series.', 'A hilarious supernatural adventure based on the hit anime.', 'DS Dengeki Bunko: Inukami! feat. Animation offers fans a chance to dive into the chaotic world of Keita and Yoko. Enjoy original scenarios, voiced dialogue, and the signature humor of the anime in this portable visual novel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ds-dengeki-bunko---iriya-no-sora-ufo-no-natsu-japan', 'NDS', 'DS Dengeki Bunko - Iriya no Sora, UFO no Natsu (Japan)', '2007', 'Adventure', 'Kadokawa Shoten', '1', 'Visual Novel', 'Visual novel and mystery.', 'Uncover the secrets of the mysterious girl Iriya.', 'A poignant sci-fi story about a boy and a secret pilot.', 'DS Dengeki Bunko: Iriya no Sora, UFO no Natsu is a touching visual novel on NDS. Follow Naoyuki''s summer encounter with a girl who holds the fate of the world in her hands. Experience a deep, emotional narrative with stunning artwork.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ds-dengeki-bunko---iriya-no-sora-ufo-no-natsu-ii-japan', 'NDS', 'DS Dengeki Bunko - Iriya no Sora, UFO no Natsu II (Japan)', '2008', 'Adventure', 'Kadokawa Shoten', '1', 'Visual Novel', 'Visual novel and mystery.', 'Continue the emotional story of Iriya and Naoyuki.', 'The second part of the acclaimed sci-fi light novel series.', 'DS Dengeki Bunko: Iriya no Sora, UFO no Natsu II concludes the dramatic tale. This sequel offers more branching paths and emotional depth, providing a definitive ending to the mysterious summer story on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ds-dengeki-bunko-adv---baccano!-japan', 'NDS', 'DS Dengeki Bunko ADV - Baccano! (Japan)', '2009', 'Adventure', 'Kadokawa Shoten', '1', 'Visual Novel', 'Tactical visual novel.', 'Navigate the intertwining lives of criminals in Chicago.', 'A unique adventure based on the high-octane Baccano! series.', 'DS Dengeki Bunko ADV: Baccano! brings the chaotic world of 1930s Chicago to NDS. Manage multiple perspectives in this non-linear story, solving mysteries and surviving the underworld in a highly stylized adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ds-gostop-korea', 'NDS', 'DS GoStop (Korea)', '2007', 'Board', 'GameVillage', '2', 'Board Game', 'Card game simulation.', 'Win matches of the traditional Korean card game Go-Stop.', 'A digital version of the popular Korean Hanafuda game.', 'DS GoStop provides a portable and authentic Hanafuda experience. Play the classic Korean "Go-Stop" rules against AI opponents, master the scoring system, and enjoy the strategy of this traditional card game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ds-kageyama-method-dennou-hanpuku---masu-x-masu-hyaku-masu-keisan-japan', 'NDS', 'DS Kageyama Method Dennou Hanpuku - Masu x Masu Hyaku Masu Keisan (Japan)', '2006', 'Educational', 'Nintendo', '1', 'Educational', 'Math training and calculation.', 'Solve 100-cell math grids as quickly as possible.', 'A brain-training game based on the Kageyama Method.', 'DS Kageyama Method: Masu x Masu Hyaku Masu Keisan is designed to improve mental arithmetic. Practice daily with the famous 100-cell calculation method to boost your speed, accuracy, and overall cognitive health.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ds-kageyama-method-dennou-hanpuku---masu-x-masu-pre-hyaku-masu-keisan---hyaku-masu-no-mae-ni-kore-da-yo!-japan', 'NDS', 'DS Kageyama Method Dennou Hanpuku - Masu x Masu Pre-Hyaku Masu Keisan - Hyaku Masu no Mae ni Kore Da yo! (Japan)', '2007', 'Educational', 'Nintendo', '1', 'Educational', 'Introductory math training.', 'Master basic calculations to prepare for harder grids.', 'An entry-level math trainer for younger students or beginners.', 'This "Pre-Hyaku Masu" version of the Kageyama Method focuses on the fundamentals. It offers simplified grids and foundational math exercises to help users build the confidence needed for advanced 100-cell challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ds-kageyama-method-dennou-hanpuku---tadashii-kanji-kakitori-kun---kondo-wa-kanken-taisaku-da-yo!-japan', 'NDS', 'DS Kageyama Method Dennou Hanpuku - Tadashii Kanji Kakitori-kun - Kondo wa Kanken Taisaku Da yo! (Japan)', '2008', 'Educational', 'Nintendo', '1', 'Educational', 'Kanji writing and exam prep.', 'Practice Kanji characters for the Kanken proficiency test.', 'A specialized Kanji training tool for Japanese exams.', 'DS Kageyama Method: Tadashii Kanji Kakitori-kun Kanken Taisaku is the ultimate tool for mastering Japanese characters. With specific modules for the Kanken exam, it tracks your writing accuracy and stroke order.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ds-kageyama-method-dennou-hanpuku---tadashii-kanji-kakitori-kun-japan', 'NDS', 'DS Kageyama Method Dennou Hanpuku - Tadashii Kanji Kakitori-kun (Japan)', '2006', 'Educational', 'Nintendo', '1', 'Educational', 'Kanji writing practice.', 'Learn to write Kanji correctly using the stylus.', 'A comprehensive handwriting trainer for Japanese Kanji.', 'This Kageyama Method title focuses on the beauty and accuracy of Kanji writing. Use the NDS stylus to trace characters, receive instant feedback, and improve your Japanese literacy through repetitive, effective practice.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ds-motte-tabi-ni-deyo---kyoto-japan', 'NDS', 'DS Motte Tabi ni Deyo - Kyoto (Japan)', '2007', 'Travel', 'Nintendo', '1', 'Lifestyle', 'Travel guide and exploration.', 'Plan a trip and learn about the history of Kyoto.', 'An interactive travel guide for Japan''s ancient capital.', 'DS Motte Tabi ni Deyo: Kyoto is more than a game; it''s a digital companion. Explore maps, learn about shrines and temples, and discover local secrets of Kyoto through your NDS before or during your real-world visit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ds-nishimura-kyotaro-suspense-2-shin-tantei-series---kanazawa-hakodate-gokkan-no-kyoukoku---fukushuu-no-kage-japan', 'NDS', 'DS Nishimura Kyotaro Suspense 2 Shin Tantei Series - Kanazawa, Hakodate, Gokkan no Kyoukoku - Fukushuu no Kage (Japan)', '2008', 'Adventure', 'WorkJam', '1', 'Adventure', 'Mystery and detective adventure.', 'Solve a series of murders across various Japanese cities.', 'A suspenseful crime-solving game from the famous author.', 'In this Nishimura Kyotaro Suspense sequel, players investigate dark mysteries in Kanazawa and Hakodate. Collect evidence, interrogate suspects, and use logic to catch the killer in this gripping NDS adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ds-nishimura-kyotaro-suspense-shin-tantei-series---kyoto-atami-zekkai-no-kotou---satsui-no-wana-japan', 'NDS', 'DS Nishimura Kyotaro Suspense Shin Tantei Series - Kyoto, Atami, Zekkai no Kotou - Satsui no Wana (Japan)', '2007', 'Adventure', 'WorkJam', '1', 'Adventure', 'Mystery and detective adventure.', 'Uncover the truth behind a deadly trap in Kyoto and Atami.', 'A classic Japanese detective mystery with deep investigative gameplay.', 'DS Nishimura Kyotaro Suspense Shin Tantei Series puts you in the role of a detective. Explore famous Japanese locations, piece together clues, and navigate a web of betrayal in this atmospheric crime thriller.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ds-puzzler---nanpure-fan-&-oekaki-logic---wi-fi-taiou-japan', 'NDS', 'DS Puzzler - Nanpure Fan & Oekaki Logic - Wi-Fi Taiou (Japan)', '2007', 'Puzzle', 'Hudson Soft', '1', 'Puzzle', 'Logic puzzle collection.', 'Solve Sudoku and Oekaki logic puzzles with Wi-Fi features.', 'A massive collection of Sudoku and picture-logic puzzles.', 'DS Puzzler: Nanpure Fan & Oekaki Logic offers endless hours of brain-teasing fun. Solve classic Sudoku and picture-grid puzzles, and use the Wi-Fi connection to download new challenges or compete with others.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ds-puzzler---nanpure-fan-&-oekaki-logic-japan', 'NDS', 'DS Puzzler - Nanpure Fan & Oekaki Logic (Japan)', '2006', 'Puzzle', 'Hudson Soft', '1', 'Puzzle', 'Logic puzzle collection.', 'Complete various Sudoku and logic-based puzzles.', 'A standard collection of popular Japanese paper puzzles.', 'This edition of DS Puzzler focuses on pure gameplay. With hundreds of Sudoku (Nanpure) and Oekaki Logic levels, it provides the perfect portable experience for fans of traditional Japanese logic puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ds-rakubiki-jiten-japan', 'NDS', 'DS Rakubiki Jiten (Japan)', '2007', 'Reference', 'Nintendo', '1', 'Reference', 'Digital dictionary and translation.', 'Translate words and look up Kanji definitions.', 'A powerful multilingual dictionary for NDS.', 'DS Rakubiki Jiten is an essential tool for students. It features comprehensive Japanese, English, and Kanji dictionaries with touch-screen input, making it easy to look up words by writing them directly.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ds-teku-teku-nikki---walking-&-diet-diary-japan', 'NDS', 'DS Teku Teku Nikki - Walking & Diet Diary (Japan)', '2007', 'Fitness', 'Nintendo', '1', 'Lifestyle', 'Health and fitness tracking.', 'Record daily steps and manage weight loss goals.', 'A personal walking and diet diary for the NDS.', 'DS Teku Teku Nikki is your portable health coach. Log your daily activity, track calories burned, and visualize your weight loss progress over time using the interactive charts and diary entries.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ds-uranai-seikatsu-japan', 'NDS', 'DS Uranai Seikatsu (Japan)', '2008', 'Lifestyle', 'Nintendo', '1', 'Lifestyle', 'Fortune telling and astrology.', 'Discover your daily fortune and compatibility.', 'A lifestyle app for daily horoscopes and divination.', 'DS Uranai Seikatsu offers a variety of fortune-telling methods, from Western astrology to traditional Japanese divination. Check your daily luck, career prospects, and romantic compatibility in this fun lifestyle title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ds-vitamin---widaehan-bapsang---malhaneun!-geongangyori-giljabi-korea', 'NDS', 'DS Vitamin - Widaehan Bapsang - Malhaneun! Geongangyori Giljabi (Korea)', '2008', 'Lifestyle', 'Nintendo', '1', 'Lifestyle', 'Cooking and health guide.', 'Learn to cook healthy meals through voiced instructions.', 'A Korean healthy cooking guide with voice recognition.', 'DS Vitamin: Widaehan Bapsang is an interactive cookbook. It guides you through healthy Korean recipes with voice prompts, allowing you to cook hands-free while learning about the nutritional benefits of your food.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ds-yamamura-misa-suspense---maiko-kogiku-kisha-catherine-sougiya-ishihara-akiko---koto-ni-mau-hana-sanrin---kyoto-satsujin-jiken-file-japan', 'NDS', 'DS Yamamura Misa Suspense - Maiko Kogiku, Kisha Catherine, Sougiya Ishihara Akiko - Koto ni Mau Hana Sanrin - Kyoto Satsujin Jiken File (Japan)', '2007', 'Adventure', 'WorkJam', '1', 'Adventure', 'Mystery and investigation.', 'Solve murder cases featuring iconic suspense characters.', 'A detective adventure based on popular Japanese TV mysteries.', 'DS Yamamura Misa Suspense brings three famous detective series to one game. Investigate murders in the historic streets of Kyoto, interview witnesses, and solve the "Kyoto Murder Files" using your NDS stylus.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ds-yukemuri-suspense-series---free-writer-tachibana-maki---touyako-nanatsu-no-yu-okuyu-no-sato---shuzai-techou-japan', 'NDS', 'DS Yukemuri Suspense Series - Free Writer Tachibana Maki - Touyako, Nanatsu no Yu, Okuyu no Sato - Shuzai Techou (Japan)', '2008', 'Adventure', 'WorkJam', '1', 'Adventure', 'Mystery and investigation.', 'Solve a travel-writing mystery in a hot spring resort.', 'A suspenseful adventure following a freelance writer.', 'Join Tachibana Maki in DS Yukemuri Suspense Series as she investigates a crime at a snowy resort. Explore hot spring locations, take notes in your reporter''s notebook, and solve the mystery behind the "Seven Springs."');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ds-pico-series---sanrio-no-party-e-ikou!---oryouri-oshare-okaimono-japan', 'NDS', 'DS-PICO Series - Sanrio no Party e Ikou! - Oryouri, Oshare, Okaimono (Japan)', '2007', 'Adventure', 'WorkJam', '1', 'Adventure', 'Educational mini-games.', 'Complete various tasks with Sanrio characters.', 'A fun educational game featuring Hello Kitty and friends.', 'DS-PICO Series: Sanrio no Party e Ikou! is perfect for younger players. Join Hello Kitty for cooking, shopping, and dressing up through simple touch-screen mini-games designed to teach basic skills in a fun way.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dtm-race-driver-3---create-&-race-germany-enfrdeesit', 'NDS', 'DTM Race Driver 3 - Create & Race (Germany) (En,Fr,De,Es,It)', '2008', 'Party', 'Sanrio', '4', 'Party', 'Professional circuit racing.', 'Win championships and create custom tracks.', 'A realistic racing simulator with track-editing features.', 'DTM Race Driver 3: Create & Race brings professional touring car racing to NDS. Experience realistic physics, multiple race modes, and the unique ability to design your own tracks and share them with friends.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ducati-moto-europe-enfrdeesit', 'NDS', 'Ducati Moto (Europe) (En,Fr,De,Es,It)', '2006', 'Racing', 'Codemasters', '1', 'Racing', 'Motorcycle racing.', 'Win races and upgrade your Ducati motorcycles.', 'High-speed motorcycle racing featuring official Ducati bikes.', 'Ducati Moto offers an authentic biking experience on NDS. Ride iconic models like the Monster or the Desmosedici, compete in international circuits, and customize your bikes for maximum performance on the track.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ducati-moto-usa', 'NDS', 'Ducati Moto (USA)', '2007', 'Racing', 'Opus', '1', 'Racing', 'Motorcycle racing.', 'Win races and upgrade your Ducati motorcycles.', 'High-speed motorcycle racing featuring official Ducati bikes.', 'Ducati Moto offers an authentic biking experience on NDS. Ride iconic models like the Monster or the Desmosedici, compete in international circuits, and customize your bikes for maximum performance on the track.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('duel-love---koisuru-otome-wa-shouri-no-megami-japan', 'NDS', 'Duel Love - Koisuru Otome wa Shouri no Megami (Japan)', '2010', 'Visual Novel', 'Nintendo', '1', 'Romance', 'Dating simulation and rhythm.', 'Win the heart of your crush through mini-games.', 'A unique romance game for girls with "physical" interaction.', 'Duel Love: Koisuru Otome wa Shouri no Megami is a romantic adventure on NDS. Build relationships with handsome athletes, support them in their matches, and use the stylus in unique mini-games to win their affection.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('duke-nukem---critical-mass-europe-enfrdeesit', 'NDS', 'Duke Nukem - Critical Mass (Europe) (En,Fr,De,Es,It)', '2009', 'Action', 'Snakebyte', '1', 'Action', 'Third-person shooter and platforming.', 'Defeat alien forces and save the future.', 'An action-packed shooter featuring the iconic Duke Nukem.', 'Duke Nukem: Critical Mass brings classic run-and-gun action to the NDS. Fight through multiple eras, upgrade your weaponry, and take down massive bosses in this portable entry of the legendary shooter franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dun-dam---dungeons-&-dam-japan', 'NDS', 'Dun-Dam - Dungeons & Dam (Japan)', '2008', 'Action', 'Nintendo', '1', 'Action', 'Strategic dungeon defense and RPG.', 'Protect the village by building and managing dungeons.', 'A unique blend of town management and dungeon defense.', 'Dun-Dam: Dungeons & Dam challenges players to balance village life with strategic combat. Build intricate dungeons to trap monsters and protect your people in this innovative Japanese tactical RPG for the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dungeon-explorer---jashin-no-ryouiki-japan', 'NDS', 'Dungeon Explorer - Jashin no Ryouiki (Japan)', '2007', 'Action RPG', 'Hudson Soft', '1', 'Action RPG', 'Action RPG and dungeon crawling.', 'Explore dark ruins to defeat ancient evil deities.', 'A classic top-down dungeon crawler with multiplayer support.', 'Dungeon Explorer: Jashin no Ryouiki offers deep RPG customization on NDS. Choose your class, delve into dangerous labyrinths, and enjoy cooperative gameplay as you hunt for legendary gear and fight powerful gods.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dungeon-explorer---warriors-of-ancient-arts-usa', 'NDS', 'Dungeon Explorer - Warriors of Ancient Arts (USA)', '2007', 'Action RPG', 'Hudson Soft', '1', 'Action RPG', 'Action RPG and dungeon crawling.', 'Explore dark ruins to defeat ancient evil deities.', 'A classic top-down dungeon crawler with multiplayer support.', 'Dungeon Explorer: Warriors of Ancient Arts brings high-fantasy action to your NDS. Master different combat styles, upgrade your arts, and team up with friends to conquer challenging dungeons and mythical beasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dungeon-explorer-europe-enfrdeesit', 'NDS', 'Dungeon Explorer (Europe) (En,Fr,De,Es,It)', '2007', 'Action RPG', 'Hudson Soft', '1', 'Action RPG', 'Action RPG and dungeon crawling.', 'Explore dark ruins to defeat ancient evil deities.', 'A classic top-down dungeon crawler with multiplayer support.', 'Dungeon Explorer for NDS is a definitive handheld action RPG. Navigate trap-filled corridors, battle hordes of monsters, and develop your hero''s skills in a quest to restore peace to a land plagued by darkness.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dungeon-maker---mahou-no-shovel-to-chiisana-yuusha-japan', 'NDS', 'Dungeon Maker - Mahou no Shovel to Chiisana Yuusha (Japan)', '2008', 'Action RPG', 'Global A Entertainment', '1', 'Action RPG', 'Creative dungeon building and RPG.', 'Design a dungeon to lure and defeat specific monsters.', 'A creative simulation game where you build your own dungeons.', 'Dungeon Maker (Mahou no Shovel) lets you become an architect of evil. Use your magical shovel to dig corridors and rooms, place bait for monsters, and then dive in to clear them out and collect rare loot on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dungeon-maker-europe-enfrdeesit', 'NDS', 'Dungeon Maker (Europe) (En,Fr,De,Es,It)', '2008', 'Action RPG', 'Global A Entertainment', '1', 'Action RPG', 'Creative dungeon building and RPG.', 'Design a dungeon to lure and defeat specific monsters.', 'A creative simulation game where you build your own dungeons.', 'Dungeon Maker for NDS turns traditional RPGs on their head. Instead of exploring pre-made maps, you design the layout yourself to attract specific enemies. A perfect mix of strategy, building, and classic monster hunting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dungeon-of-windaria-japan', 'NDS', 'Dungeon of Windaria (Japan)', '2008', 'RPG', 'Success', '1', 'Turn-based', 'Top-down dungeon exploration.', 'Navigate through the mysterious dungeons of Windaria.', 'A classic-style dungeon crawler based on the Windaria universe.', 'Dungeon of Windaria provides a nostalgic RPG experience on NDS. Explore randomly generated floors, manage your inventory carefully, and survive the perils of the deep in this engaging Japanese dungeon adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dungeon-raiders-europe-enfrdeesit', 'NDS', 'Dungeon Raiders (Europe) (En,Fr,De,Es,It)', '2009', 'Action', 'SouthPeak Games', '1', 'Action', 'Tactical puzzle and adventure.', 'Navigate dangerous rooms and collect treasures.', 'A grid-based puzzle adventure set in a fantasy dungeon.', 'Dungeon Raiders on NDS combines logic and adventure. Use your stylus to navigate through trap-ridden levels, solve environmental puzzles, and outsmart enemies in this clever take on the dungeon-crawling genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dynasty-warriors-ds---fighters-battle-europe-enfrdeesit', 'NDS', 'Dynasty Warriors DS - Fighter''s Battle (Europe) (En,Fr,De,Es,It)', '2009', 'Action', 'Koei', '1', 'Action', 'Tactical card-based action.', 'Defeat rival generals using a deck of fighter cards.', 'A strategic spin-off of the famous Dynasty Warriors series.', 'Dynasty Warriors DS: Fighter''s Battle brings massive combat to NDS with a tactical twist. Build a deck of powerful warriors, capture enemy bases, and use strategic card timing to dominate the battlefield and unify China.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dynasty-warriors-ds---fighters-battle-usa', 'NDS', 'Dynasty Warriors DS - Fighter''s Battle (USA)', '2009', 'Action', 'Koei', '1', 'Action', 'Tactical card-based action.', 'Defeat rival generals using a deck of fighter cards.', 'A strategic spin-off of the famous Dynasty Warriors series.', 'Dynasty Warriors DS: Fighter''s Battle brings massive combat to NDS with a tactical twist. Build a deck of powerful warriors, capture enemy bases, and use strategic card timing to dominate the battlefield and unify China.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('e=m6-defi-cerebral-france', 'NDS', 'E=M6 Defi Cerebral (France)', '2008', 'Puzzle', 'Mindscape', '1', 'Brain Training', 'Educational trivia and brain training.', 'Answer science and logic questions to win the challenge.', 'A French educational game based on the popular science show.', 'E=M6 Defi Cerebral is the ultimate brain teaser for NDS. Based on the hit TV program, it challenges your knowledge of science, history, and logic through interactive quizzes and fun mini-games designed to educate and entertain.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ea-playground-europe-enfrdeesit', 'NDS', 'EA Playground (Europe) (En,Fr,De,Es,It)', '2007', 'Party', 'EA Canada', '4', 'Party', 'Mini-game collection and exploration.', 'Master playground games and earn stickers and rank.', 'A fun collection of classic outdoor games and sports.', 'EA Playground turns your NDS into a digital park. Compete in Dodgeball, Tetherball, and Kart Racing to become the king of the playground. Unlock new areas and items in this vibrant, family-friendly social experience.');
