INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('easy-learning---discover-our-world-europe-enfrdeesit', 'NDS', 'Easy Learning - Discover Our World (Europe) (En,Fr,De,Es,It)', '2009', 'Educational', 'DTI', '1', 'Educational', 'Educational and interactive learning.', 'Explore different cultures and geography through puzzles.', 'A children''s educational game about the world around us.', 'Easy Learning: Discover Our World makes geography fun on NDS. Kids can learn about continents, animals, and cultures through colorful mini-games and interactive maps, fostering a sense of curiosity about the planet.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('easy-piano---learn-play-&-compose-europe-enfrdeesit', 'NDS', 'Easy Piano - Learn, Play & Compose (Europe) (En,Fr,De,Es,It)', '2008', 'Educational', 'Easy Interactive', '1', 'Music', 'Music simulation and education.', 'Learn to play the piano and compose original songs.', 'A comprehensive piano trainer including a keyboard peripheral.', 'Easy Piano for NDS is a complete music school in your pocket. Use the included 8-key peripheral to learn real songs, practice scales, and even compose your own tracks. Perfect for beginners looking to learn the basics of music.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('easy-piano-usa-enfres', 'NDS', 'Easy Piano (USA) (En,Fr,Es)', '2009', 'Educational', 'Easy Interactive', '1', 'Music', 'Music simulation and education.', 'Learn to play the piano and compose original songs.', 'A comprehensive piano trainer including a keyboard peripheral.', 'Easy Piano for NDS is a complete music school in your pocket. Use the included 8-key peripheral to learn real songs, practice scales, and even compose your own tracks. Perfect for beginners looking to learn the basics of music.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eco-creatures---save-the-forest-usa', 'NDS', 'Eco-Creatures - Save the Forest (USA)', '2009', 'Adventure', 'Spike', '1', 'Adventure', 'Real-time strategy and environmental sim.', 'Lead small creatures to protect the forest from pollution.', 'A unique RTS where you control nature-dwelling spirits.', 'Eco-Creatures: Save the Forest tasks you with defending the environment on NDS. Control a variety of "Ecolis" spirits, manage resources, and fight back against industrial machines to restore the natural balance of your woodland home.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ecolis---aoi-umi-to-ugoku-shima-japan', 'NDS', 'Ecolis - Aoi Umi to Ugoku Shima (Japan)', '2007', 'Adventure', 'Prope', '1', 'Adventure', 'Real-time strategy and environmental sim.', 'Lead small creatures to protect the forest from pollution.', 'A unique RTS where you control nature-dwelling spirits.', 'Ecolis: Aoi Umi to Ugoku Shima expands the environmental strategy gameplay on NDS. Lead your spirits across new island environments, solve puzzles, and use the power of nature to overcome man-made threats in this charming sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ecolis---save-the-forest-europe-enfrdeesit', 'NDS', 'Ecolis - Save the Forest (Europe) (En,Fr,De,Es,It)', '2009', 'Adventure', 'Prope', '1', 'Adventure', 'Real-time strategy and environmental sim.', 'Lead small creatures to protect the forest from pollution.', 'A unique RTS where you control nature-dwelling spirits.', 'Ecolis: Save the Forest is an engaging real-time strategy game for NDS. Train and command tiny creatures to plant trees and clean up toxic waste, blending fun tactical gameplay with a positive message about environmentalism.');
