INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ed-edd-n-eddy---scam-of-the-century-europe-enfrdeesit', 'NDS', 'Ed, Edd n Eddy - Scam of the Century (Europe) (En,Fr,De,Es,It)', '2007', 'Platform', 'Artificial Mind & Movement', '1', 'Cartoon', 'Side-scrolling platformer and action.', 'Help the Eds recover their stolen scam items.', 'A wacky adventure based on the Cartoon Network show.', 'Ed, Edd n Eddy: Scam of the Century captures the humor of the show on NDS. Switch between the three Eds to use their unique abilities, avoid the Kanker sisters, and navigate school-life chaos in this entertaining platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ed-edd-n-eddy---scam-of-the-century-usa', 'NDS', 'Ed, Edd n Eddy - Scam of the Century (USA)', '2007', 'Platform', 'Artificial Mind & Movement', '1', 'Cartoon', 'Side-scrolling platformer and action.', 'Help the Eds recover their stolen scam items.', 'A wacky adventure based on the Cartoon Network show.', 'Ed, Edd n Eddy: Scam of the Century captures the humor of the show on NDS. Switch between the three Eds to use their unique abilities, avoid the Kanker sisters, and navigate school-life chaos in this entertaining platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eds-farm-europe-enfrdeesit', 'NDS', 'Ed''s Farm (Europe) (En,Fr,De,Es,It)', '2009', 'Simulation', 'Neko Entertainment', '1', 'Casual', 'Farm management and mini-games.', 'Manage a successful farm and care for the animals.', 'A lighthearted farming simulation for younger players.', 'Ed''s Farm on NDS allows you to experience life in the countryside. Tend to your crops, feed the animals, and complete various farming chores through simple touch-screen mini-games in this relaxing and colorful sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('edamoto-naomi-no-shiawase-kitchen---kakushi-aji-wa-anata-ga-kimete-ne-japan', 'NDS', 'Edamoto Naomi no Shiawase Kitchen - Kakushi Aji wa Anata ga Kimete ne (Japan)', '2008', 'Simulation', 'Nintendo', '1', 'Cooking', 'Cooking simulation and recipes.', 'Learn new recipes and master cooking techniques.', 'An interactive Japanese cookbook and cooking simulator.', 'Edamoto Naomi no Shiawase Kitchen provides professional culinary guidance on your NDS. Follow step-by-step recipes from the famous chef, learn "secret ingredients," and practice your skills in a virtual kitchen setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('edo-bunka-rekishi-kentei-ds-japan', 'NDS', 'Edo Bunka Rekishi Kentei DS (Japan)', '2009', 'Educational', 'Nintendo', '1', 'Educational', 'Educational trivia and history.', 'Study and pass the Edo culture and history exam.', 'A specialized educational tool for Japanese history buffs.', 'Edo Bunka Rekishi Kentei DS is designed to help users master the history of the Edo period. Featuring thousands of questions and detailed explanations, it''s the perfect study guide for the official Japanese history certification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('edogawa-ranpo-no-kaijin-nijuu-mensou-ds-japan', 'NDS', 'Edogawa Ranpo no Kaijin Nijuu Mensou DS (Japan)', '2008', 'Adventure', 'Nintendo', '1', 'Visual Novel', 'Mystery and detective adventure.', 'Solve cases and track down the elusive Fiend with 20 Faces.', 'A detective game based on the works of Ranpo Edogawa.', 'Step into the world of Japanese mystery with Edogawa Ranpo no Kaijin Nijuu Mensou DS. Interrogate suspects, search for clues, and solve complex cases inspired by the legendary author''s most famous detective stories.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('egg-monster-hero-japan', 'NDS', 'Egg Monster Hero (Japan)', '2009', 'RPG', 'Jupiter', '1', 'Turn-based', 'Strategy and monster battling.', 'Summon and command "Egg Monsters" to win battles.', 'A comedic strategy RPG from the makers of Final Fantasy.', 'Egg Monster Hero brings zany, fast-paced tactical combat to the NDS. Use the touch screen to draw shapes and summon bizarre monsters from eggs to fight your enemies in this colorful and humorous adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('egokoro-kyoushitsu-ds-japan-ndsi-enhanced', 'NDS', 'Egokoro Kyoushitsu DS (Japan) (NDSi Enhanced)', '2009', 'Educational', 'Nintendo', '1', 'Art', 'Art training and digital painting.', 'Learn real-world drawing and painting techniques.', 'A professional art instructor for the NDS.', 'Egokoro Kyoushitsu DS (Art Academy) turns your NDS into a portable studio. Follow step-by-step lessons on shading, color theory, and perspective, using the stylus as a brush to create stunning digital artwork.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eibun-tadoku-ds---sekai-no-bungaku-senshuu-japan', 'NDS', 'Eibun Tadoku DS - Sekai no Bungaku Senshuu (Japan)', '2008', 'Educational', 'Nintendo', '1', 'Educational', 'English language reading and literature.', 'Improve English skills by reading world literature.', 'A language learning tool featuring classic English novels.', 'Eibun Tadoku DS: Sekai no Bungaku Senshuu is an educational reader for NDS. It features a selection of classic world literature in English, designed to help Japanese speakers improve their vocabulary and comprehension through extensive reading.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eibun-tadoku-ds---sekai-no-meisaku-douwa-japan', 'NDS', 'Eibun Tadoku DS - Sekai no Meisaku Douwa (Japan)', '2008', 'Educational', 'Nintendo', '1', 'Educational', 'English language reading and literature.', 'Improve English skills by reading famous fairy tales.', 'A language learning tool featuring global folk stories.', 'Eibun Tadoku DS: Sekai no Meisaku Douwa helps users learn English through familiar stories. Read "Cinderella," "Peter Pan," and other classics with interactive dictionary support, making English study engaging and accessible on NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eigo-de-tabisuru---little-charo-japan', 'NDS', 'Eigo de Tabisuru - Little Charo (Japan)', '2008', 'Educational', 'Nintendo', '1', 'Educational', 'Adventure and language learning.', 'Follow Charo the dog and learn English through his journey.', 'An interactive adventure for English learners based on the NHK show.', 'Eigo de Tabisuru: Little Charo brings the beloved NHK character to NDS. Follow the heartwarming story of a lost dog in New York while improving your English listening and vocabulary through interactive episodes and mini-games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eigo-ga-nigate-na-otona-no-ds-training---eigo-zuke-japan', 'NDS', 'Eigo ga Nigate na Otona no DS Training - Eigo Zuke (Japan)', '2006', 'Educational', 'Nintendo', '1', 'Educational', 'Dictation and English training.', 'Listen to English phrases and write them using the stylus.', 'A popular brain-training style game for learning English.', 'Eigo Zuke is the definitive English training tool for NDS. Using a simple dictation method, users listen to native speakers and write sentences to improve their hearing and spelling, featuring levels for all adult learners.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eigo-ga-nigate-na-otona-no-ds-training---eigo-zuke-japan-rev-1', 'NDS', 'Eigo ga Nigate na Otona no DS Training - Eigo Zuke (Japan) (Rev 1)', '2006', 'Educational', 'Nintendo', '1', 'Educational', 'Dictation and English training.', 'Listen to English phrases and write them using the stylus.', 'A popular brain-training style game for learning English.', 'Eigo Zuke is the definitive English training tool for NDS. Using a simple dictation method, users listen to native speakers and write sentences to improve their hearing and spelling, featuring levels for all adult learners.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eigo-ga-nigate-na-otona-no-ds-training---motto-eigo-zuke-japan', 'NDS', 'Eigo ga Nigate na Otona no DS Training - Motto Eigo Zuke (Japan)', '2007', 'Educational', 'Nintendo', '1', 'Educational', 'Advanced dictation and English training.', 'Master complex English conversations and phrases.', 'The sequel to the hit English trainer with more content.', 'Motto Eigo Zuke takes your English skills further on NDS. This sequel introduces more conversational English, slang, and cultural nuances, providing a deeper challenge for those who mastered the first training game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eigo-o-taberu-fushigi-na-ikimono---marsh-japan', 'NDS', 'Eigo o Taberu Fushigi na Ikimono - Marsh (Japan)', '2009', 'Educational', 'Nintendo', '1', 'Educational', 'Simulation and language learning.', 'Feed the creature "Marsh" by correctly identifying English words.', 'A unique pet-sim that uses English vocabulary as food.', 'Eigo o Taberu Fushigi na Ikimono: Marsh makes vocabulary building fun. Interact with a mysterious creature and help it grow by solving English word puzzles, creating an engaging daily habit for language students on NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eigyoudou-the-japan', 'NDS', 'Eigyoudou, The (Japan)', '2009', 'Simulation', 'Success', '1', 'Business', 'Business simulation and strategy.', 'Master the art of sales and business negotiations.', 'A professional simulation game focused on sales techniques.', 'The Eigyoudou is a unique NDS title that simulates the life of a Japanese salesperson. Learn body language, negotiation tactics, and business etiquette through realistic scenarios designed to sharpen your professional skills.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eijukugo-target-1000-ds-japan', 'NDS', 'Eijukugo Target 1000 DS (Japan)', '2007', 'Educational', 'Nintendo', '1', 'Educational', 'Vocabulary flashcards and testing.', 'Memorize 1,000 essential English idioms for exams.', 'A specialized training tool for mastering English idioms.', 'Eijukugo Target 1000 DS is an efficient study aid for Japanese students. Focus on the most common English idioms found in entrance exams with interactive flashcards, quizzes, and progress tracking on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eiken-ds-japan', 'NDS', 'Eiken DS (Japan)', '2006', 'Educational', 'Nintendo', '1', 'Educational', 'Exam preparation and testing.', 'Study for and pass the Eiken English proficiency exam.', 'A comprehensive study guide for the Eiken certification.', 'Eiken DS provides all the tools needed to ace the popular Japanese English test. Practice listening, reading, and vocabulary with mock exams and specialized drills tailored to various proficiency levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eiken-ds-training-japan', 'NDS', 'Eiken DS Training (Japan)', '2007', 'Educational', 'Nintendo', '1', 'Educational', 'Drills and practice tests.', 'Improve English proficiency through repetitive training.', 'An educational trainer focused on Eiken test success.', 'Eiken DS Training offers a focused approach to language learning. Use the dual screens to practice writing and listening, with specific feedback to help you overcome your weaknesses before the official Eiken exam.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eiken-kakomondai-shuuroku---eiken-ds-2-deluxe-japan', 'NDS', 'Eiken Kakomondai Shuuroku - Eiken DS 2 Deluxe (Japan)', '2008', 'Educational', 'Nintendo', '1', 'Educational', 'Exam prep and past paper drills.', 'Complete past Eiken exam questions to build confidence.', 'A deluxe edition featuring extensive past exam papers.', 'Eiken DS 2 Deluxe is the ultimate resource for students. It includes a vast collection of real past questions and specialized vocabulary lists, making it the most complete Eiken preparation tool available on NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eiken-ou---2-kyuu-hen-japan', 'NDS', 'Eiken-ou - 2-kyuu Hen (Japan)', '2009', 'Educational', 'Nintendo', '1', 'Educational', 'Level-specific exam training.', 'Pass the Grade 2 Eiken English proficiency test.', 'Focused training for the Eiken Grade 2 certification.', 'Eiken-ou: 2-kyuu Hen focuses specifically on the requirements for Grade 2. Master the necessary grammar, advanced vocabulary, and listening comprehension skills needed to succeed at this specific certification level.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eiken-ou---3-kyuu-hen-japan', 'NDS', 'Eiken-ou - 3-kyuu Hen (Japan)', '2009', 'Educational', 'Nintendo', '1', 'Educational', 'Level-specific exam training.', 'Pass the Grade 3 Eiken English proficiency test.', 'Focused training for the Eiken Grade 3 certification.', 'Eiken-ou: 3-kyuu Hen is designed for intermediate English learners. This NDS title provides targeted practice for the Grade 3 Eiken exam, helping students bridge the gap between basic and advanced English skills.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eiken-ou---4-kyuu-hen-japan', 'NDS', 'Eiken-ou - 4-kyuu Hen (Japan)', '2009', 'Educational', 'Nintendo', '1', 'Educational', 'Level-specific exam training.', 'Pass the Grade 4 Eiken English proficiency test.', 'Focused training for the Eiken Grade 4 certification.', 'Eiken-ou: 4-kyuu Hen is perfect for beginners starting their Eiken journey. It covers the fundamental English vocabulary and grammar required for Grade 4 through interactive lessons and simple mock tests.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eiken-ou---jun-2-kyuu-hen-japan', 'NDS', 'Eiken-ou - Jun-2-kyuu Hen (Japan)', '2009', 'Educational', 'Nintendo', '1', 'Educational', 'Level-specific exam training.', 'Pass the Pre-2 Grade Eiken English proficiency test.', 'Focused training for the Eiken Pre-2 certification.', 'Eiken-ou: Jun-2-kyuu Hen targets the critical intermediate step in English proficiency. Practice the specific sentence structures and listening patterns required to clear the Pre-2 Grade exam with ease.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eikoh-seminar-koushiki-ds-kyouzai---chuugaku-eitango---eitan-zamurai-ds-japan', 'NDS', 'Eikoh Seminar Koushiki DS Kyouzai - Chuugaku Eitango - Eitan Zamurai DS (Japan)', '2008', 'Educational', 'Nintendo', '1', 'Educational', 'Samurai-themed word battling.', 'Defeat enemies by correctly translating middle school vocabulary.', 'A fun educational game that blends samurai action with English.', 'Eitan Zamurai DS makes studying middle school English vocabulary an adventure. Battle through Feudal Japan by solving word puzzles, making rote memorization an engaging and competitive experience on NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eikoh-seminar-koushiki-ds-kyouzai---koukou-eitango---eitan-zamurai-ds-japan', 'NDS', 'Eikoh Seminar Koushiki DS Kyouzai - Koukou Eitango - Eitan Zamurai DS (Japan)', '2008', 'Educational', 'Nintendo', '1', 'Educational', 'Samurai-themed word battling.', 'Defeat enemies by correctly translating high school vocabulary.', 'An action-based vocabulary trainer for high school students.', 'Eitan Zamurai DS for high schoolers increases the challenge with advanced vocabulary. Use your "sword" of knowledge to defeat rivals and master the words needed for university entrance exams.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eikoh-seminar-koushiki-ds-kyouzai---shougakkou-eitango---eitan-zamurai-ds-japan', 'NDS', 'Eikoh Seminar Koushiki DS Kyouzai - Shougakkou Eitango - Eitan Zamurai DS (Japan)', '2008', 'Educational', 'Nintendo', '1', 'Educational', 'Samurai-themed word battling.', 'Defeat enemies by correctly translating elementary vocabulary.', 'A child-friendly English trainer with a samurai twist.', 'Eitan Zamurai DS for elementary students introduces basic English in a fun way. Kids can play as a young samurai, learning essential words and phrases while progressing through a colorful historical story.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eindeloos-backgammon-netherlands', 'NDS', 'Eindeloos Backgammon (Netherlands)', '2007', 'Board', 'Game Factory', '2', 'Board Game', 'Board game simulation.', 'Win matches of the classic game of Backgammon.', 'A portable version of the traditional Backgammon board game.', 'Eindeloos Backgammon offers a clean and intuitive way to play this ancient strategy game on NDS. Compete against the computer or friends, featuring customizable rules and different difficulty levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eindeloos-games-top-10-netherlands', 'NDS', 'Eindeloos Games Top 10 (Netherlands)', '2008', 'Board', 'Game Factory', '4', 'Board Game', 'Collection of classic board and card games.', 'Master ten different popular table-top games.', 'A 10-in-1 collection of classic games for casual play.', 'Eindeloos Games Top 10 brings a variety of favorites to your NDS. From Chess and Checkers to various card games, this collection is perfect for quick gaming sessions and classic entertainment on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eindeloos-mahjong-netherlands-ennl', 'NDS', 'Eindeloos Mahjong (Netherlands) (En,Nl)', '2008', 'Board', 'Game Factory', '4', 'Board Game', 'Tile-matching puzzle.', 'Clear the board by matching identical Mahjong tiles.', 'A relaxing digital version of the classic Mahjong Solitaire.', 'Eindeloos Mahjong provides endless relaxation on NDS. With multiple tile sets and layouts, players can enjoy the meditative process of matching tiles while trying to beat their high scores in this portable puzzle classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eindeloos-mahjong-2---een-reis-om-de-wereld-netherlands', 'NDS', 'Eindeloos Mahjong 2 - Een Reis om de Wereld (Netherlands)', '2009', 'Board', 'Game Factory', '4', 'Board Game', 'Tile-matching and exploration.', 'Solve Mahjong puzzles while traveling around the virtual world.', 'An expanded Mahjong sequel with a global travel theme.', 'Eindeloos Mahjong 2 takes the puzzle experience further. Unlock new locations across the globe by clearing boards, featuring beautiful backgrounds and more challenging tile arrangements than the original.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eindeloos-patience-netherlands', 'NDS', 'Eindeloos Patience (Netherlands)', '2007', 'Board', 'Game Factory', '2', 'Board Game', 'Card game simulation.', 'Clear the deck in various modes of Solitaire.', 'A comprehensive collection of Solitaire (Patience) card games.', 'Eindeloos Patience is the ultimate NDS companion for card game lovers. Featuring classic Klondike and other popular variants, it offers a smooth touch-screen interface for the perfect portable Solitaire experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eitango-target-1900-ds-japan', 'NDS', 'Eitango Target 1900 DS (Japan)', '2009', 'Educational', 'Nintendo', '1', 'Educational', 'Vocabulary flashcards and testing.', 'Memorize 1,900 essential English words for university exams.', 'A high-level vocabulary trainer based on the famous book.', 'Eitango Target 1900 DS is a must-have for Japanese high school students. It digitizes the famous "Target" book series, offering smart tracking to focus on the words you find most difficult to remember.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eiyuu-senki---laevatein-japan', 'NDS', 'Eiyuu Senki - Laevatein (Japan)', '2011', 'RPG', 'Tenco', '1', 'Turn-based', 'Strategy RPG and card battling.', 'Use magical swords to battle enemies in a fantasy world.', 'A tactical RPG featuring personified legendary weapons.', 'Eiyuu Senki: Laevatein combines deep strategy with high-fantasy storytelling. Command heroes and utilize the power of legendary blades in grid-based tactical combat, featuring beautiful Japanese artwork and a branching narrative.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('elebits---kai-to-zero-no-fushigi-na-tabi-japan', 'NDS', 'Elebits - Kai to Zero no Fushigi na Tabi (Japan)', '2007', 'Action-Adventure', 'Konami', '1', 'Action', 'Action-adventure and monster catching.', 'Capture tiny electrical creatures to restore power.', 'A charming adventure where you hunt for hidden Elebits.', 'Elebits: The Adventures of Kai and Zero expands the world of the original Wii hit. Use your capture gun to find Elebits hidden in the environment, solve puzzles, and use their powers to explore new areas.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('elebits---kaiwa-zeroui-sinbihan-yeohaeng-korea', 'NDS', 'Elebits - Kaiwa Zeroui Sinbihan Yeohaeng (Korea)', '2007', 'Action-Adventure', 'Konami', '1', 'Action', 'Action-adventure and monster catching.', 'Capture tiny electrical creatures to restore power.', 'A charming adventure where you hunt for hidden Elebits.', 'Elebits: The Adventures of Kai and Zero expands the world of the original Wii hit. Use your capture gun to find Elebits hidden in the environment, solve puzzles, and use their powers to explore new areas.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('elebits---the-adventures-of-kai-and-zero-usa-enfr', 'NDS', 'Elebits - The Adventures of Kai and Zero (USA) (En,Fr)', '2007', 'Action-Adventure', 'Konami', '1', 'Action', 'Action-adventure and monster catching.', 'Capture tiny electrical creatures to restore power.', 'A charming adventure where you hunt for hidden Elebits.', 'Elebits: The Adventures of Kai and Zero expands the world of the original Wii hit. Use your capture gun to find Elebits hidden in the environment, solve puzzles, and use their powers to explore new areas.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('electroplankton-europe-enfrdeesit', 'NDS', 'Electroplankton (Europe) (En,Fr,De,Es,It)', '2005', 'Music', 'Nintendo', '1', 'Experimental', 'Interactive audio-visual art.', 'Create unique music and visuals by touching the plankton.', 'A revolutionary musical toy designed by Toshio Iwai.', 'Electroplankton turns the NDS into a living instrument. Interact with ten different species of plankton to create mesmerizing soundscapes and visual art. It is a unique, zen-like experience that defies traditional gaming genres.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('electroplankton-japan', 'NDS', 'Electroplankton (Japan)', '2005', 'Music', 'Nintendo', '1', 'Experimental', 'Interactive audio-visual art.', 'Create unique music and visuals by touching the plankton.', 'A revolutionary musical toy designed by Toshio Iwai.', 'Electroplankton turns the NDS into a living instrument. Interact with ten different species of plankton to create mesmerizing soundscapes and visual art. It is a unique, zen-like experience that defies traditional gaming genres.');
