INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eledees---the-adventures-of-kai-and-zero-europe-enfrdeesit', 'NDS', 'Eledees - The Adventures of Kai and Zero (Europe) (En,Fr,De,Es,It)', '2007', 'Action-Adventure', 'Konami', '1', 'Action', 'Action-adventure and monster catching.', 'Capture tiny electrical creatures to restore power.', 'A charming adventure where you hunt for hidden Elebits.', 'Eledees: The Adventures of Kai and Zero (known as Elebits in the US) is a delightful NDS quest. Explore diverse worlds, collect elemental spirits, and solve environmental puzzles in this high-energy action-adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('element-girls---love-fashion-&-friends-europe-enfrdeesit', 'NDS', 'Element Girls - Love, Fashion & Friends (Europe) (En,Fr,De,Es,It)', '2009', 'Simulation', 'Shin''en', '1', 'Casual', 'Lifestyle simulation and mini-games.', 'Manage your social life, fashion, and friendships.', 'A trendy lifestyle game for girls based on the magazine.', 'Element Girls: Love, Fashion & Friends lets you live out a virtual life full of style. Customize your avatar, play fashion mini-games, and navigate the social world of teenage friendships in this fun, interactive NDS title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('element-girls---style-your-life!-europe-frde', 'NDS', 'Element Girls - Style Your Life! (Europe) (Fr,De)', '2009', 'Simulation', 'Shin''en', '1', 'Casual', 'Lifestyle simulation and personality tests.', 'Discover your style and complete personality challenges.', 'A personal lifestyle guide and mini-game collection for girls.', 'Element Girls: Style Your Life! focuses on self-discovery and fun. Take personality quizzes, get fashion advice, and play engaging mini-games designed to reflect your unique "elemental" style on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('element-girls-germany', 'NDS', 'Element Girls (Germany)', '2009', 'Simulation', 'Tivola', '1', 'Casual', 'Lifestyle simulation and personality tests.', 'Discover your style and complete personality challenges.', 'A personal lifestyle guide and mini-game collection for girls.', 'Element Girls for NDS (Germany) focuses on self-discovery and fun. Take personality quizzes, get fashion advice, and play engaging mini-games designed to reflect your unique style through interactive challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('element-hunters-japan', 'NDS', 'Element Hunters (Japan)', '2009', 'Action', 'Namco Bandai', '1', 'Action', 'Action RPG and monster hunting.', 'Collect chemical elements and hunt monsters to save Earth.', 'A sci-fi action RPG based on the popular anime series.', 'Element Hunters on NDS takes you on a mission to recover lost chemical elements. Battle massive monsters in real-time combat, craft powerful gear, and explore alien dimensions in this deep, educational action-adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('element-hunters-korea', 'NDS', 'Element Hunters (Korea)', '2009', 'Action', 'Namco Bandai', '1', 'Action', 'Action RPG and monster hunting.', 'Collect chemical elements and hunt monsters to save Earth.', 'A sci-fi action RPG based on the popular anime series.', 'Element Hunters on NDS takes you on a mission to recover lost chemical elements. Battle massive monsters in real-time combat, craft powerful gear, and explore alien dimensions in this deep, educational action-adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('elemental-monster---itsu-hashira-gami-no-nazo-japan', 'NDS', 'Elemental Monster - Itsu Hashira Gami no Nazo (Japan)', '2009', 'Adventure', 'Nintendo', '1', 'Adventure', 'Tactical card battling RPG.', 'Build a powerful deck to defeat ancient elemental gods.', 'A deep strategic card-battle game with RPG elements.', 'Elemental Monster on NDS offers a complex grid-based card combat system. Collect hundreds of unique creature cards, master elemental affinities, and uncover the mystery of the Five Pillar Gods in this tactical Japanese RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('elements-of-destruction-europe-enfrdees', 'NDS', 'Elements of Destruction (Europe) (En,Fr,De,Es)', '2007', 'Action', 'A2M', '1', 'Action', 'Weather manipulation and strategy.', 'Control natural disasters to destroy cities and fulfill goals.', 'A unique game where you play as the forces of nature.', 'Elements of Destruction lets you control tornadoes, lightning, and earthquakes on NDS. Use the stylus to guide storms across maps, destroy targets, and outmaneuver the weather-control military in this destructive strategy title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('elements-of-destruction-usa', 'NDS', 'Elements of Destruction (USA)', '2007', 'Action', 'A2M', '1', 'Action', 'Weather manipulation and strategy.', 'Control natural disasters to destroy cities and fulfill goals.', 'A unique game where you play as the forces of nature.', 'Elements of Destruction lets you control tornadoes, lightning, and earthquakes on NDS. Use the stylus to guide storms across maps, destroy targets, and outmaneuver the weather-control military in this destructive strategy title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('elf-bowling-1-&-2-usa', 'NDS', 'Elf Bowling 1 & 2 (USA)', '2008', 'Party', 'NStorm', '4', 'Party', 'Physics-based bowling.', 'Knock down elf pins in a humorous holiday-themed game.', 'A quirky arcade bowling collection with a holiday twist.', 'Elf Bowling 1 & 2 brings the classic internet sensations to NDS. Launch Santa’s elves down the ice, aim for strikes, and enjoy the crude humor and simple physics-based gameplay of these two holiday arcade classics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('elite-beat-agents-europe', 'NDS', 'Elite Beat Agents (Europe)', '2007', 'Music', 'Nintendo', '1', 'Rhythm', 'Rhythm-based action and tapping.', 'Tap and slide to the beat to help people in distress.', 'A high-energy rhythm game with comic-book style stories.', 'Elite Beat Agents is a cult classic on NDS. Follow the agents as they dance to save the day through catchy pop songs. Hit markers on the beat to boost the "spirit" of people facing hilarious and heartwarming challenges.');
