INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('elite-forces---unit-77-europe-enfrdeesit', 'NDS', 'Elite Forces - Unit 77 (Europe) (En,Fr,De,Es,It)', '2009', 'Action', 'Kiwi Games', '1', 'Action', 'Tactical squad-based action.', 'Lead an elite unit through missions to stop terrorists.', 'A strategy-action game featuring squad management.', 'Elite Forces: Unit 77 on NDS puts you in command of a specialized team. Switch between characters like the sniper and medic to complete dangerous missions, rescue hostages, and dismantle global threats in this tactical adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('elite-forces---unit-77-usa-enfrdeesit', 'NDS', 'Elite Forces - Unit 77 (USA) (En,Fr,De,Es,It)', '2009', 'Action', 'Kiwi Games', '1', 'Action', 'Tactical squad-based action.', 'Lead an elite unit through missions to stop terrorists.', 'A strategy-action game featuring squad management.', 'Elite Forces: Unit 77 on NDS puts you in command of a specialized team. Switch between characters like the sniper and medic to complete dangerous missions, rescue hostages, and dismantle global threats in this tactical adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ellen-whitakers-horse-life-europe-enfrdeesitnl', 'NDS', 'Ellen Whitaker''s Horse Life (Europe) (En,Fr,De,Es,It,Nl)', '2008', 'Simulation', 'DTI Games', '1', 'Simulation', 'Equestrian simulation and racing.', 'Train horses and win international show jumping events.', 'A realistic horse riding and care simulation game.', 'Ellen Whitaker''s Horse Life lets you experience the world of professional show jumping on NDS. Care for your horse, master grooming routines, and compete in prestigious tournaments guided by the champion rider herself.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('elminage---yami-no-miko-to-kamigami-no-yubiwa---ds-remix-japan', 'NDS', 'Elminage - Yami no Miko to Kamigami no Yubiwa - DS Remix (Japan)', '2008', 'RPG', 'Starfish SD', '1', 'Turn-based', 'First-person dungeon crawler RPG.', 'Navigate complex labyrinths and defeat mythical beasts.', 'A classic "wizardry-style" RPG with deep party customization.', 'Elminage: DS Remix is a hardcore dungeon crawler for NDS. Create a party of adventurers, manage resources, and survive trap-filled corridors in a high-fantasy world where every step could be your last.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('elminage-ii---sousei-no-megami-to-unmei-no-daichi---ds-remix-japan-ndsi-enhanced', 'NDS', 'Elminage II - Sousei no Megami to Unmei no Daichi - DS Remix (Japan) (NDSi Enhanced)', '2009', 'RPG', 'Starfish SD', '1', 'Turn-based', 'First-person dungeon crawler RPG.', 'Navigate complex labyrinths and defeat mythical beasts.', 'A hardcore sequel with enhanced dungeon crawling mechanics.', 'Elminage II: DS Remix brings deeper customization and even more challenging dungeons to the NDS. Explore massive maps, engage in strategic turn-based combat, and enjoy the DSi enhanced features in this epic Japanese RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('elvenland-europe-enfrde', 'NDS', 'Elvenland (Europe) (En,Fr,De)', '2009', 'Adventure', 'Tivola', '1', 'Adventure', 'Adventure and mini-games.', 'Help the elves restore magic to their enchanted kingdom.', 'A magical adventure game designed for younger players.', 'Elvenland for NDS is a colorful journey through a fantasy realm. Play as a helpful elf, solve simple environmental puzzles, and complete mini-games to bring peace and beauty back to the enchanted forest and its inhabitants.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('emblem-of-gundam-japan', 'NDS', 'Emblem of Gundam (Japan)', '2007', 'Strategy', 'Bandai Namco', '1', 'Tactical', 'Tactical strategy and visual novel.', 'Lead Gundam units through historical and original battles.', 'A strategy game focusing on the Gundam universe''s lore.', 'Emblem of Gundam offers a deep dive into Universal Century history on NDS. Command mobile suits in strategic encounters and experience a rich narrative told through visual novel segments, perfect for hardcore Gundam fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('emergency-europe-enfresitnl', 'NDS', 'Emergency (Europe) (En,Fr,Es,It,Nl)', '2008', 'Simulation', 'Sixteen Tons', '1', 'Simulation', 'Emergency management strategy.', 'Dispatch rescue units to handle fires and accidents.', 'A real-time strategy game focused on rescue operations.', 'Emergency on NDS tasks you with being a first responder coordinator. Manage firefighters, paramedics, and police units to resolve high-stakes emergencies and save lives in challenging urban and natural disaster scenarios.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('emergency-2012-germany', 'NDS', 'Emergency 2012 (Germany)', '2011', 'Simulation', 'Sixteen Tons', '1', 'Simulation', 'Emergency management strategy.', 'Dispatch rescue units to handle fires and accidents.', 'A real-time strategy game focused on rescue operations.', 'Emergency 2012 for NDS offers updated scenarios and more complex missions. Command a variety of specialized vehicles and personnel to mitigate disasters and ensure the safety of citizens across various European cities.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('emergency-ds-germany', 'NDS', 'Emergency DS (Germany)', '2009', 'Simulation', 'Sixteen Tons', '1', 'Simulation', 'Emergency management strategy.', 'Dispatch rescue units to handle fires and accidents.', 'A real-time strategy game focused on rescue operations.', 'Emergency DS delivers intense rescue simulation on the go. Control the dual screens to oversee the disaster zone and issue commands rapidly to your emergency teams to prevent a total catastrophe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('emergency-room---real-life-rescues-usa', 'NDS', 'Emergency Room - Real Life Rescues (USA)', '2009', 'Simulation', 'Legacy Interactive', '1', 'Simulation', 'Medical simulation and adventure.', 'Perform surgeries and emergency treatments to save lives.', 'A realistic medical simulation focused on emergency care.', 'Emergency Room: Real Life Rescues puts you in the ER on NDS. Use the stylus as surgical tools, diagnose patients under pressure, and experience the fast-paced world of a trauma surgeon in this detailed medical sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('emily---my-animal-shelter-europe-enfrit', 'NDS', 'Emily - My Animal Shelter (Europe) (En,Fr,It)', '2009', 'Simulation', 'Tivola', '1', 'Casual', 'Simulation and animal care.', 'Manage an animal shelter and help injured pets recover.', 'A pet rescue simulation focused on medical care and adoption.', 'Emily: My Animal Shelter on NDS allows you to care for stray cats and dogs. Treat their illnesses, feed them, and find them loving homes while expanding your shelter''s facilities in this heartwarming simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('emily---my-dog-paradise-europe-enfrit', 'NDS', 'Emily - My Dog Paradise (Europe) (En,Fr,It)', '2008', 'Simulation', 'Tivola', '1', 'Casual', 'Simulation and pet training.', 'Create a dream park for dogs and keep them happy.', 'A lighthearted pet simulation game for dog lovers.', 'Emily: My Dog Paradise for NDS lets you build the ultimate playground for pups. Interact with various breeds, teach them tricks, and manage a beautiful park where dogs and their owners can have fun together.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('emily---my-personal-diary-europe-enfrdeesitnl', 'NDS', 'Emily - My Personal Diary (Europe) (En,Fr,De,Es,It,Nl)', '2008', 'Simulation', 'Tivola', '1', 'Casual', 'Lifestyle organizer and simulation.', 'Keep a digital diary and manage your daily activities.', 'A personal diary and lifestyle app for the NDS.', 'Emily: My Personal Diary is more than a game; it''s a digital organizer. Write secrets, track your mood, play mini-games, and use the calendar and contact list to keep your life organized on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('emma-at-the-farm-europe-endesvnodafi', 'NDS', 'Emma at the Farm (Europe) (En,De,Sv,No,Da,Fi)', '2008', 'Simulation', 'Tivola', '1', 'Casual', 'Educational adventure and mini-games.', 'Learn about farm life through puzzles and exploration.', 'A kid-friendly educational game set on a farm.', 'Emma at the Farm offers an interactive learning experience on NDS. Children can learn about animals, plants, and farm chores through simple touch-screen games and engaging stories designed for early development.');
