INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('enchanted-europe-enfrdeesitnl', 'NDS', 'Enchanted (Europe) (En,Fr,De,Es,It,Nl)', '2007', 'Adventure', 'Disney Interactive', '1', 'Adventure', 'Action-adventure and mini-games.', 'Help Giselle navigate the real world and find her way home.', 'A magical adventure based on the Disney film Enchanted.', 'Experience the magic of Disney''s Enchanted on NDS. Play as Giselle and Edward, using unique abilities and magic to overcome challenges in New York City. Includes fun mini-games and a charming story for fans of all ages.');
