INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('enchanted-folk-and-the-school-of-wizardry-europe-enfrdeesit', 'NDS', 'Enchanted Folk and the School of Wizardry (Europe) (En,Fr,De,Es,It)', '2008', 'Simulation', 'Nintendo', '1', 'Life Simulation', 'Life simulation and magic.', 'Attend wizardry school, learn spells, and make friends.', 'A social simulation game set in a magical school.', 'Enchanted Folk and the School of Wizardry offers a deep life-sim experience on NDS. Create your wizard, learn over 100 spells, catch magical bugs, and form bonds with quirky classmates in a world that changes in real-time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ener-g---dance-squad-usa-enfres', 'NDS', 'Ener-G - Dance Squad (USA) (En,Fr,Es)', '2008', 'Dance', 'Aksys Games', '4', 'Dance', 'Rhythm and dance simulation.', 'Perform dance routines and lead your squad to victory.', 'A high-energy dance and rhythm game for aspiring stars.', 'Ener-G: Dance Squad on NDS lets you choreograph and perform amazing routines. Use the stylus to keep the beat, customize your dancer’s outfits, and compete in various venues to become the top dance squad in the country.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ener-g---gym-rockets-usa-enfres', 'NDS', 'Ener-G - Gym Rockets (USA) (En,Fr,Es)', '2008', 'Fitness', 'Aksys Games', '1', 'Fitness', 'Sports simulation and gymnastics.', 'Master gymnastics routines and win gold medals.', 'A rhythmic gymnastics game featuring multiple events.', 'Ener-G: Gym Rockets challenges you to master the balance beam, floor exercises, and more on NDS. Train hard, customize your gymnast, and use precision touch-screen controls to execute perfect flips and landings in competition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ener-g---horse-riders-usa-enfres', 'NDS', 'Ener-G - Horse Riders (USA) (En,Fr,Es)', '2008', 'Simulation', 'Aksys Games', '1', 'Casual', 'Equestrian simulation and care.', 'Train your horse and win riding competitions.', 'A horse riding adventure focused on training and care.', 'Ener-G: Horse Riders for NDS allows you to bond with your horse. Manage your stable, practice jumping and dressage, and enter prestigious shows. A perfect title for players who love animals and competitive riding.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('englisch-buddy-europe-enfrdeesitnl', 'NDS', 'Englisch Buddy (Europe) (En,Fr,De,Es,It,Nl)', '2007', 'Educational', 'Mentor Interactive', '1', 'Educational', 'Language learning and drills.', 'Improve English vocabulary and grammar through games.', 'An interactive English language trainer for all levels.', 'Englisch Buddy on NDS provides a portable way to learn English. Featuring various difficulty levels, vocabulary exercises, and listening tests, it turns your handheld console into a personal language tutor for daily practice.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('englisch-buddy-europe-enfrde', 'NDS', 'Englisch Buddy (Europe) (En,Fr,De)', '2007', 'Educational', 'Mentor Interactive', '1', 'Educational', 'Language learning and drills.', 'Improve English vocabulary and grammar through games.', 'An interactive English language trainer for all levels.', 'Englisch Buddy on NDS provides a portable way to learn English. Featuring various difficulty levels, vocabulary exercises, and listening tests, it turns your handheld console into a personal language tutor for daily practice.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('englisch-macht-spass---eine-reise-nach-london!-germany', 'NDS', 'Englisch Macht Spass - Eine Reise nach London! (Germany)', '2008', 'Educational', 'Tivola', '1', 'Educational', 'Educational adventure.', 'Travel to London and learn English through a story.', 'A narrative-driven English learning game for children.', 'Englisch Macht Spass takes kids on a trip to London on their NDS. Learn essential phrases and culture through interactive scenarios and mini-games designed to make English learning fun and natural for young beginners.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('english-training---have-fun-improving-your-skills-europe-frdeesitnl', 'NDS', 'English Training - Have Fun Improving Your Skills (Europe) (Fr,De,Es,It,Nl)', '2008', 'Educational', 'Nintendo', '1', 'Educational', 'Dictation and language practice.', 'Enhance English skills through listening and writing.', 'A comprehensive English training tool for non-native speakers.', 'English Training for NDS focuses on practical language skills. Listen to sentences and write them using the stylus to improve your comprehension and spelling. Includes various modes to track your progress and improve daily.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('enpitsu-de-oku-no-hosomichi-ds-japan', 'NDS', 'Enpitsu de Oku no Hosomichi DS (Japan)', '2007', 'Adventure', 'Nintendo', '1', 'Literature', 'Stylus-based writing and literature.', 'Trace the classic "Oku no Hosomichi" text in Japanese.', 'A literary and calligraphy trainer based on Basho''s work.', 'Enpitsu de Oku no Hosomichi DS allows you to experience classic Japanese literature while practicing your handwriting. Trace the beautiful prose of Matsuo Basho to improve your calligraphy skills and cultural knowledge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('entraineur-cerebral-l---kids-france', 'NDS', 'Entraineur Cerebral, L'' - Kids (France)', '2007', 'Educational', 'Mindscape', '1', 'Brain Training', 'Brain training and mini-games.', 'Solve puzzles to improve cognitive skills in children.', 'A fun brain trainer designed specifically for kids.', 'L''Entraineur Cerebral: Kids on NDS offers a variety of educational mini-games. Focus on logic, math, and memory challenges tailored for younger minds to help them develop essential cognitive skills while playing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('entraineur-cerebral-l---logique-france', 'NDS', 'Entraineur Cerebral, L'' - Logique (France)', '2007', 'Educational', 'Mindscape', '1', 'Brain Training', 'Logic puzzles and brain training.', 'Solve complex logic riddles to sharpen your mind.', 'A specialized brain trainer focused on logical thinking.', 'L''Entraineur Cerebral: Logique provides a deep collection of logic-based puzzles for NDS. Challenge your analytical skills with increasingly difficult tasks designed to keep your brain active and improve problem-solving speed.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('entraineur-cerebral-l---perception-france', 'NDS', 'Entraineur Cerebral, L'' - Perception (France)', '2007', 'Educational', 'Mindscape', '1', 'Brain Training', 'Visual puzzles and memory games.', 'Enhance visual perception and spatial awareness.', 'A brain training game focused on sight and perception.', 'L''Entraineur Cerebral: Perception challenges your eyes and brain. Play through various mini-games that test your ability to recognize patterns, find differences, and process visual information quickly on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eq-trainer-ds---dekiru-otona-no-communication-jutsu-japan', 'NDS', 'EQ Trainer DS - Dekiru Otona no Communication Jutsu (Japan)', '2008', 'Educational', 'Nintendo', '1', 'Lifestyle', 'Social simulation and training.', 'Improve communication and emotional intelligence.', 'A unique "EQ" trainer for better social interactions.', 'EQ Trainer DS helps you master the art of adult communication. Through various social scenarios and quizzes, learn how to read emotions and respond effectively in professional and personal life using this interactive Japanese trainer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('equestrian-training-europe', 'NDS', 'Equestrian Training (Europe)', '2009', 'Simulation', 'Tivola', '1', 'Simulation', 'Equestrian simulation.', 'Learn horse riding theory and practice for exams.', 'A comprehensive guide to horse riding and stable care.', 'Equestrian Training on NDS is the perfect tool for horse enthusiasts. Learn about different breeds, grooming, and riding techniques while preparing for official equestrian certifications through interactive lessons and tests.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('equitation---galops-1-a-4-france', 'NDS', 'Equitation - Galops 1 a 4 (France)', '2008', 'Simulation', 'Mindscape', '1', 'Simulation', 'Educational and sports sim.', 'Master the first four levels of French equestrianism.', 'A specialized horse riding guide for Galops 1-4.', 'Equitation - Galops 1 a 4 provides a structured way to study French riding standards. Use your NDS to review theory, learn about horse anatomy, and practice the skills needed to pass the first four official riding grades.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('equitation---galops-1-a-7-france', 'NDS', 'Equitation - Galops 1 a 7 (France)', '2009', 'Simulation', 'Mindscape', '1', 'Simulation', 'Educational and sports sim.', 'Master all seven levels of French equestrianism.', 'The complete guide for the French Galops riding exams.', 'Equitation - Galops 1 a 7 is the definitive NDS resource for riders in the French system. It covers advanced theory, dressage, and jumping rules required to reach the highest levels of equestrian certification.');
