INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eragon-europe-enfrdeesit', 'NDS', 'Eragon (Europe) (En,Fr,De,Es,It)', '2006', 'Action', 'Stormfront Studios', '1', 'Action', 'Action-adventure and combat.', 'Defeat the evil king and master dragon riding.', 'An epic fantasy adventure based on the Eragon film.', 'Eragon for NDS brings the world of Alagaesia to life. Engage in touch-screen based combat, cast powerful spells, and fly on the back of Saphira the dragon in this immersive action-RPG experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eragon-usa', 'NDS', 'Eragon (USA)', '2006', 'Action', 'Stormfront Studios', '1', 'Action', 'Action-adventure and combat.', 'Defeat the evil king and master dragon riding.', 'An epic fantasy adventure based on the Eragon film.', 'Eragon for NDS brings the world of Alagaesia to life. Engage in touch-screen based combat, cast powerful spells, and fly on the back of Saphira the dragon in this immersive action-RPG experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ermii-kart-ds-legacy-edition', 'NDS', 'Ermii Kart DS Legacy Edition', '2011', 'Racing', 'Ermii Soft', '4', 'Kart Racing', 'Kart racing and battle.', 'Win races and unlock tracks in this fan-enhanced edition.', 'A specialized "Legacy Edition" of a classic kart racer.', 'Ermii Kart DS Legacy Edition delivers fast-paced racing action on NDS. Choose your character, use power-ups to sabotage rivals, and master diverse tracks in this refined and community-driven racing experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('escape-the-museum-europe-enfrit', 'NDS', 'Escape the Museum (Europe) (En,Fr,It)', '2008', 'Adventure', 'Tika Mobile', '1', 'Hidden Object', 'Hidden object and puzzle solving.', 'Escape a crumbling museum by finding items and solving riddles.', 'A tense hidden object adventure set during an earthquake.', 'Escape the Museum on NDS puts you in a race against time. After a devastating earthquake, navigate through ruined exhibits, find useful tools, and solve clever puzzles to find your daughter and escape the building.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('escape-the-museum-europe-enfrnl', 'NDS', 'Escape the Museum (Europe) (En,Fr,Nl)', '2008', 'Adventure', 'Tika Mobile', '1', 'Hidden Object', 'Hidden object and puzzle solving.', 'Escape a crumbling museum by finding items and solving riddles.', 'A tense hidden object adventure set during an earthquake.', 'Escape the Museum on NDS puts you in a race against time. After a devastating earthquake, navigate through ruined exhibits, find useful tools, and solve clever puzzles to find your daughter and escape the building.');
