INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('esse-shikkari-kakeibo-ds-japan-rev-1', 'NDS', 'ESSE Shikkari Kakeibo DS (Japan) (Rev 1)', '2007', 'Simulation', 'Shogakukan', '1', 'Finance', 'Finance management and diary.', 'Manage your household budget and track expenses.', 'A popular Japanese household account book app.', 'ESSE Shikkari Kakeibo DS makes financial planning easy on your NDS. Log your daily spending, categorize expenses, and use the interactive charts to visualize your savings goals based on the famous ESSE magazine methods.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('essential-sudoku-ds-europe', 'NDS', 'Essential Sudoku DS (Europe)', '2006', 'Puzzle', 'Game Factory', '1', 'Puzzle', 'Logic puzzle and Sudoku.', 'Complete hundreds of Sudoku grids of varying difficulty.', 'A focused collection of classic Sudoku puzzles.', 'Essential Sudoku DS offers a clean, distraction-free puzzle experience. With a massive library of grids and a helpful hint system, it is the perfect NDS title for fans of the world''s most popular number logic game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('estpolis---the-lands-cursed-by-the-gods-japan', 'NDS', 'Estpolis - The Lands Cursed by the Gods (Japan)', '2010', 'RPG', 'Neverland', '1', 'Turn-based', 'Action-RPG and exploration.', 'Explore a world plagued by monsters and ancient curses.', 'A high-quality action-RPG remake of a classic franchise.', 'Estpolis (Lufia) for NDS reimagines the series with stunning 3D graphics and real-time combat. Solve intricate environmental puzzles and experience an emotional story in this definitive Japanese RPG adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('etrian-odyssey-europe-enfrdeesit', 'NDS', 'Etrian Odyssey (Europe) (En,Fr,De,Es,It)', '2008', 'RPG', 'Atlus', '1', 'Dungeon Crawler', 'First-person dungeon crawling.', 'Map out dangerous labyrinths and defeat powerful bosses.', 'A challenging RPG where you draw your own maps.', 'Etrian Odyssey is a hardcore RPG for NDS. Use the bottom screen to draw your own maps as you explore the Yggdrasil Labyrinth. Build a custom party and survive brutal turn-based battles in this celebrated dungeon crawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('etrian-odyssey-usa', 'NDS', 'Etrian Odyssey (USA)', '2008', 'RPG', 'Atlus', '1', 'Dungeon Crawler', 'First-person dungeon crawling.', 'Map out dangerous labyrinths and defeat powerful bosses.', 'A challenging RPG where you draw your own maps.', 'Etrian Odyssey is a hardcore RPG for NDS. Use the bottom screen to draw your own maps as you explore the Yggdrasil Labyrinth. Build a custom party and survive brutal turn-based battles in this celebrated dungeon crawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('etrian-odyssey-ii---heroes-of-lagaard-usa', 'NDS', 'Etrian Odyssey II - Heroes of Lagaard (USA)', '2010', 'RPG', 'Atlus', '1', 'Dungeon Crawler', 'First-person dungeon crawling.', 'Map the High Lagaard castle and defeat legendary guardians.', 'A challenging sequel to the acclaimed dungeon-mapping RPG.', 'Etrian Odyssey II: Heroes of Lagaard returns to the NDS with more classes and deeper customization. Use the touch screen to draw detailed maps of the Yggdrasil Labyrinth while surviving brutal turn-based combat in this hardcore RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('etrian-odyssey-iii---the-drowned-city-usa', 'NDS', 'Etrian Odyssey III - The Drowned City (USA)', '2011', 'RPG', 'Atlus', '1', 'Dungeon Crawler', 'First-person dungeon crawling and sailing.', 'Explore underwater ruins and discover the secrets of Armoroad.', 'The third installment featuring sea exploration and new classes.', 'Etrian Odyssey III: The Drowned City expands the series on NDS. In addition to deep dungeon crawling, you can now set sail on the ocean, trade with other ships, and map out the high seas in this massive tactical adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('evolution-gt-europe-enfrdeesit', 'NDS', 'Evolution GT (Europe) (En,Fr,De,Es,It)', '2005', 'Racing', 'Milestone', '1', 'Racing', 'Professional circuit racing.', 'Win races, gain reputation, and upgrade your driving skills.', 'A realistic racing simulator focused on career progression.', 'Evolution GT for NDS offers a sophisticated driving experience. Develop your driver''s skills like a real pro, manage your racing career, and master various European tracks with a selection of high-performance licensed cars.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('exit-ds-europe-enjafrdeesit', 'NDS', 'Exit DS (Europe) (En,Ja,Fr,De,Es,It)', '2008', 'Puzzle', 'Taito', '1', 'Action', 'Puzzle and rescue action.', 'Lead survivors to the exit before the time runs out.', 'A stylish puzzle-platformer featuring "Mr. ESC."', 'Exit DS brings a unique aesthetic to the NDS. As an escapologist, you must navigate disasters and use logic to rescue trapped civilians. Each level is a complex puzzle that requires perfect timing and strategic thinking.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('exit-ds-usa-enfrdeesit', 'NDS', 'Exit DS (USA) (En,Fr,De,Es,It)', '2008', 'Puzzle', 'Taito', '1', 'Action', 'Puzzle and rescue action.', 'Lead survivors to the exit before the time runs out.', 'A stylish puzzle-platformer featuring "Mr. ESC."', 'Exit DS brings a unique aesthetic to the NDS. As an escapologist, you must navigate disasters and use logic to rescue trapped civilians. Each level is a complex puzzle that requires perfect timing and strategic thinking.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('expeditie-robinson-netherlands', 'NDS', 'Expeditie Robinson (Netherlands)', '2008', 'Party', 'Endemol', '4', 'Party', 'Survival and mini-games.', 'Compete in challenges and survive on a deserted island.', 'A game based on the popular "Survivor" reality TV show.', 'Expeditie Robinson for NDS tasks you with outlasting the competition. Manage your resources, participate in physical and mental challenges, and navigate social alliances to be the last survivor on the island in this competitive sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eyeshield-21---max-devil-power!-japan', 'NDS', 'Eyeshield 21 - Max Devil Power! (Japan)', '2007', 'Sports', 'Konami', '1', 'Sports', 'Sports action and strategy.', 'Lead the Deimon Devil Bats to victory in American Football.', 'An American Football game based on the hit sports manga.', 'Eyeshield 21: Max Devil Power! brings high-octane football to NDS. Use the touch screen to execute special moves and tactical plays. Follow the anime''s story and build a winning team through intense training and matches.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-24---stealth-fighter-europe-enfrdeesit', 'NDS', 'F-24 - Stealth Fighter (Europe) (En,Fr,De,Es,It)', '2006', 'Simulation', 'Mastiff', '1', 'Flight', 'Flight simulation and combat.', 'Complete aerial missions and engage in dogfights.', 'A portable flight combat simulator featuring stealth fighters.', 'F-24 Stealth Fighter for NDS puts you in the cockpit of a modern jet. Take part in dangerous air-to-air and air-to-ground missions, manage your fuel and ammo, and prove your skills as an elite pilot in this intense flight sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-24---stealth-fighter-usa', 'NDS', 'F-24 - Stealth Fighter (USA)', '2006', 'Simulation', 'Mastiff', '1', 'Flight', 'Flight simulation and combat.', 'Complete aerial missions and engage in dogfights.', 'A portable flight combat simulator featuring stealth fighters.', 'F-24 Stealth Fighter for NDS puts you in the cockpit of a modern jet. Take part in dangerous air-to-air and air-to-ground missions, manage your fuel and ammo, and prove your skills as an elite pilot in this intense flight sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fab-5-soccer-usa', 'NDS', 'Fab 5 Soccer (USA)', '2008', 'Sports', 'Akupara Games', '2', 'Sports', 'Sports simulation and management.', 'Coach a soccer team and win the championship.', 'A casual soccer game focused on team management and play.', 'Fab 5 Soccer on NDS offers a fun and accessible football experience. Manage your squad, participate in tournaments, and use the stylus to control players on the pitch as you aim for the top of the league.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fabulous-finds-usa', 'NDS', 'Fabulous Finds (USA)', '2009', 'Adventure', 'Big Fish Games', '1', 'Hidden Object', 'Hidden object and puzzle solving.', 'Find valuable items and sell them to restore your garden.', 'A hidden object game with a focus on interior design.', 'Fabulous Finds for NDS combines treasure hunting with decoration. Search through cluttered rooms for valuable antiques, manage your budget, and use your earnings to create a beautiful home and garden in this relaxing title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('facening-de-hyoujou-yutaka-ni-inshou-up---otona-no-ds-kao-training-japan', 'NDS', 'Facening de Hyoujou Yutaka ni Inshou Up - Otona no DS Kao Training (Japan)', '2008', 'Educational', 'Nintendo', '1', 'Training', 'Facial exercise and simulation.', 'Perform facial movements to improve your expression.', 'A unique health-sim for exercising facial muscles.', 'Face Training (Facening) uses the NDS camera to guide you through exercises designed to tone your face. Follow the on-screen instructors to improve your expressions and boost your facial health through daily digital workouts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fall-fuer-tkkg-ein---detektiv-gesucht!-germany', 'NDS', 'Fall fuer TKKG, Ein - Detektiv Gesucht! (Germany)', '2009', 'Adventure', 'Tivola', '1', 'Adventure', 'Adventure and point-and-click.', 'Solve mysteries and find the missing detective.', 'A detective adventure based on the German book series TKKG.', 'Ein Fall fuer TKKG for NDS follows the famous group of teenage detectives. Solve puzzles, collect clues, and interview witnesses to crack a complex case in this German-exclusive mystery adventure game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('famicom-wars-ds-japan', 'NDS', 'Famicom Wars DS (Japan)', '2005', 'Strategy', 'Nintendo', '1', 'Tactical', 'Turn-based tactical strategy.', 'Lead your army to victory against the enemy nation.', 'The Japanese version of the acclaimed Advance Wars series.', 'Famicom Wars DS brings intense tactical warfare to the NDS. Command diverse land, air, and sea units across multiple battlefields. Use powerful Commanding Officer abilities to turn the tide of war in this strategy masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('family-feud---2010-edition-usa', 'NDS', 'Family Feud - 2010 Edition (USA)', '2010', 'Party', 'Ludia', '4', 'Quiz', 'Trivia and game show.', 'Answer survey questions to win points for your family.', 'A digital version of the popular TV game show Family Feud.', 'Family Feud: 2010 Edition for NDS captures the excitement of the TV show. Compete against the computer or friends in "Fast Money" and other classic rounds to see if you can guess the most popular answers to everyday questions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('family-fortunes-europe', 'NDS', 'Family Fortunes (Europe)', '2008', 'Party', 'Ludia', '4', 'Quiz', 'Trivia and game show.', 'Guess the most popular survey answers to win the prize.', 'The UK version of the hit game show Family Feud.', 'Family Fortunes on NDS brings the classic British TV game home. Test your knowledge of public opinion through various rounds of survey-based trivia, making it a perfect game for solo play or social gatherings.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('family-park-tycoon-europe-ende', 'NDS', 'Family Park Tycoon (Europe) (En,De)', '2008', 'Simulation', 'Independent Arts', '1', 'Management', 'Theme park management.', 'Build and manage a successful amusement park.', 'A tycoon-style simulation focused on theme park design.', 'Family Park Tycoon for NDS lets you build the park of your dreams. Manage rides, stalls, and staff while keeping your visitors happy and your finances in check in this engaging and portable management simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('famous---the-road-to-glory!-europe-enfrdeesitnl', 'NDS', 'Famous - The Road to Glory! (Europe) (En,Fr,De,Es,It,Nl)', '2008', 'Simulation', 'Neko Entertainment', '1', 'Career', 'Lifestyle simulation and fame.', 'Rise to fame by mastering various star-studded skills.', 'A career simulation game about becoming a celebrity.', 'Famous: The Road to Glory! on NDS lets you experience the path to stardom. Train in music, fashion, and acting, manage your public image, and work your way up from a beginner to a world-renowned celebrity.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fantastic-four---rise-of-the-silver-surfer-europe-enfrdeesit', 'NDS', 'Fantastic Four - Rise of the Silver Surfer (Europe) (En,Fr,De,Es,It)', '2007', 'Action', '7 Studios', '1', 'Action', 'Action and character switching.', 'Save Earth from the Silver Surfer and Dr. Doom.', 'An action game based on the Fantastic Four sequel.', 'Play as the Marvel heroes in Fantastic Four: Rise of the Silver Surfer for NDS. Switch between characters to utilize their unique powers—fire, strength, invisibility, and stretch—to defeat cosmic threats in this hero adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fantastic-four---rise-of-the-silver-surfer-usa-enfrdeesit', 'NDS', 'Fantastic Four - Rise of the Silver Surfer (USA) (En,Fr,De,Es,It)', '2007', 'Action', '7 Studios', '1', 'Action', 'Action and character switching.', 'Save Earth from the Silver Surfer and Dr. Doom.', 'An action game based on the Fantastic Four sequel.', 'Play as the Marvel heroes in Fantastic Four: Rise of the Silver Surfer for NDS. Switch between characters to utilize their unique powers—fire, strength, invisibility, and stretch—to defeat cosmic threats in this hero adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fantasy-aquarium-by-ds-europe-enfrdeesit', 'NDS', 'Fantasy Aquarium by DS (Europe) (En,Fr,De,Es,It)', '2008', 'Simulation', 'DSI Games', '1', 'Casual', 'Simulation and pet care.', 'Raise and care for exotic fantasy creatures in an aquarium.', 'A unique aquarium sim featuring mythical sea creatures.', 'Fantasy Aquarium for NDS lets you manage a tank filled with magical fish and monsters. Keep them healthy, decorate their environment, and discover new species in this creative and relaxing take on the virtual pet genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fantasy-aquarium-by-ds-usa', 'NDS', 'Fantasy Aquarium by DS (USA)', '2008', 'Simulation', 'DSI Games', '1', 'Casual', 'Simulation and pet care.', 'Raise and care for exotic fantasy creatures in an aquarium.', 'A unique aquarium sim featuring mythical sea creatures.', 'Fantasy Aquarium for NDS lets you manage a tank filled with magical fish and monsters. Keep them healthy, decorate their environment, and discover new species in this creative and relaxing take on the virtual pet genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('farm-frenzy---animal-country-europe-enfrdeesitnl', 'NDS', 'Farm Frenzy - Animal Country (Europe) (En,Fr,De,Es,It,Nl)', '2009', 'Simulation', 'Alawar', '1', 'Management', 'Time management and farming.', 'Produce goods and meet goals within the time limit.', 'A fast-paced arcade farming game with various levels.', 'Farm Frenzy: Animal Country brings addictive time-management to NDS. Manage animals, process raw materials into valuable goods, and upgrade your farm buildings to beat challenging levels and earn gold trophies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('farm-frenzy---animal-country-usa-ennl', 'NDS', 'Farm Frenzy - Animal Country (USA) (En,Nl)', '2009', 'Simulation', 'Alawar', '1', 'Management', 'Time management and farming.', 'Produce goods and meet goals within the time limit.', 'A fast-paced arcade farming game with various levels.', 'Farm Frenzy: Animal Country brings addictive time-management to NDS. Manage animals, process raw materials into valuable goods, and upgrade your farm buildings to beat challenging levels and earn gold trophies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('farm-life---manage-your-own-farm-europe-enfrdeesitnl', 'NDS', 'Farm Life - Manage Your Own Farm (Europe) (En,Fr,De,Es,It,Nl)', '2009', 'Simulation', 'Roundhouse', '1', 'Management', 'Farming and life simulation.', 'Run a successful farm and interact with the local community.', 'A comprehensive farming sim focused on management and care.', 'Farm Life for NDS tasks you with building a rural empire. Plant crops, raise livestock, and upgrade your equipment. Balance your daily chores with social interactions to create the most prosperous farm in the valley.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fashion-designer---high-fashion-europe-enfrdeesit', 'NDS', 'Fashion Designer - High Fashion (Europe) (En,Fr,De,Es,It)', '2008', 'Simulation', 'Fashion Studio', '1', 'Fashion', 'Fashion simulation and design.', 'Create high-fashion outfits and win competitions.', 'A creative design game focused on the world of fashion.', 'Fashion Designer: High Fashion for NDS lets you live the life of a couturier. Design clothes, choose fabrics, and showcase your collections on the runway to become a respected name in the global fashion industry.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fashion-designer---style-icon-europe-enfrdeesit', 'NDS', 'Fashion Designer - Style Icon (Europe) (En,Fr,De,Es,It)', '2009', 'Simulation', 'Fashion Studio', '1', 'Fashion', 'Fashion simulation and design.', 'Design outfits and rise to become a style icon.', 'A creativity-driven game about fashion and social status.', 'Fashion Designer: Style Icon on NDS puts your creative skills to the test. Create unique looks for your clients, manage your fashion boutique, and influence the latest trends to secure your spot as a legendary style icon.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fashion-dogz-europe', 'NDS', 'Fashion Dogz (Europe)', '2009', 'Simulation', 'Tivola', '1', 'Casual', 'Pet simulation and grooming.', 'Care for and dress up a variety of stylish dogs.', 'A dog-focused pet sim with a focus on fashion.', 'Fashion Dogz for NDS combines pet care with dress-up fun. Choose your favorite breed, groom them to perfection, and dress them in the latest canine trends to compete in doggy fashion shows.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fashion-studio---paris-collection-usa-enfres', 'NDS', 'Fashion Studio - Paris Collection (USA) (En,Fr,Es)', '2009', 'Simulation', 'Funcom', '1', 'Fashion', 'Fashion and time management.', 'Create a collection for the prestigious Paris fashion week.', 'A career-based simulation focused on international fashion.', 'Fashion Studio: Paris Collection takes you to the heart of France on NDS. Design stunning outfits, manage your studio, and prepare for the ultimate runway show in this glamorous and creative fashion adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fashion-tycoon-europe-enfrdeesitnl', 'NDS', 'Fashion Tycoon (Europe) (En,Fr,De,Es,It,Nl)', '2009', 'Simulation', 'Tivola', '1', 'Management', 'Business simulation and fashion.', 'Manage a fashion empire and maximize profits.', 'A tycoon game focused on the retail and fashion business.', 'Fashion Tycoon for NDS challenges you to build a fashion brand from the ground up. Manage production, distribution, and retail stores while keeping up with changing trends to dominate the fashion market.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fast-food-panic-europe-enfrdeesit', 'NDS', 'Fast Food Panic (Europe) (En,Fr,De,Es,It)', '2008', 'Simulation', 'Office Create', '1', 'Management', 'Time management and cooking.', 'Run a fast food restaurant and serve customers quickly.', 'A high-speed cooking simulation where every second counts.', 'Fast Food Panic for NDS challenges you to manage a busy restaurant. From preparing burgers to cleaning up, use the stylus to handle every aspect of the kitchen. Keep customers happy and your business growing in this frantic and fun culinary adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fast-food-panic-usa-enfres', 'NDS', 'Fast Food Panic (USA) (En,Fr,Es)', '2008', 'Simulation', 'Office Create', '1', 'Management', 'Time management and cooking.', 'Run a fast food restaurant and serve customers quickly.', 'A high-speed cooking simulation where every second counts.', 'Fast Food Panic for NDS challenges you to manage a busy restaurant. From preparing burgers to cleaning up, use the stylus to handle every aspect of the kitchen. Keep customers happy and your business growing in this frantic and fun culinary adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fee-lili-rose-2-la---mon-monde-merveilleux-europe-enfrit', 'NDS', 'Fee Lili-Rose 2, La - Mon Monde Merveilleux (Europe) (En,Fr,It)', '2009', 'Adventure', 'Tivola', '1', 'Fantasy', 'Adventure and mini-games.', 'Explore a magical world and complete fairy tasks.', 'A charming adventure game for kids featuring Princess Lillifee.', 'La Fee Lili-Rose 2: Mon Monde Merveilleux brings a world of magic to NDS. Young players can explore enchanted gardens, solve simple puzzles, and participate in fairy-themed mini-games designed for creative and imaginative fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fee-lili-rose-la---la-magie-des-fees-europe-enfrde', 'NDS', 'Fee Lili-Rose, La - La Magie des Fees (Europe) (En,Fr,De)', '2008', 'Adventure', 'Tivola', '1', 'Fantasy', 'Adventure and mini-games.', 'Complete tasks and use magic to help fairy friends.', 'A magical adventure based on the Princess Lillifee series.', 'La Fee Lili-Rose: La Magie des Fees on NDS offers a delightful experience for children. Use the stylus to cast spells, decorate environments, and go on a journey through a whimsical world filled with friendly characters and magical surprises.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('feel-the-magic---xy-xx-usa-enja', 'NDS', 'Feel the Magic - XY-XX (USA) (En,Ja)', '2006', 'Party', 'Nintendo', '1', 'Experimental', 'Stylus-based mini-games and romance.', 'Win the heart of a girl through bizarre and fun challenges.', 'A quirky and artistic mini-game collection from SEGA.', 'Feel the Magic: XY-XX is a unique NDS title that uses every feature of the console. Perform strange tasks like rubbing the screen or blowing into the mic to protect your love interest. A stylish, fast-paced, and cult-classic experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('feji-russia', 'NDS', 'Feji (Russia)', '2009', 'Puzzle', 'Russobit-M', '1', 'Puzzle', 'Strategy and logic puzzles.', 'Solve complex puzzles in a mystical fantasy world.', 'A Russian logic puzzle game with a fantasy aesthetic.', 'Feji for NDS offers challenging brain-teasers set in a world of mystery. Navigate grid-based levels, move elemental stones, and solve increasingly difficult puzzles that require careful planning and strategic thinking to progress.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ferrari-challenge---trofeo-pirelli---european-series-europe-enfrdeesit', 'NDS', 'Ferrari Challenge - Trofeo Pirelli - European Series (Europe) (En,Fr,De,Es,It)', '2009', 'Racing', 'System 3', '1', 'Racing', 'Professional circuit racing.', 'Win the Ferrari Trofeo Pirelli and unlock legendary cars.', 'A realistic racing simulator featuring officially licensed Ferraris.', 'Ferrari Challenge: Trofeo Pirelli brings elite racing to NDS. Master the handling of iconic Italian supercars, compete on world-famous tracks, and experience deep career progression in this high-fidelity portable racing simulation.');
