INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa-06-europe-enfrdeesitnl', 'NDS', 'FIFA 06 (Europe) (En,Fr,De,Es,It,Nl)', '2005', 'Sports', 'EA Sports', '4', 'Sports', 'Sports simulation and football.', 'Win matches and lead your favorite team to the championship.', 'The definitive portable football experience with official licenses.', 'FIFA 06 for NDS delivers authentic soccer action. Manage your team, play through full seasons, and enjoy the touch-screen management features. Featuring hundreds of real players and teams from across the globe.');
