INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifi-and-the-flowertots-europe', 'NDS', 'Fifi and the Flowertots (Europe)', '2009', 'Adventure', 'Stormfront Studios', '1', 'Casual', 'Mini-game collection and education.', 'Help Fifi and her friends with gardening and tasks.', 'A colorful game for kids based on the popular preschool show.', 'Fifi and the Flowertots on NDS is a delightful collection of mini-games. Children can help Fifi in the garden, solve simple puzzles, and interact with all their favorite characters in this gentle and educational adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fighting-fantasy---the-warlock-of-firetop-mountain-usa', 'NDS', 'Fighting Fantasy - The Warlock of Firetop Mountain (USA)', '2009', 'Adventure', 'Big Blue Bubble', '1', 'Interactive Fiction', 'First-person action RPG.', 'Survive the dungeon and defeat the Warlock of Firetop Mountain.', 'An RPG based on the classic Fighting Fantasy gamebook.', 'Fighting Fantasy for NDS brings the legendary book series to life as a 3D action RPG. Explore dangerous dungeons, fight terrifying monsters, and make choices that determine your fate in this dark and immersive fantasy quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('figure-princess---dugeundugeun-skating---geum-medaleul-noryeora!-korea', 'NDS', 'Figure Princess - Dugeundugeun Skating - Geum-medaleul Noryeora! (Korea)', '2009', 'Sports', 'Hudson Soft', '1', 'Simulation', 'Sports simulation and management.', 'Train your skater and win the gold medal.', 'A figure skating RPG and simulation for young players.', 'Figure Princess for NDS focuses on the life of an aspiring skater. Manage your training schedule, choose your costumes, and perform routines using rhythm-based touch controls to win international skating competitions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('figure-skating---eunban-wiui-yojeong-korea', 'NDS', 'Figure Skating - Eunban wiui Yojeong (Korea)', '2009', 'Sports', 'Hudson Soft', '1', 'Simulation', 'Sports simulation and management.', 'Train your skater and win the gold medal.', 'A figure skating RPG and simulation for young players.', 'Figure Skating: Eunban wiui Yojeong allows you to live the life of a professional skater on NDS. Balance your daily life with intense training and beautiful on-ice performances to become a world champion in this charming sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy---the-4-heroes-of-light-europe', 'NDS', 'Final Fantasy - The 4 Heroes of Light (Europe)', '2010', 'RPG', 'Square Enix', '1', 'Turn-based', 'Turn-based RPG and adventure.', 'Lead four young heroes to restore light to the world.', 'A charming retro-style RPG from the Final Fantasy series.', 'Final Fantasy: The 4 Heroes of Light offers a nostalgic yet fresh RPG experience on NDS. Featuring a unique storybook art style and a classic turn-based battle system, it follows four heroes on a grand quest to save their world.');
