INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-iii-europe-enfrdeesit', 'NDS', 'Final Fantasy III (Europe) (En,Fr,De,Es,It)', '2006', 'RPG', 'Square Enix', '1', 'Turn-based', 'Turn-based RPG with Job System.', 'Lead four orphans to restore balance as Warriors of Light.', 'A full 3D remake of the classic NES RPG masterpiece.', 'Final Fantasy III on NDS reimagines the original title with beautiful 3D graphics. Master the deep Job System, explore a dual-layered world, and engage in strategic turn-based battles in this definitive handheld RPG experience.');
