INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-iv-europe-enfrdeesit', 'NDS', 'Final Fantasy IV (Europe) (En,Fr,De,Es,It)', '2007', 'RPG', 'Square Enix', '1', 'Turn-based', 'Turn-based RPG with cinematic story.', 'Guide Cecil the Dark Knight on a quest for redemption.', 'A high-quality 3D remake of one of the most beloved RPGs.', 'Final Fantasy IV for NDS features enhanced 3D visuals, voiced cutscenes, and the innovative Augment System. Experience an emotional tale of betrayal and love as you travel from the earth to the moon.');
