INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('finde-die-unterschiede---foto-frenzy-europe-enfrdeesit', 'NDS', 'Finde die Unterschiede - Foto Frenzy (Europe) (En,Fr,De,Es,It)', '2009', 'Puzzle', 'Tivola', '1', 'Puzzle', 'Puzzle and observation.', 'Spot the differences between two similar photos.', 'A fast-paced hidden object and observation game.', 'Foto Frenzy on NDS tests your eyes with hundreds of high-quality photos. Compete against the clock to find subtle differences in various game modes, making it a perfect title for quick puzzle-solving sessions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('findet-nemo---flucht-in-den-ozean-germany', 'NDS', 'Findet Nemo - Flucht in den Ozean (Germany)', '2005', 'Action', 'Disney Interactive', '1', 'Action', 'Mini-game collection and adventure.', 'Help Nemo and his friends escape to the ocean.', 'An underwater adventure based on the Pixar movie.', 'Finding Nemo: Escape to the Big Blue for NDS features fun mini-games starring Nemo, Dory, and Marlin. Use the stylus to navigate through the Sydney harbor and avoid dangerous sea creatures in this family-friendly title.');
