INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-emblem---shadow-dragon-europe-enfrdeesit', 'NDS', 'Fire Emblem - Shadow Dragon (Europe) (En,Fr,De,Es,It)', '2008', 'Strategy RPG', 'Nintendo', '1', 'Tactical', 'Tactical turn-based strategy.', 'Lead Marth’s army to reclaim his kingdom and defeat Medeus.', 'A remake of the first entry in the legendary strategy series.', 'Fire Emblem: Shadow Dragon for NDS brings classic tactical gameplay to the dual screen. Manage your units carefully—death is permanent—as you navigate deep political intrigue and challenging grid-based warfare.');
