INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-emblem---shin-monshou-no-nazo---hikari-to-kage-no-eiyuu-japan-rev-1-ndsi-enhanced', 'NDS', 'Fire Emblem - Shin Monshou no Nazo - Hikari to Kage no Eiyuu (Japan) (Rev 1) (NDSi Enhanced)', '2010', 'Strategy RPG', 'Nintendo', '1', 'Tactical', 'Tactical turn-based strategy.', 'Create an avatar and fight alongside Marth to save the land.', 'An enhanced remake of the third Fire Emblem title.', 'Fire Emblem: Shin Monshou no Nazo on NDS introduces the Avatar system and Casual Mode. Command your army through intense battles, build relationships between units, and enjoy high-quality strategic combat in this Japanese exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fireman-sam-europe', 'NDS', 'Fireman Sam (Europe)', '2008', 'Adventure', 'Flashpoint', '1', 'Adventure', 'Mini-game collection.', 'Help Fireman Sam save the residents of Pontypandy.', 'A friendly rescue adventure for kids based on the TV show.', 'Fireman Sam on NDS brings the heroic world of Pontypandy to life. Children can help Sam and his team through various rescue-themed mini-games, teaching them about teamwork and safety in a fun, interactive way.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fish-tycoon-europe-enfrdeesit', 'NDS', 'Fish Tycoon (Europe) (En,Fr,De,Es,It)', '2008', 'Simulation', 'Last Day of Work', '1', 'Management', 'Simulation and breeding.', 'Breed and care for exotic fish to find the Magic Fish.', 'A real-time fish breeding and aquarium management sim.', 'Fish Tycoon for NDS lets you manage a virtual aquarium. Cross-breed fish, buy supplies, and sell your creations to fund your research. The game continues even when your NDS is off, making every moment of breeding count!');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fish-tycoon-usa', 'NDS', 'Fish Tycoon (USA)', '2008', 'Simulation', 'Last Day of Work', '1', 'Management', 'Simulation and breeding.', 'Breed and care for exotic fish to find the Magic Fish.', 'A real-time fish breeding and aquarium management sim.', 'Fish Tycoon for NDS lets you manage a virtual aquarium. Cross-breed fish, buy supplies, and sell your creations to fund your research. The game continues even when your NDS is off, making every moment of breeding count!');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fishdom-europe-frde', 'NDS', 'Fishdom (Europe) (Fr,De)', '2009', 'Puzzle', 'Playrix', '1', 'Puzzle', 'Match-3 puzzle and design.', 'Solve puzzles to earn money and build a dream aquarium.', 'A classic tile-matching game with aquarium customization.', 'Fishdom on NDS combines addictive match-3 gameplay with the fun of pet care. Clear boards to unlock beautiful fish and decorations, allowing you to create and maintain multiple unique underwater environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fishdom-europe-frnl', 'NDS', 'Fishdom (Europe) (Fr,Nl)', '2009', 'Puzzle', 'Playrix', '1', 'Puzzle', 'Match-3 puzzle and design.', 'Solve puzzles to earn money and build a dream aquarium.', 'A classic tile-matching game with aquarium customization.', 'Fishdom on NDS combines addictive match-3 gameplay with the fun of pet care. Clear boards to unlock beautiful fish and decorations, allowing you to create and maintain multiple unique underwater environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fit-for-fun---der-interaktive-ernaehrungscoach-germany', 'NDS', 'Fit for Fun - Der Interaktive Ernaehrungscoach (Germany)', '2009', 'Fitness', 'Deep Silver', '1', 'Lifestyle', 'Health and nutrition coaching.', 'Improve your eating habits through personal tracking.', 'An interactive nutrition coach based on the German magazine.', 'Fit for Fun for NDS provides a digital way to manage your diet. Log meals, learn about nutritional values, and follow a personalized plan to improve your overall health and well-being with this handy German guide.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fix-it-europe-enfrdeesitnl', 'NDS', 'Fix It (Europe) (En,Fr,De,Es,It,Nl)', '2009', 'Simulation', 'Black Bean Games', '1', 'Casual', 'Strategy and building.', 'Repair and renovate various objects and environments.', 'A creative "fix-it" simulation featuring diverse repairs.', 'Fix It on NDS challenges you to become a master handyman. Use the stylus to mend broken items, manage resources, and complete renovation projects in this satisfying and productive simulation game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fizz-europe-enfrdeesit', 'NDS', 'Fizz (Europe) (En,Fr,De,Es,It)', '2009', 'Puzzle', 'OSSMedia', '1', 'Puzzle', 'Puzzle and logic.', 'Connect points and create paths to clear the board.', 'A fast-paced puzzle game focused on color and flow.', 'Fizz for NDS tests your spatial reasoning and reflexes. Link energy points of the same color to create paths, clear the board, and score high points in this visually vibrant and mentally engaging puzzle experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flaaklypa-grand-prix-europe-ensvnoda', 'NDS', 'Flaaklypa Grand Prix (Europe) (En,Sv,No,Da)', '2006', 'Racing', 'Pan Vision', '1', 'Racing', 'Racing and adventure.', 'Compete in the legendary Grand Prix and solve puzzles.', 'A charming racing game based on the Norwegian film.', 'Flaklypa Grand Prix on NDS features high-speed kart racing and engaging mini-games. Join the cast of the classic stop-motion film to build your own car and win the ultimate race through beautiful Norwegian landscapes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flash-focus---vision-training-in-minutes-a-day-usa-enfres', 'NDS', 'Flash Focus - Vision Training in Minutes a Day (USA) (En,Fr,Es)', '2009', 'Educational', 'Nintendo', '1', 'Training', 'Brain training and visual exercise.', 'Improve your eye-hand coordination and focus.', 'Daily exercises designed to sharpen your visual skills.', 'Flash Focus on NDS offers a series of quick, interactive challenges to boost your eye-hand coordination, peripheral vision, and focus. Perfect for a quick "mental workout" to keep your vision sharp every day.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flipper-critters-europe-enfrdeesit', 'NDS', 'Flipper Critters (Europe) (En,Fr,De,Es,It)', '2009', 'Puzzle', 'Wildworks', '1', 'Puzzle', 'Pinball and platforming.', 'Navigate a world of pinball tables with a fantasy twist.', 'A colorful 3D pinball adventure with unique missions.', 'Flipper Critters on NDS takes pinball to a new dimension. Instead of traditional tables, play through vibrant 3D environments, complete quests for NPC animals, and master creative bumpers and ramps.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flipper-critters-usa-enfrdeesit', 'NDS', 'Flipper Critters (USA) (En,Fr,De,Es,It)', '2009', 'Puzzle', 'Wildworks', '1', 'Puzzle', 'Pinball and platforming.', 'Navigate a world of pinball tables with a fantasy twist.', 'A colorful 3D pinball adventure with unique missions.', 'Flipper Critters on NDS takes pinball to a new dimension. Instead of traditional tables, play through vibrant 3D environments, complete quests for NPC animals, and master creative bumpers and ramps.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flips-6-book-pack---cathy-cassidy-europe', 'NDS', 'Flips 6 Book Pack - Cathy Cassidy (Europe)', '2009', 'Reference', 'Trickstar', '1', 'Reading', 'Interactive e-book reader.', 'Read six popular Cathy Cassidy novels on your NDS.', 'A collection of girl-centric young adult fiction books.', 'Flips: Cathy Cassidy offers six full books on one cartridge. Enjoy interactive features like character bios, quizzes, and the ability to share chapters with friends via wireless connection on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flips-6-book-pack---enid-blyton---faraway-tree-stories-europe', 'NDS', 'Flips 6 Book Pack - Enid Blyton - Faraway Tree Stories (Europe)', '2009', 'Reference', 'Trickstar', '1', 'Reading', 'Interactive e-book reader.', 'Read six Faraway Tree stories by Enid Blyton.', 'A magical collection of classic children''s literature.', 'Flips: Enid Blyton''s Faraway Tree brings these beloved stories to NDS. Young readers can explore the enchanted woods through the dual screens, with interactive maps and sound effects that bring the magic to life.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flips-6-book-pack---eoin-colfer---artemis-fowl-europe', 'NDS', 'Flips 6 Book Pack - Eoin Colfer - Artemis Fowl (Europe)', '2009', 'Reference', 'Trickstar', '1', 'Reading', 'Interactive e-book reader.', 'Read six Artemis Fowl adventures by Eoin Colfer.', 'A high-tech thriller series in a digital book format.', 'Flips: Artemis Fowl puts the first six books of the acclaimed series in your pocket. Track Artemis’s schemes with interactive character files and hidden secrets found within the digital pages on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flips-6-book-pack---mr-gum-by-andy-stanton-europe', 'NDS', 'Flips 6 Book Pack - Mr Gum by Andy Stanton (Europe)', '2009', 'Reference', 'Trickstar', '1', 'Reading', 'Interactive e-book reader.', 'Read six hilarious Mr. Gum books by Andy Stanton.', 'A collection of wacky and surreal children''s stories.', 'Flips: Mr. Gum features the absurd humor of Andy Stanton on NDS. With sound effects and interactive elements, reading about the world''s worst man has never been more fun or portable.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flips-6-book-pack---rick-riordan---percy-jackson-europe', 'NDS', 'Flips 6 Book Pack - Rick Riordan - Percy Jackson (Europe)', '2009', 'Reference', 'Trickstar', '1', 'Reading', 'Interactive e-book reader.', 'Read six Percy Jackson adventures by Rick Riordan.', 'A mythological book collection for the NDS.', 'Flips: Percy Jackson allows you to experience the first six books of the Olympian saga. Use the interactive glossary to learn about Greek gods while following Percy''s epic quests on your handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flips-8-book-pack---enid-blyton---the-adventure-series-europe', 'NDS', 'Flips 8 Book Pack - Enid Blyton - The Adventure Series (Europe)', '2009', 'Reference', 'Trickstar', '1', 'Reading', 'Interactive e-book reader.', 'Read eight classic Enid Blyton "Adventure" books.', 'An extensive collection of vintage mystery and adventure.', 'Flips: The Adventure Series brings Enid Blyton’s timeless tales to life. Follow the children on their daring missions with interactive clues and character summaries designed specifically for the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flips-8-book-pack---too-ghoul-for-school-europe', 'NDS', 'Flips 8 Book Pack - Too Ghoul for School (Europe)', '2010', 'Reference', 'Trickstar', '1', 'Reading', 'Interactive e-book reader.', 'Read eight spooky books from the Too Ghoul series.', 'A ghostly and funny book collection for young readers.', 'Flips: Too Ghoul for School features eight interactive stories. Dive into the supernatural mysteries of St. Orrid’s School, collect virtual stickers, and enjoy spooky sound effects as you read on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('florist-shop-germany', 'NDS', 'Florist Shop (Germany)', '2009', 'Simulation', 'Tivola', '1', 'Casual', 'Simulation and time management.', 'Run a successful florist shop and create bouquets.', 'A creative floral business simulation.', 'Florist Shop for NDS lets you manage your own flower business. Plant seeds, water flowers, and create beautiful arrangements for your customers to grow your shop’s reputation in this colorful and relaxing sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('florist-shop-usa', 'NDS', 'Florist Shop (USA)', '2009', 'Simulation', 'Tivola', '1', 'Casual', 'Simulation and time management.', 'Run a successful florist shop and create bouquets.', 'A creative floral business simulation.', 'Florist Shop for NDS lets you manage your own flower business. Plant seeds, water flowers, and create beautiful arrangements for your customers to grow your shop’s reputation in this colorful and relaxing sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flower-sun-and-rain---murder-and-mystery-in-paradise-europe-enfrdeesit', 'NDS', 'Flower, Sun and Rain - Murder and Mystery in Paradise (Europe) (En,Fr,De,Es,It)', '2009', 'Adventure', 'Grasshopper Manufacture', '1', 'Mystery', 'Surreal mystery and adventure.', 'Solve a series of murders through time loops and puzzles.', 'A cult-classic detective adventure from Goichi Suda.', 'Flower, Sun and Rain on NDS is a unique, philosophical mystery. Play as Sumio Mondo, solving bizarre puzzles with your suitcase computer, "L some," to break a time loop on a mysterious tropical island.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flower-sun-and-rain---murder-and-mystery-in-paradise-usa', 'NDS', 'Flower, Sun and Rain - Murder and Mystery in Paradise (USA)', '2009', 'Adventure', 'Grasshopper Manufacture', '1', 'Mystery', 'Surreal mystery and adventure.', 'Solve a series of murders through time loops and puzzles.', 'A cult-classic detective adventure from Goichi Suda.', 'Flower, Sun and Rain on NDS is a unique, philosophical mystery. Play as Sumio Mondo, solving bizarre puzzles with your suitcase computer, "L some," to break a time loop on a mysterious tropical island.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flunkerne---paa-maanen-europe-noda', 'NDS', 'Flunkerne - Paa Maanen (Europe) (No,Da)', '2008', 'Adventure', 'Pan Vision', '1', 'Adventure', 'Hidden object and mini-games.', 'Find the Flunkerne hidden on the moon.', 'A Danish hidden object game based on the popular series.', 'Flunkerne: Paa Maanen for NDS challenges your observation skills. Search for the tiny Flunkerne characters in intricate moon landscapes, solve puzzles, and play mini-games in this charming Scandinavian title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flunkerne---superskurke-europe-noda', 'NDS', 'Flunkerne - Superskurke (Europe) (No,Da)', '2009', 'Adventure', 'Pan Vision', '1', 'Adventure', 'Hidden object and mini-games.', 'Track down the supervillain Flunkerne.', 'A fun search-and-find adventure with a hero theme.', 'Flunkerne: Superskurke on NDS brings more hidden object fun. Navigate through superhero-themed levels to find the mischievous Flunkerne and stop their villainous plans through various interactive challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flushed-away-europe', 'NDS', 'Flushed Away (Europe)', '2006', 'Action', 'Art Co.', '1', 'Action', 'Platforming and puzzle.', 'Help Roddy and Rita escape the sewers and reach home.', 'An action-adventure based on the DreamWorks movie.', 'Flushed Away on NDS lets you control Roddy and Rita in their quest to return to Kensington. Use the stylus to pilot boats and defeat enemies in this fun-filled adventure through the underground world of Ratropolis.');
