INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('foot-2-rue---nicolas-anelka-europe-enfrit', 'NDS', 'Foot 2 Rue - Nicolas Anelka (Europe) (En,Fr,It)', '2003', 'Sports', 'Digital Chocolate', '1', 'Soccer', 'Street soccer and skill moves.', 'Win street football matches and complete skill challenges.', 'An urban soccer game featuring star striker Nicolas Anelka.', 'Foot 2 Rue: Nicolas Anelka brings high-energy street soccer to NDS. Perform incredible tricks, build your urban team, and compete in gritty city environments to become a street legend in this fast-paced football title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('football-academy---build-and-prove-your-football-knowledge-europe-enfrdeesit', 'NDS', 'Football Academy - Build and Prove Your Football Knowledge (Europe) (En,Fr,De,Es,It)', '2009', 'Sports', 'SEGA', '1', 'Education', 'Sports trivia and training.', 'Test and build your knowledge of football facts and history.', 'A specialized quiz game for ultimate football fans.', 'Football Academy challenges your soccer IQ. Tackle thousands of questions about players, teams, and history. Prove you are a true expert and build your reputation as the most knowledgeable fan in the academy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('football-director-ds-europe', 'NDS', 'Football Director DS (Europe)', '2009', 'Simulation', 'Cypronia', '1', 'Management', 'Sports management simulation.', 'Manage a football club and lead them to the top league.', 'A deep and strategic football management experience.', 'Football Director DS puts you in the manager''s seat. Handle transfers, set tactics, and oversee club finances. Experience the pressure of match days as you make critical decisions to secure victory for your team.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ford-racing-3-europe-enfrdeesit', 'NDS', 'Ford Racing 3 (Europe) (En,Fr,De,Es,It)', '2004', 'Racing', 'Razorworks', '4', 'Arcade', 'Arcade circuit racing.', 'Win races and unlock a wide variety of Ford vehicles.', 'A high-speed racer featuring officially licensed Ford cars.', 'Ford Racing 3 on NDS offers a massive garage of classic and modern Ford vehicles. Compete across diverse tracks, from off-road trails to professional circuits, and master the unique handling of each legendary model.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ford-racing-3-usa', 'NDS', 'Ford Racing 3 (USA)', '2004', 'Racing', 'Razorworks', '4', 'Arcade', 'Arcade circuit racing.', 'Win races and unlock a wide variety of Ford vehicles.', 'A high-speed racer featuring officially licensed Ford cars.', 'Ford Racing 3 on NDS offers a massive garage of classic and modern Ford vehicles. Compete across diverse tracks, from off-road trails to professional circuits, and master the unique handling of each legendary model.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fort-boyard---casse-tetes-&-enigmes-france', 'NDS', 'Fort Boyard - Casse-tetes & Enigmes (France)', '2009', 'Puzzle', 'Mindscape', '1', 'Quiz', 'Puzzle and brain training.', 'Solve the riddles of the fort to collect keys and coins.', 'A puzzle collection based on the famous French TV show.', 'Fort Boyard: Casse-tetes & Enigmes focuses on the mental challenges of the fort. Solve complex riddles and logic puzzles to unlock secrets, providing a perfect brain-training experience for fans of the iconic show.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fort-boyard---le-jeu-france', 'NDS', 'Fort Boyard - Le Jeu (France)', '2008', 'Party', 'Mindscape', '4', 'MiniGames', 'Action adventure and mini-games.', 'Complete physical and mental trials to win the treasure.', 'The official video game of the legendary Fort Boyard.', 'Fort Boyard: Le Jeu captures the excitement of the TV program. Navigate the stone corridors of the fort, compete in classic physical trials, and outsmart the masters to win as much gold as possible on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fort-boyard---le-jeu-france-rev-1', 'NDS', 'Fort Boyard - Le Jeu (France) (Rev 1)', '2008', 'Party', 'Mindscape', '4', 'MiniGames', 'Action adventure and mini-games.', 'Complete physical and mental trials to win the treasure.', 'The official video game of the legendary Fort Boyard.', 'Fort Boyard: Le Jeu captures the excitement of the TV program. Navigate the stone corridors of the fort, compete in classic physical trials, and outsmart the masters to win as much gold as possible on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fossil-fighters-usa', 'NDS', 'Fossil Fighters (USA)', '2008', 'RPG', 'Red Entertainment', '1', 'TurnBased', 'RPG and monster battling.', 'Dig up fossils, revive dinosaurs, and battle other fighters.', 'An addictive monster-collection RPG with ancient fossils.', 'Fossil Fighters lets you become a Master Fighter. Use the stylus to carefully clean fossils, revive powerful Vivosaurs, and engage in strategic 3-on-3 turn-based battles to become the world champion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fossil-league---dino-tournament-championship-europe', 'NDS', 'Fossil League - Dino Tournament Championship (Europe)', '2008', 'Strategy', 'SmileBoom', '1', 'TurnBased', 'Strategy and dinosaur battling.', 'Collect dinosaur cards and win the tournament championship.', 'A tactical card-battle RPG featuring prehistoric beasts.', 'Fossil League: Dino Tournament Championship tasks you with assembling the ultimate dinosaur team. Battle through multiple eras, collect rare species, and use elemental strategies to dominate the global prehistoric arena.');
