INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fosters-home-for-imaginary-friends---imagination-invaders-europe', 'NDS', 'Foster''s Home for Imaginary Friends - Imagination Invaders (Europe)', '2009', 'Platformer', 'Altron', '1', 'Cartoon', 'Action adventure and platforming.', 'Rescue the imaginary friends from alien invaders.', 'A wacky adventure based on the hit Cartoon Network show.', 'Foster''s Home: Imagination Invaders brings Bloo and Mac to NDS. Explore the mansion, solve puzzles, and use "imagination powers" to defeat the Space Nut Boogies and save your friends in this colorful quest.');
