INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('foto-frenzy---spot-the-difference-usa-enfres', 'NDS', 'Foto Frenzy - Spot the Difference (USA) (En,Fr,Es)', '2006', 'Puzzle', 'DSI Games', '1', 'SpotDifference', 'Puzzle and observation.', 'Find the differences between two images before time runs out.', 'A classic "spot the difference" game with high-quality photos.', 'Foto Frenzy on NDS challenges your eyes. Compare similar images, spot the subtle changes, and clear hundreds of levels. A relaxing yet stimulating game perfect for sharpening your attention to detail.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('franklins-great-adventures-europe-enfrdeesitnlptda', 'NDS', 'Franklin''s Great Adventures (Europe) (En,Fr,De,Es,It,Nl,Pt,Da)', '2007', 'Adventure', 'Neko Entertainment', '1', 'Family', 'Adventure and mini-games.', 'Help Franklin and his friends complete woodland tasks.', 'A gentle educational adventure for young children.', 'Franklin''s Great Adventures on NDS features the beloved turtle in a series of heartwarming quests. Solve puzzles and play mini-games that teach valuable life lessons about friendship and helping others.');
