INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('franzoesisch-buddy-europe-frdeesit', 'NDS', 'Franzoesisch Buddy (Europe) (Fr,De,Es,It)', '2008', 'Education', 'Europress', '1', 'Language', 'Language learning and drills.', 'Learn French vocabulary and grammar through mini-games.', 'An interactive French language tutor for beginners.', 'Franzoesisch Buddy makes learning French accessible on NDS. Practice pronunciation, build your vocabulary, and track your progress with daily lessons and quizzes designed for effective language acquisition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('freddi-fish---abc-under-the-sea-europe-enfrdeesitnl', 'NDS', 'Freddi Fish - ABC under the Sea (Europe) (En,Fr,De,Es,It,Nl)', '2009', 'Education', 'Humongous Entertainment', '1', 'Educational', 'Educational and mini-games.', 'Help Freddi Fish learn the alphabet and solve puzzles.', 'A preschool educational game featuring the famous fish.', 'Freddi Fish: ABC under the Sea teaches young children letters and early reading skills. Join Freddi and Luther for fun underwater activities that make learning the alphabet a joyful adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('freddie-flintoffs-power-play-cricket-europe', 'NDS', 'Freddie Flintoff''s Power Play Cricket (Europe)', '2009', 'Sports', 'Codemasters', '4', 'Cricket', 'Sports simulation and action.', 'Win cricket matches and master batting and bowling.', 'A fast-paced cricket game featuring Freddie Flintoff.', 'Freddie Flintoff''s Power Play Cricket brings the excitement of the sport to NDS. Use intuitive stylus controls to hit boundaries and take wickets in various international match formats and skill challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('freedom-wings-europe', 'NDS', 'Freedom Wings (Europe)', '2006', 'Simulation', 'Nintendo', '1', 'Flight', 'Flight simulation and RPG.', 'Pilot a plane, fight aerial battles, and upgrade your aircraft.', 'A unique mix of flight simulation and role-playing.', 'Freedom Wings on NDS lets you take to the skies. Engage in intense dogfights, complete diverse missions, and customize your plane with better engines and weapons to become the ultimate ace pilot.');
