INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fresh-precure!---asobi-collection-japan', 'NDS', 'Fresh PreCure! - Asobi Collection (Japan)', '2009', 'Action', 'Bandai', '1', 'Anime', 'Mini-game collection and girls'' lifestyle.', 'Complete tasks and dress up with the PreCure characters.', 'A colorful mini-game collection based on the anime.', 'Fresh PreCure! Asobi Collection for NDS is filled with fun activities. From cooking and fashion to rhythm games, join the PreCure girls in a variety of challenges designed for fans of the magical girl series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('freshly-picked---tingles-rosy-rupeeland-europe-enfrdeesit', 'NDS', 'Freshly-Picked - Tingle''s Rosy Rupeeland (Europe) (En,Fr,De,Es,It)', '2007', 'Adventure', 'Vanpool', '1', 'StoryDriven', 'Adventure and economy sim.', 'Collect rupees to reach the legendary Rupeeland.', 'A quirky and dark Legend of Zelda spin-off starring Tingle.', 'Freshly-Picked: Tingle''s Rosy Rupeeland is a unique NDS adventure. Barter for everything, fight bizarre monsters, and hoard money to grow your tower and discover Tingle''s true destiny in this cult-classic title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fritz-europe-enfrdeesit', 'NDS', 'Fritz (Europe) (En,Fr,De,Es,It)', '2008', 'Puzzle', 'AI Factory', '1', 'BoardGame', 'Chess simulation.', 'Defeat AI opponents and improve your chess rating.', 'A professional-grade chess engine for the NDS.', 'Fritz on NDS provides a world-class chess experience. Whether you are a beginner or a grandmaster, the game offers tailored challenges, move analysis, and a library of famous matches to learn from.');
