INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('frogger---helmet-chaos-europe-enfrdeesit', 'NDS', 'Frogger - Helmet Chaos (Europe) (En,Fr,De,Es,It)', '2005', 'Platformer', 'KCEJ', '1', 'Arcade', 'Platforming and puzzle.', 'Navigate Frogger through dangerous levels to stop Dr. Frog.', 'A modern 3D update of the classic arcade franchise.', 'Frogger: Helmet Chaos brings the famous frog to NDS with challenging platforming. Avoid obstacles, solve environmental puzzles, and use Frogger’s tongue to navigate through vibrant worlds in this action-packed revival.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('frogger---helmet-chaos-usa', 'NDS', 'Frogger - Helmet Chaos (USA)', '2005', 'Platformer', 'KCEJ', '1', 'Arcade', 'Platforming and puzzle.', 'Navigate Frogger through dangerous levels to stop Dr. Frog.', 'A modern 3D update of the classic arcade franchise.', 'Frogger: Helmet Chaos brings the famous frog to NDS with challenging platforming. Avoid obstacles, solve environmental puzzles, and use Frogger’s tongue to navigate through vibrant worlds in this action-packed revival.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('frogman-show-ds-the---datte-shouganai-janai-japan', 'NDS', 'Frogman Show D.S., The - Datte, Shouganai Janai. (Japan)', '2006', 'Action', 'D3 Publisher', '1', 'Comedy', 'Surreal comedy and mini-games.', 'Experience the bizarre humor of the Frogman Show.', 'A unique Japanese comedy game with wacky challenges.', 'The Frogman Show D.S. is an eccentric collection of mini-games and interactive segments. Fans of the Flash animation series will love the signature voice acting and the absurd, hilarious situations only this cast can provide.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('from-the-abyss-europe-enfrdeesit', 'NDS', 'From the Abyss (Europe) (En,Fr,De,Es,It)', '2008', 'Action', 'Sonic Powered', '1', 'Arcade', 'Action RPG and dungeon crawling.', 'Explore the Abyss and defeat waves of monsters.', 'A fast-paced hack-and-slash RPG with customization.', 'From the Abyss on NDS offers classic dungeon exploration. Customize your character''s skills, loot powerful weapons, and conquer procedurally generated maps as you fight to close the gates of the underworld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('from-the-abyss-japan', 'NDS', 'From the Abyss (Japan)', '2008', 'Action', 'Sonic Powered', '1', 'Arcade', 'Action RPG and dungeon crawling.', 'Explore the Abyss and defeat waves of monsters.', 'A fast-paced hack-and-slash RPG with customization.', 'From the Abyss on NDS offers classic dungeon exploration. Customize your character''s skills, loot powerful weapons, and conquer procedurally generated maps as you fight to close the gates of the underworld.');
