INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('front-mission-usa', 'NDS', 'Front Mission (USA)', '2005', 'RPG', 'G-Craft', '1', 'Tactical', 'Tactical turn-based strategy.', 'Command mecha units (Wanzers) to win a futuristic war.', 'A deep tactical RPG featuring customizable mechs.', 'Front Mission on NDS is a definitive remake of the strategy classic. Build and customize your Wanzers, manage your squad’s equipment, and navigate a mature, political story set in a gritty future conflict.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('front-mission-1st-japan', 'NDS', 'Front Mission 1st (Japan)', '2003', 'RPG', 'Square Enix', '1', 'Tactical', 'Tactical turn-based strategy.', 'Command mecha units (Wanzers) to win a futuristic war.', 'A deep tactical RPG featuring customizable mechs.', 'Front Mission 1st brings the original mecha strategy epic to NDS. Experience refined gameplay, detailed pixel art, and intense tactical combat as you fight for survival on Huffman Island.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('front-mission-2089---border-of-madness-japan', 'NDS', 'Front Mission 2089 - Border of Madness (Japan)', '2007', 'RPG', 'Square Enix', '1', 'Tactical', 'Tactical turn-based strategy.', 'Navigate a dark military story in the Front Mission world.', 'A gritty tactical RPG following a mercenary group.', 'Front Mission 2089: Border of Madness offers a deep narrative experience for NDS. Command your mercenary squad in strategic Wanzer combat, solve tactical puzzles, and survive a web of military conspiracies in this Japan-exclusive entry.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fruits-mura-no-doubutsu-tachi-2---osora-no-fruits-land-japan', 'NDS', 'Fruits Mura no Doubutsu-tachi 2 - Osora no Fruits Land (Japan)', '2007', 'Simulation', 'Success', '1', 'LifeSim', 'Life simulation and mini-games.', 'Interact with animal friends in a colorful fruit kingdom.', 'A cute social simulation game for young players.', 'Fruits Mura no Doubutsu-tachi 2 on NDS invites you to a world of adorable animals and fruit-themed fun. Complete simple tasks, play mini-games, and build friendships in this charming and relaxing Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fruits-mura-no-doubutsu-tachi-2---osora-no-fruits-land-japan-rev-1', 'NDS', 'Fruits Mura no Doubutsu-tachi 2 - Osora no Fruits Land (Japan) (Rev 1)', '2007', 'Simulation', 'Success', '1', 'LifeSim', 'Life simulation and mini-games.', 'Interact with animal friends in a colorful fruit kingdom.', 'A cute social simulation game for young players.', 'Fruits Mura no Doubutsu-tachi 2 on NDS invites you to a world of adorable animals and fruit-themed fun. Complete simple tasks, play mini-games, and build friendships in this charming and relaxing Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fuehrerschein-coach-2008-germany', 'NDS', 'Fuehrerschein Coach 2008 (Germany)', '2008', 'Education', 'Tivola', '1', 'Driving', 'Educational and exam prep.', 'Study and pass the German driving license theory test.', 'A comprehensive study guide for the 2008 driving exam.', 'Fuehrerschein Coach 2008 for NDS is a professional training tool. It features official questionnaire sets, traffic sign recognition, and mock exams to ensure you are fully prepared for the German theoretical driving test.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fuehrerschein-trainer-germany', 'NDS', 'Fuehrerschein-Trainer (Germany)', '2006', 'Education', 'Tivola', '1', 'Driving', 'Educational and exam prep.', 'Practice driving rules to prepare for the license exam.', 'An interactive trainer for the German driving theory test.', 'Fuehrerschein-Trainer on NDS provides a portable classroom experience. Test your knowledge of road safety, right-of-way rules, and technical questions through engaging drills and full-length practice examinations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fujimori-midori-no-lets-tarot---anata-mo-kyou-kara-uranaishi-japan', 'NDS', 'Fujimori Midori no Let''s Tarot - Anata mo Kyou kara Uranaishi (Japan)', '2009', 'Simulation', 'Marvelous', '1', 'Tarot', 'Tarot reading and simulation.', 'Learn to read Tarot cards and predict the future.', 'An interactive guide to the art of Tarot reading.', 'Fujimori Midori no Let''s Tarot turns your NDS into a fortune-telling tool. Learn the meanings of the Major and Minor Arcana, practice different spreads, and give readings to your friends in this detailed Japanese guide.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fukoumori---molily-no-unhappy-project-japan', 'NDS', 'Fukoumori - Molily no Unhappy Project (Japan)', '2009', 'Adventure', 'Irem', '1', 'StoryDriven', 'Simulation and strategy.', 'Help Molily manage "unhappy" situations through puzzles.', 'A quirky Japanese game focused on misfortune and luck.', 'Fukoumori: Molily no Unhappy Project offers a unique concept on NDS. Navigate through eccentric scenarios, solve social puzzles, and explore the bizarre world of Molily in this creative and humorous simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fullmetal-alchemist---dual-sympathy-europe', 'NDS', 'Fullmetal Alchemist - Dual Sympathy (Europe)', '2007', 'Action', 'Bandai', '1', 'Anime', 'Side-scrolling beat ''em up.', 'Follow the Elric brothers and stop the homunculi.', 'An action-packed brawler based on the hit anime.', 'Fullmetal Alchemist: Dual Sympathy brings the journey of Ed and Al to NDS. Use the touch screen to perform alchemy, battle powerful bosses, and experience the epic story through intense side-scrolling combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fullmetal-alchemist---dual-sympathy-usa', 'NDS', 'Fullmetal Alchemist - Dual Sympathy (USA)', '2007', 'Action', 'Bandai', '1', 'Anime', 'Side-scrolling beat ''em up.', 'Follow the Elric brothers and stop the homunculi.', 'An action-packed brawler based on the hit anime.', 'Fullmetal Alchemist: Dual Sympathy brings the journey of Ed and Al to NDS. Use the touch screen to perform alchemy, battle powerful bosses, and experience the epic story through intense side-scrolling combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fullmetal-alchemist---trading-card-game-usa', 'NDS', 'Fullmetal Alchemist - Trading Card Game (USA)', '2007', 'Card', 'Bandai', '2', 'Trading', 'Digital trading card game.', 'Build a powerful deck and defeat opponents in duels.', 'A strategic card-battle game set in the FMA universe.', 'Fullmetal Alchemist TCG for NDS digitizes the popular card game. Collect hundreds of cards, build custom decks using your favorite characters, and use strategic alchemy to outsmart your rivals in tactical card duels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fushigi-kagaku---nazotoki-quiz-training---nazotore-japan', 'NDS', 'Fushigi Kagaku - Nazotoki Quiz Training - Nazotore (Japan)', '2008', 'Education', 'Nintendo', '1', 'Quiz', 'Trivia and logic training.', 'Solve science-based quizzes and brain teasers.', 'An educational puzzle game focused on curious facts.', 'Fushigi Kagaku: Nazotoki Quiz Training challenges your mind on NDS. Learn fascinating scientific facts through interactive quizzes and logic puzzles designed to entertain while educating users of all ages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fushigi-no-dungeon---fuurai-no-shiren-4---kami-no-hitomi-to-akuma-no-heso-japan', 'NDS', 'Fushigi no Dungeon - Fuurai no Shiren 4 - Kami no Hitomi to Akuma no Heso (Japan)', '2010', 'RPG', 'Spike', '1', 'Roguelike', 'Roguelike dungeon crawler.', 'Navigate the dungeon and retrieve the Eye of God.', 'A challenging turn-based RPG with permadeath.', 'Shiren the Wanderer 4 on NDS offers a brutal and rewarding experience. Explore procedurally generated floors, manage your hunger and items, and master the deep tactical combat that the Mystery Dungeon series is famous for.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fushigi-no-dungeon---fuurai-no-shiren-5---fortune-tower-to-unmei-no-dice-japan', 'NDS', 'Fushigi no Dungeon - Fuurai no Shiren 5 - Fortune Tower to Unmei no Dice (Japan)', '2015', 'RPG', 'Spike', '1', 'Roguelike', 'Roguelike dungeon crawler.', 'Climb the Fortune Tower to change your destiny.', 'A deep and atmospheric Mystery Dungeon entry.', 'Shiren the Wanderer 5 brings stunning pixel art and complex mechanics to NDS. Use the Dice of Fate, encounter new monsters, and survive the perils of the tower in this definitive roguelike adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fushigi-no-dungeon---fuurai-no-shiren-ds-japan', 'NDS', 'Fushigi no Dungeon - Fuurai no Shiren DS (Japan)', '2004', 'RPG', 'Chunsoft', '1', 'Roguelike', 'Roguelike dungeon crawler.', 'Survive the dungeon and reach the top of Table Mountain.', 'A remake of the classic SNES roguelike for NDS.', 'Shiren the Wanderer DS is the perfect entry point for the genre. Experience the classic turn-based exploration where every move matters, and a single mistake can mean losing all your hard-earned equipment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fushigi-no-dungeon---fuurai-no-shiren-ds-2---sabaku-no-majou-japan', 'NDS', 'Fushigi no Dungeon - Fuurai no Shiren DS 2 - Sabaku no Majou (Japan)', '2008', 'RPG', 'Chunsoft', '1', 'Roguelike', 'Roguelike dungeon crawler.', 'Protect the Desert Castle from a monstrous threat.', 'The NDS sequel to the original Shiren the Wanderer.', 'Shiren the Wanderer DS 2 expands the adventure with a new setting. Battle through trap-filled dungeons, recruit allies, and upgrade your gear to survive the harsh desert environments in this tactical RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fushigi-yuugi-ds-japan', 'NDS', 'Fushigi Yuugi DS (Japan)', '2009', 'Adventure', 'Idea Factory', '1', 'VisualNovel', 'Visual novel and romance.', 'Navigate the story and build relationships with characters.', 'An interactive novel based on the Fushigi Yuugi series.', 'Fushigi Yuugi DS brings the classic shojo manga to life. Make choices that affect the story''s outcome, experience romantic subplots, and interact with the Seven Celestial Warriors in this beautifully illustrated adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('futari-wa-precure-max-heart---danzen!-ds-de-precure---chikara-o-awasete-dai-battle!!-japan', 'NDS', 'Futari wa PreCure Max Heart - Danzen! DS de PreCure - Chikara o Awasete Dai-battle!! (Japan)', '2006', 'Action', 'Bandai', '1', 'Anime', 'Action and mini-games.', 'Battle enemies alongside the PreCure magical girls.', 'A colorful action game based on the Max Heart anime.', 'Futari wa PreCure Max Heart on NDS features fast-paced combat and fun challenges. Join Nagisa and Honoka to protect the Garden of Light through interactive touch-screen battles and engaging mini-games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('futari-wa-precure-splash-star---panpaka-game-de-zekkouchou!-japan', 'NDS', 'Futari wa PreCure Splash Star - Panpaka Game de Zekkouchou! (Japan)', '2006', 'Action', 'Bandai', '1', 'Anime', 'Mini-game collection.', 'Complete tasks and play games with the Splash Star cast.', 'A vibrant collection of games for PreCure fans.', 'Futari wa PreCure Splash Star offers a variety of fun activities on NDS. From cooking to puzzles, join Saki and Mai in a colorful world full of friendship and magical girl excitement.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('futureu---the-prep-game-for-sat-usa', 'NDS', 'futureU - The Prep Game for SAT (USA)', '2009', 'Education', 'FutureU', '1', 'TestPrep', 'Educational and test prep.', 'Study and take mock exams to prepare for the SAT.', 'A gamified SAT prep tool for high school students.', 'futureU: The Prep Game for SAT makes studying portable on NDS. Track your progress in Math, Reading, and Writing through interactive drills and practice tests designed to boost your scores in a fun way.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fuuun!-dairoujou-japan', 'NDS', 'Fuuun! Dairoujou (Japan)', '2009', 'Action', 'Taito', '2', 'Arcade', 'Tower defense and strategy.', 'Defend the castle from waves of attacking enemies.', 'A classic tower defense game with a historical Japanese theme.', 'Fuuun! Dairoujou tasks you with protecting ancient fortresses on NDS. Strategically place your units, manage your resources, and survive massive sieges in this challenging and tactical defense game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('g-force-europe-deit', 'NDS', 'G-Force (Europe) (De,It)', '2009', 'Action', 'Eurocom', '1', 'Platformer', 'Action-adventure and platforming.', 'Use high-tech gadgets to stop an evil billionaire.', 'An action game based on the Disney movie G-Force.', 'G-Force for NDS puts you in control of Darwin the guinea pig. Use your jetpack and specialized gadgets to navigate levels, hack electronic devices, and fight off a robotic army in this exciting spy adventure.');
