INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gg-series-collection+-japan', 'NDS', 'G.G Series Collection+ (Japan)', '2010', 'Compilation', 'G-Mode', '1', 'Arcade', 'Mini-game collection.', 'Master a huge variety of retro-style arcade games.', 'A massive collection of over 30 arcade-style titles.', 'G.G Series Collection+ on NDS is a treasure trove for arcade fans. Featuring shooters, platformers, and puzzles, this collection offers dozens of high-quality, bite-sized experiences that are perfect for gaming on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gi-joe---the-rise-of-cobra-europe-enfrdeesit', 'NDS', 'G.I. Joe - The Rise of Cobra (Europe) (En,Fr,De,Es,It)', '2009', 'Action', 'Double Helix', '1', 'Shooter', 'Action and combat.', 'Lead the G.I. Joe team to stop the Cobra organization.', 'A fast-paced action game based on the movie.', 'G.I. Joe: The Rise of Cobra on NDS lets you play as iconic heroes. Fight through intense missions, use specialized vehicles, and upgrade your gear to thwart the global threat of Cobra in this action-packed title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gi-joe---the-rise-of-cobra-usa-enfres', 'NDS', 'G.I. Joe - The Rise of Cobra (USA) (En,Fr,Es)', '2009', 'Action', 'Double Helix', '1', 'Shooter', 'Action and combat.', 'Lead the G.I. Joe team to stop the Cobra organization.', 'A fast-paced action game based on the movie.', 'G.I. Joe: The Rise of Cobra on NDS lets you play as iconic heroes. Fight through intense missions, use specialized vehicles, and upgrade your gear to thwart the global threat of Cobra in this action-packed title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gabu-gabu-planet-japan', 'NDS', 'Gabu Gabu Planet (Japan)', '2006', 'Action', 'Nintendo', '1', 'Arcade', 'Physics-based action.', 'Guide Gabu the creature and devour objects to grow.', 'A quirky Japanese game with addictive eating mechanics.', 'Gabu Gabu Planet is a unique physics game for NDS. Use the stylus to help Gabu eat everything in sight, growing larger and overcoming environmental obstacles in this colorful and eccentric adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gachapin-challenge-ds-japan', 'NDS', 'Gachapin Challenge DS (Japan)', '2006', 'Party', 'Nintendo', '1', 'MiniGames', 'Mini-game collection.', 'Complete the "Gachapin Challenge" through various sports.', 'A fun collection of games starring the famous Japanese mascot.', 'Gachapin Challenge DS features the green dinosaur in a series of athletic trials. From snowboarding to skydiving, use the NDS controls to master each sport and clear every challenge in the game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gachapin-nikki-ds-japan', 'NDS', 'Gachapin Nikki DS (Japan)', '2006', 'Party', 'Nintendo', '1', 'MiniGames', 'Lifestyle simulation and diary.', 'Manage your daily life and interact with Gachapin and Mukku.', 'A personal diary and simulation app featuring Gachapin.', 'Gachapin Nikki DS is more than a game; it''s a digital companion. Use the calendar, track your health, and read Gachapin''s daily entries while playing mini-games with the famous Japanese characters on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gaitame-baibai-trainer---kabutore-fx-japan', 'NDS', 'Gaitame Baibai Trainer - Kabutore FX (Japan)', '2009', 'Finance', 'Success', '1', 'Trading', 'Financial simulation and training.', 'Learn the basics of Forex (FX) trading and maximize profit.', 'A realistic foreign exchange market training simulator.', 'Gaitame Baibai Trainer teaches you the world of currency trading on NDS. Practice with real-time charts and market scenarios to learn when to buy and sell, helping you master the fundamentals of the FX market.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gakken---chuugokugo-zanmai-ds-japan', 'NDS', 'Gakken - Chuugokugo Zanmai DS (Japan)', '2008', 'Education', 'Gakken', '1', 'Language', 'Language learning and drills.', 'Master Chinese vocabulary and grammar through practice.', 'A comprehensive Chinese language tutor for Japanese speakers.', 'Gakken: Chuugokugo Zanmai DS offers a structured way to learn Chinese. Featuring dictation, listening exercises, and writing drills, it turns your NDS into a powerful educational tool for mastering a new language.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gakken-ds---otona-no-gakushuu---kindaichi-sensei-no-nihongo-lesson-japan', 'NDS', 'Gakken DS - Otona no Gakushuu - Kindaichi Sensei no Nihongo Lesson (Japan)', '2007', 'Education', 'Gakken', '1', 'Language', 'Educational and language practice.', 'Master proper Japanese grammar and kanji usage.', 'A refined Japanese language lesson for adults.', 'Kindaichi Sensei no Nihongo Lesson on NDS offers a sophisticated way to polish your Japanese skills. Under the guidance of the famous linguist, practice correct honorifics, kanji, and vocabulary through interactive drills and quizzes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gakken-ds---shin-toeic-test-kanzen-kouryaku-japan', 'NDS', 'Gakken DS - Shin TOEIC Test Kanzen Kouryaku (Japan)', '2007', 'Education', 'Gakken', '1', 'TestPrep', 'Educational and test prep.', 'Prepare for the TOEIC English proficiency exam.', 'A comprehensive study guide for the TOEIC test.', 'Gakken DS: Shin TOEIC Test offers a complete preparation package on NDS. Featuring thousands of practice questions, listening exercises, and mock exams, it’s the perfect tool for students and professionals aiming for a high TOEIC score.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gakken-eigo-zanmai-ds-japan', 'NDS', 'Gakken Eigo Zanmai DS (Japan)', '2006', 'Education', 'Gakken', '1', 'Language', 'Language learning and drills.', 'Improve English proficiency through daily practice.', 'An interactive English language trainer for Japanese speakers.', 'Gakken Eigo Zanmai DS provides a structured approach to learning English. Use the stylus for dictation, practice listening comprehension, and track your vocabulary growth with this portable and effective language learning tool.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gakken-hangeul-zanmai-ds-japan', 'NDS', 'Gakken Hangeul Zanmai DS (Japan)', '2007', 'Education', 'Gakken', '1', 'Language', 'Language learning and drills.', 'Master the Korean Hangeul alphabet and vocabulary.', 'A comprehensive Korean language tutor for beginners.', 'Gakken Hangeul Zanmai DS makes learning Korean accessible on NDS. From writing Hangeul characters to mastering basic grammar and conversation, this trainer uses the touch screen to help you build a strong linguistic foundation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gakken-m-bunko-presents---monoshiri-edo-meijin-japan', 'NDS', 'Gakken M Bunko Presents - Monoshiri Edo Meijin (Japan)', '2009', 'Education', 'Gakken', '1', 'Reference', 'Trivia and history educational.', 'Learn about the history and culture of the Edo period.', 'A cultural quiz and trivia game about historical Japan.', 'Monoshiri Edo Meijin turns history into a game. Test your knowledge of Edo-era society, famous figures, and daily life through interactive quizzes and detailed encyclopedic entries on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gakken-mainichi-no-drill-ds---mezase!-miracle-shougaku-1-nensei-japan', 'NDS', 'Gakken Mainichi no Drill DS - Mezase! Miracle Shougaku 1 Nensei (Japan)', '2007', 'Education', 'Gakken', '1', 'School', 'Educational and school prep.', 'Complete daily drills to prepare for the first grade.', 'A comprehensive school readiness trainer for children.', 'Mezase! Miracle Shougaku 1 Nensei on NDS helps kids master basic math and reading. Designed for young learners, it uses fun characters and rewarding mini-games to build confidence for the first year of elementary school.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gakken-mu-henshuubu-kanshuu---choujou-genshou-research-file-japan', 'NDS', 'Gakken Mu Henshuubu Kanshuu - Choujou Genshou Research File (Japan)', '2008', 'Education', 'Gakken', '1', 'Mystery', 'Mystery and research simulation.', 'Investigate paranormal phenomena and urban legends.', 'A unique research-based game about supernatural events.', 'Choujou Genshou Research File for NDS lets you dive into the world of the occult. Research UFOs, ghosts, and cryptids through interactive files and investigation mini-games based on Mu magazine''s famous archives.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gakken-youten-rank-jun-series---kagaku-ds-japan', 'NDS', 'Gakken Youten Rank Jun Series - Kagaku DS (Japan)', '2008', 'Education', 'Gakken', '1', 'Science', 'Educational and science drills.', 'Master essential science topics for junior high exams.', 'A science-focused study aid for Japanese students.', 'Gakken Youten Rank Jun Series: Kagaku DS focuses on key scientific concepts. Organize your study by importance and master chemistry, biology, and physics through concise lessons and targeted practice quizzes on NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gakken-youten-rank-jun-series---nihon-no-rekishi-ds-japan', 'NDS', 'Gakken Youten Rank Jun Series - Nihon no Rekishi DS (Japan)', '2009', 'Education', 'Gakken', '1', 'History', 'Educational and history drills.', 'Learn Japanese history in chronological order.', 'A chronological history trainer for exam preparation.', 'Nihon no Rekishi DS provides a deep dive into Japan''s past. From ancient times to the modern era, memorize dates and events through interactive timelines and quizzes designed to help students ace their history exams.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gakkou-no-kaidan-ds-japan', 'NDS', 'Gakkou no Kaidan DS (Japan)', '2007', 'Adventure', 'Banpresto', '1', 'Horror', 'Adventure and horror.', 'Survive supernatural encounters in a haunted school.', 'A spooky adventure game based on Japanese urban legends.', 'Gakkou no Kaidan DS brings school ghost stories to life. Explore haunted corridors, solve supernatural mysteries, and escape terrifying spirits in this atmospheric adventure game designed for fans of J-horror.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gakkou-no-kowai-uwasa---hanako-san-ga-kita!!---minna-no-hanako-san-japan', 'NDS', 'Gakkou no Kowai Uwasa - Hanako-san ga Kita!! - Minna no Hanako-san (Japan)', '2008', 'Adventure', 'Banpresto', '1', 'Horror', 'Adventure and horror.', 'Solve mysteries with the legendary ghost Hanako-san.', 'A kid-friendly horror adventure based on the urban legend.', 'Hanako-san ga Kita!! on NDS lets you investigate "scary rumors" in schools. Solve puzzles and complete mini-games with Hanako-san to protect students from spooky spirits in this interactive adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gakuen-alice---waku-waku-happy-friends-japan', 'NDS', 'Gakuen Alice - Waku Waku Happy Friends (Japan)', '2006', 'Adventure', 'Marvelous', '1', 'Anime', 'Adventure and mini-games.', 'Interact with friends and complete tasks at Alice Academy.', 'A social adventure game based on the Gakuen Alice series.', 'Gakuen Alice: Waku Waku Happy Friends brings the popular manga to NDS. Explore the academy, use special "Alice" powers, and build friendships with Mikan and her classmates through fun mini-games and story events.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('galactic-taz-ball-europe-enfrdeesitnl', 'NDS', 'Galactic Taz Ball (Europe) (En,Fr,De,Es,It,Nl)', '2009', 'Action', 'Sierra', '1', 'Arcade', 'Puzzle and action.', 'Guide Taz through 3D spheres to save the galaxy.', 'A unique gravity-based action game featuring Taz.', 'Galactic Taz Ball on NDS puts the Tasmanian Devil in a space-faring adventure. Rotate world-spheres using the stylus to navigate Taz through traps and enemies in this fast-paced, 3D platforming puzzle game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('galactic-taz-ball-usa-enfrespt', 'NDS', 'Galactic Taz Ball (USA) (En,Fr,Es,Pt)', '2009', 'Action', 'Sierra', '1', 'Arcade', 'Puzzle and action.', 'Guide Taz through 3D spheres to save the galaxy.', 'A unique gravity-based action game featuring Taz.', 'Galactic Taz Ball on NDS puts the Tasmanian Devil in a space-faring adventure. Rotate world-spheres using the stylus to navigate Taz through traps and enemies in this fast-paced, 3D platforming puzzle game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('galactik-football-europe-enfrdeesit', 'NDS', 'Galactik Football (Europe) (En,Fr,De,Es,It)', '2008', 'Sports', 'Namco', '1', 'Anime', 'Sports simulation and football.', 'Master the "Breath" energy to win futuristic soccer matches.', 'An arcade soccer game based on the sci-fi anime series.', 'Galactik Football on NDS brings the high-stakes cosmic tournament to your handheld. Use special team abilities and fast-paced tactics to win matches across the galaxy and become the ultimate champions of the Flux.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('galaxy-racers-europe-enfrdeesit', 'NDS', 'Galaxy Racers (Europe) (En,Fr,De,Es,It)', '2009', 'Racing', 'Ubisoft', '1', 'Arcade', 'Racing and strategy.', 'Win intergalactic races and manage your racing team.', 'A sci-fi racing game with a focus on team management.', 'Galaxy Racers for NDS combines high-speed space racing with tactical planning. Upgrade your ship, choose your pilots, and compete on exotic planet tracks to dominate the galactic racing circuit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('galaxy-racers-usa-enfrdeesit', 'NDS', 'Galaxy Racers (USA) (En,Fr,De,Es,It)', '2009', 'Racing', 'Ubisoft', '1', 'Arcade', 'Racing and strategy.', 'Win intergalactic races and manage your racing team.', 'A sci-fi racing game with a focus on team management.', 'Galaxy Racers for NDS combines high-speed space racing with tactical planning. Upgrade your ship, choose your pilots, and compete on exotic planet tracks to dominate the galactic racing circuit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('galileo-japan', 'NDS', 'Galileo (Japan)', '2006', 'Adventure', 'Nintendo', '1', 'Mystery', 'Mystery and deduction.', 'Solve complex scientific mysteries alongside Professor Galileo.', 'A detective adventure based on the popular Japanese TV show.', 'Galileo on NDS tasks you with using science and logic to crack difficult cases. Solve intricate puzzles and analyze evidence to find the truth behind seemingly impossible crimes in this cerebral adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('galileo-mystery---die-krone-des-midas-germany', 'NDS', 'Galileo Mystery - Die Krone des Midas (Germany)', '2009', 'Adventure', 'Adventure Company', '1', 'Mystery', 'Hidden object and puzzle adventure.', 'Find the crown of Midas and solve ancient mysteries.', 'A mystery-adventure game based on the Galileo German TV show.', 'Galileo Mystery: Die Krone des Midas for NDS takes you on a global treasure hunt. Search for hidden objects, solve historical riddles, and uncover the truth behind the legend of King Midas in this engaging German puzzle game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('game-center-cx---arino-no-chousenjou-japan', 'NDS', 'Game Center CX - Arino no Chousenjou (Japan)', '2007', 'Compilation', 'Namco', '1', 'Retro', 'Retro mini-games and challenges.', 'Complete challenges to defeat Arino in retro-style games.', 'A collection of original "8-bit" games for the NDS.', 'Game Center CX (Retro Game Challenge) is a love letter to the NES era. Play through a variety of custom-made retro games—from shooters to RPGs—while completing specific challenges set by the digital version of Arino-kachou.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('game-center-cx---arino-no-chousenjou-2-japan', 'NDS', 'Game Center CX - Arino no Chousenjou 2 (Japan)', '2009', 'Compilation', 'Namco', '1', 'Retro', 'Retro mini-games and challenges.', 'Complete even more challenges in new retro-style titles.', 'The sequel to the hit retro gaming challenge.', 'Game Center CX 2 on NDS expands the retro library with more genres, including puzzle and adventure games. Dive back into the 8-bit nostalgia and prove your gaming skills against Arino''s latest set of challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('game-de-demashita!-powerpuff-girls-z-japan', 'NDS', 'Game de Demashita! Powerpuff Girls Z (Japan)', '2006', 'Action', 'Bandai', '1', 'Anime', 'Action and mini-games.', 'Use superpowers to protect the city from villains.', 'An action-packed game based on the anime version of PPG.', 'Powerpuff Girls Z for NDS brings Blossom, Bubbles, and Buttercup to the dual screen. Fight classic villains through a series of interactive mini-games and action segments that capture the energy of the anime series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('game-hits-europe-enfrdeesitnl', 'NDS', 'Game Hits (Europe) (En,Fr,De,Es,It,Nl)', '2008', 'Compilation', '505 Games', '1', 'Variety', 'Classic puzzle and arcade collection.', 'Master a variety of popular parlor and logic games.', 'A 10-in-1 collection of casual and classic board games.', 'Game Hits for NDS provides a library of favorites like Solitaire, Mahjong, and various puzzles. It’s the perfect all-in-one cartridge for casual gamers looking for quick and relaxing challenges on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gamebook-ds---aquarian-age---perpetual-period-japan', 'NDS', 'Gamebook DS - Aquarian Age - Perpetual Period (Japan)', '2007', 'RPG', 'Broccoli', '1', 'VisualNovel', 'Interactive digital gamebook.', 'Make choices to navigate a fantasy story with card battles.', 'A digital gamebook featuring the Aquarian Age universe.', 'Aquarian Age: Perpetual Period on NDS combines a branching narrative with strategic card combat. Your choices determine the flow of the story in this beautifully illustrated interactive fantasy world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gamebook-ds---koukaku-no-regios-japan', 'NDS', 'Gamebook DS - Koukaku no Regios (Japan)', '2009', 'RPG', 'Kadokawa', '1', 'VisualNovel', 'Interactive digital gamebook.', 'Survive the post-apocalyptic world through strategic choices.', 'A digital gamebook based on the Chrome Shelled Regios series.', 'Gamebook DS: Koukaku no Regios brings the light novel series to life. Navigate a dangerous world of mobile cities and monsters, making critical decisions that lead to multiple endings in this interactive narrative experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gamebook-ds---sword-world-20-japan', 'NDS', 'Gamebook DS - Sword World 2.0 (Japan)', '2009', 'RPG', 'Group SNE', '1', 'Tabletop', 'Interactive digital gamebook.', 'Explore a high-fantasy world based on the RPG rules.', 'A digital adventure based on the Sword World 2.0 system.', 'Sword World 2.0 on NDS offers a tabletop-style experience. Roll dice, manage your character''s stats, and explore a rich fantasy narrative where your decisions and luck determine your success as an adventurer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('games-around-the-world-usa-enfr', 'NDS', 'Games Around the World (USA) (En,Fr)', '2008', 'Education', 'Tivola', '1', 'Culture', 'Cultural mini-game collection.', 'Play and learn about traditional games from different nations.', 'A globetrotting collection of traditional world games.', 'Games Around the World for NDS introduces you to classic games like Mancala and Mahjong. Travel the world digitally and learn the rules and history of diverse cultural games through fun, interactive play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ganbare-goemon---tokaidouchuu-ooedo-tengurigaeshi-no-maki-japan', 'NDS', 'Ganbare Goemon - TokaiDouchuu Ooedo Tengurigaeshi no Maki (Japan)', '2005', 'Action', 'Konami', '1', 'ActionAdventure', 'Side-scrolling adventure.', 'Help Goemon and Ebisumaru save Edo Japan.', 'A classic Konami action-adventure with a retro vibe.', 'Ganbare Goemon on NDS brings back the legendary mystical ninja. Explore vibrant 2D environments, battle wacky enemies, and pilot the giant robot Goemon Impact in this humorous and action-packed journey through Feudal Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ganbaru-watashi-no-kakei-diary-japan', 'NDS', 'Ganbaru Watashi no Kakei Diary (Japan)', '2008', 'Simulation', 'Sony', '1', 'LifeSim', 'Financial management and diary.', 'Track your daily expenses and manage your savings.', 'A helpful household budget organizer for NDS.', 'Ganbaru Watashi no Kakei Diary makes money management simple. Use the stylus to log spending, set financial goals, and view easy-to-read charts of your household''s economic health on your handheld console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ganbaru-watashi-no-kakei-diary-japan-rev-1', 'NDS', 'Ganbaru Watashi no Kakei Diary (Japan) (Rev 1)', '2008', 'Simulation', 'Sony', '1', 'LifeSim', 'Financial management and diary.', 'Track your daily expenses and manage your savings.', 'A helpful household budget organizer for NDS.', 'Ganbaru Watashi no Kakei Diary makes money management simple. Use the stylus to log spending, set financial goals, and view easy-to-read charts of your household''s economic health on your handheld console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gang-del-bosco-la-italy', 'NDS', 'Gang del Bosco, La (Italy)', '2006', 'Adventure', 'Artematica', '1', 'StoryDriven', 'Stealth and platforming.', 'Help RJ and the gang steal food from the suburbs.', 'An action-adventure based on the movie Over the Hedge.', 'La Gang del Bosco on NDS features stealth-based gameplay where you control RJ, Verne, and Hammy. Navigate suburban backyards, dodge traps, and outsmart the Exterminator to gather food for the winter in this fun movie adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gardening-guide---how-to-get-green-fingers-europe-enfrde', 'NDS', 'Gardening Guide - How to Get Green Fingers (Europe) (En,Fr,De)', '2008', 'Education', '505 Games', '1', 'Reference', 'Educational and lifestyle.', 'Learn gardening techniques and plan your own garden.', 'An interactive guide to plants, flowers, and landscaping.', 'Gardening Guide on NDS is a digital companion for plant lovers. It offers a huge database of plants, seasonal care tips, and a layout tool to design your dream garden while teaching you how to maintain healthy "green fingers."');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gardening-mama-europe-enfrdeesit', 'NDS', 'Gardening Mama (Europe) (En,Fr,De,Es,It)', '2009', 'Simulation', 'Office Create', '1', 'Casual', 'Simulation and mini-games.', 'Grow various plants and flowers through touch-screen tasks.', 'A charming gardening spin-off of the Cooking Mama series.', 'Gardening Mama brings the famous Mama outdoors on NDS. Use the stylus to dig, plant, water, and harvest. Cultivate everything from strawberries to sunflowers while decorating your garden in this colorful and addictive simulation.');
