INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('garfield---a-tail-of-two-kitties-usa-enfres', 'NDS', 'Garfield - A Tail of Two Kitties (USA) (En,Fr,Es)', '2006', 'Platformer', 'Eko Software', '1', 'Cartoon', 'Platforming and action.', 'Help Garfield travel to England and trade places with Prince.', 'An adventure based on the second Garfield movie.', 'Garfield: A Tail of Two Kitties on NDS takes the lazy cat to London. Play as both Garfield and his royal lookalike, Prince, to navigate puzzles and platforming levels across the city and the castle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('garfield-2-europe-enfrdeesitnlptsvnodafi', 'NDS', 'Garfield 2 (Europe) (En,Fr,De,Es,It,Nl,Pt,Sv,No,Da,Fi)', '2006', 'Platformer', 'Eko Software', '1', 'Cartoon', 'Platforming and action.', 'Help Garfield travel to England and trade places with Prince.', 'An adventure based on the second Garfield movie.', 'Garfield 2 brings the cinematic adventure to your NDS. Use each cat''s unique abilities to solve environmental riddles, avoid enemies, and enjoy a story full of humor and lasagna.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('garfield-gets-real-europe-enfrdeesit', 'NDS', 'Garfield Gets Real (Europe) (En,Fr,De,Es,It)', '2007', 'Platformer', 'Eko Software', '1', 'Cartoon', 'Mini-game collection.', 'Help Garfield find his missing humor and save the show.', 'A fun collection of games based on the Garfield CGI film.', 'Garfield Gets Real on NDS features a variety of touch-screen challenges. Join Garfield, Odie, and the crew in a series of circus-themed and backstage mini-games to help the famous cat return to his world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('garfield-gets-real-usa', 'NDS', 'Garfield Gets Real (USA)', '2007', 'Platformer', 'Eko Software', '1', 'Cartoon', 'Mini-game collection.', 'Help Garfield find his missing humor and save the show.', 'A fun collection of games based on the Garfield CGI film.', 'Garfield Gets Real on NDS features a variety of touch-screen challenges. Join Garfield, Odie, and the crew in a series of circus-themed and backstage mini-games to help the famous cat return to his world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('garfields-fun-fest-europe-enfrdeesit', 'NDS', 'Garfield''s Fun Fest (Europe) (En,Fr,De,Es,It)', '2008', 'Platformer', 'Eko Software', '1', 'Cartoon', 'Rhythm and mini-games.', 'Win the talent competition to save the Fun Fest.', 'A competition-based game featuring rhythm and logic tasks.', 'Garfield''s Fun Fest on NDS puts you center stage. Help Garfield prepare for the annual talent show through rhythm-based dance games, cooking challenges, and other fun activities to outshine his rival, Ramone.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('garfields-fun-fest-usa', 'NDS', 'Garfield''s Fun Fest (USA)', '2008', 'Platformer', 'Eko Software', '1', 'Cartoon', 'Rhythm and mini-games.', 'Win the talent competition to save the Fun Fest.', 'A competition-based game featuring rhythm and logic tasks.', 'Garfield''s Fun Fest on NDS puts you center stage. Help Garfield prepare for the annual talent show through rhythm-based dance games, cooking challenges, and other fun activities to outshine his rival, Ramone.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('garfields-nightmare-europe-enfrdeesitnlptsvnodafi', 'NDS', 'Garfield''s Nightmare (Europe) (En,Fr,De,Es,It,Nl,Pt,Sv,No,Da,Fi)', '2007', 'Action', 'Shin’en', '1', 'Cartoon', 'Platforming and puzzle.', 'Wake Garfield up from a world of his own nightmares.', 'A surreal and colorful platformer set in Garfield''s mind.', 'Garfield''s Nightmare on NDS is a classic 2D platformer with a twist. Travel through 16 levels of Garfield''s bad dreams, fighting off spooky creatures and collecting pieces of his broken alarm clock to wake him up.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('garfields-nightmare-usa-enfres', 'NDS', 'Garfield''s Nightmare (USA) (En,Fr,Es)', '2007', 'Action', 'Shin’en', '1', 'Cartoon', 'Platforming and puzzle.', 'Wake Garfield up from a world of his own nightmares.', 'A surreal and colorful platformer set in Garfield''s mind.', 'Garfield''s Nightmare on NDS is a classic 2D platformer with a twist. Travel through 16 levels of Garfield''s bad dreams, fighting off spooky creatures and collecting pieces of his broken alarm clock to wake him up.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gedaechtnis-trainer-germany', 'NDS', 'Gedaechtnis Trainer (Germany)', '2007', 'Education', 'DTP Entertainment', '1', 'Training', 'Brain training.', 'Improve your memory through daily scientific exercises.', 'A German brain trainer focused on memory retention.', 'Gedaechtnis Trainer on NDS offers a specialized program to sharpen your mind. Focus on remembering names, numbers, and faces through a series of increasingly difficult cognitive mini-games designed for daily practice.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gegege-no-kitarou---youkai-daigekisen-japan', 'NDS', 'Gegege no Kitarou - Youkai Daigekisen (Japan)', '2008', 'Action', 'Bandai', '1', 'Anime', 'Side-scrolling action.', 'Fight off evil spirits and save the world of Youkai.', 'A classic action-platformer starring Kitaro.', 'Gegege no Kitarou: Youkai Daigekisen brings the legendary manga to NDS. Use Kitaro’s signature weapons, like his hair needles and clogs, to defeat traditional Japanese folklore monsters in this vibrant action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gekifu-bakegyamon---ayakashi-fighting-japan', 'NDS', 'Gekifu Bakegyamon - Ayakashi Fighting (Japan)', '2009', 'Fighting', 'Starfish', '1', 'Anime', 'Monster battling and RPG.', 'Collect "Monsters" and win the Bakegyamon tournament.', 'A tactical monster-battle game based on the anime series.', 'Gekifu Bakegyamon on NDS focuses on strategic monster duels. Collect unique creatures, master their elemental affinities, and climb the ranks of the tournament in this high-energy Japanese RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gekikara-nanpure-2500-mon-japan', 'NDS', 'Gekikara Nanpure 2500 Mon (Japan)', '2007', 'Puzzle', 'Success', '1', 'Logic', 'Logic puzzle and Sudoku.', 'Solve a massive collection of 2,500 Sudoku puzzles.', 'The ultimate Sudoku library for puzzle enthusiasts.', 'Gekikara Nanpure 2500 Mon offers an incredible amount of content for NDS. From beginner levels to "spicy" challenges, it provides a clean and responsive interface for hours of number-logic fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gekitou!-custom-robo-japan', 'NDS', 'Gekitou! Custom Robo (Japan)', '2006', 'Action', 'Nintendo', '1', 'SciFi', 'Arena brawler and RPG.', 'Customize small robots and win arena battles.', 'A deep and fast-paced robot customization and fighting game.', 'Gekitou! Custom Robo brings the cult-classic series to NDS. Build your Robo from hundreds of parts and engage in intense 3D arena combat, utilizing a variety of weapons and tactical movements.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gendai-daisenryaku-ds---isshoku-sokuhatsu-gunji-balance-houkai-japan', 'NDS', 'Gendai Daisenryaku DS - Isshoku Sokuhatsu, Gunji Balance Houkai (Japan)', '2008', 'Strategy', 'SystemSoft Alpha', '1', 'Strategy', 'Turn-based strategy.', 'Command military forces in modern global conflicts.', 'A deep military simulation focusing on modern warfare.', 'Gendai Daisenryaku DS offers a complex tactical experience. Manage ground, air, and sea units on hexagonal maps to balance world power and win high-stakes military scenarios in this detailed Japanese strategy game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('genio-de-las-palabras-el-spain', 'NDS', 'Genio de las Palabras, El (Spain)', '2008', 'Word', 'Game Factory', '1', 'Education', 'Word puzzle and trivia.', 'Build words and solve linguistic challenges.', 'A Spanish word-based puzzle game for all ages.', 'El Genio de las Palabras on NDS tests your vocabulary and spelling. Through various game modes, you must connect letters to form words and solve puzzles, making it a perfect tool for fun and education in Spanish.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('genmu-no-tou-to-tsurugi-no-okite-japan', 'NDS', 'Genmu no Tou to Tsurugi no Okite (Japan)', '2009', 'RPG', 'Compile Heart', '1', 'Fantasy', 'First-person dungeon crawler.', 'Navigate dangerous labyrinths in a dark fantasy world.', 'A hardcore retro-style RPG inspired by classics.', 'Genmu no Tou to Tsurugi no Okite is a love letter to Wizardry-style games on NDS. Create your party, manage resources, and survive trap-filled corridors in this challenging first-person Japanese RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gensou-suikoden---tierkreis-japan', 'NDS', 'Gensou Suikoden - Tierkreis (Japan)', '2008', 'RPG', 'Konami', '1', 'JRPG', 'Turn-based RPG.', 'Explore the multiverse and recruit characters for your army.', 'A massive RPG experience from the Suikoden series.', 'Suikoden Tierkreis on NDS features a beautiful story about destiny. Recruit 108 Stars of Destiny across different dimensions, engage in strategic party battles, and enjoy high-quality cutscenes in this epic fantasy journey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('geo-wunder-natur-puzzle---echter-puzzlespass-fuer-unterwegs-europe-enfrdeesit', 'NDS', 'GEO Wunder Natur Puzzle - Echter Puzzlespass fuer Unterwegs (Europe) (En,Fr,De,Es,It)', '2008', 'Puzzle', 'Tivola', '1', 'Educational', 'Puzzle and observation.', 'Complete puzzles featuring stunning nature photography.', 'A nature-themed jigsaw puzzle game from GEO magazine.', 'GEO Wunder Natur Puzzle for NDS offers a relaxing puzzle experience. Solve beautiful images of wildlife and landscapes, choosing between different difficulty levels and piece counts in this high-quality visual title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('geojisui-yunmugok-korea', 'NDS', 'Geojisui Yunmugok (Korea)', '2008', 'Puzzle', 'Sonokong', '1', 'Educational', 'Rhythm and mini-games.', 'Perform musical tasks and follow the story beats.', 'A colorful Korean rhythm and adventure game.', 'Geojisui Yunmugok on NDS combines a narrative experience with engaging rhythm-based gameplay. Use the touch screen to keep the beat and progress through a charming story filled with music and characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('geolino-powerquiz---wissen-fuer-kinder-germany', 'NDS', 'GEOlino PowerQuiz - Wissen fuer Kinder (Germany)', '2007', 'Education', 'GEOlino', '1', 'Quiz', 'Educational and trivia.', 'Answer nature and science questions to become an expert.', 'A nature-based quiz game for kids from the GEOlino magazine.', 'GEOlino PowerQuiz on NDS makes learning about the planet fun. Children can test their knowledge on animals, space, and geography through hundreds of questions designed to educate and entertain.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('geometry-wars---galaxies-europe-enfrdeesit', 'NDS', 'Geometry Wars - Galaxies (Europe) (En,Fr,De,Es,It)', '2008', 'Shooter', 'Bizarre Creations', '1', 'Arcade', 'Twin-stick shooter.', 'Destroy waves of geometric enemies and reach high scores.', 'A high-energy, neon-soaked arcade space shooter.', 'Geometry Wars: Galaxies brings the intense arcade action to NDS. Survive endless waves of enemies across dozens of unique solar systems, unlocking new drones and abilities in this visually stunning and fast-paced shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('geometry-wars---galaxies-usa', 'NDS', 'Geometry Wars - Galaxies (USA)', '2007', 'Shooter', 'Bizarre Creations', '1', 'Arcade', 'Twin-stick shooter.', 'Destroy waves of geometric enemies and reach high scores.', 'A high-energy, neon-soaked arcade space shooter.', 'Geometry Wars: Galaxies brings the intense arcade action to NDS. Survive endless waves of enemies across dozens of unique solar systems, unlocking new drones and abilities in this visually stunning and fast-paced shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('george-of-the-jungle-europe-enfrdeesit', 'NDS', 'George of the Jungle (Europe) (En,Fr,De,Es,It)', '2008', 'Platformer', 'Torus Games', '1', 'Cartoon', 'Platforming and action.', 'Swing through the jungle and rescue your animal friends.', 'A fun jungle adventure based on the George of the Jungle cartoon.', 'George of the Jungle on NDS brings classic platforming fun. Swing on vines, run through lush environments, and use George’s strength to overcome obstacles and save the jungle from wacky threats in this family-friendly title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('george-of-the-jungle-and-the-search-for-the-secret-usa', 'NDS', 'George of the Jungle and the Search for the Secret (USA)', '2008', 'Platformer', 'Torus Games', '1', 'Cartoon', 'Platforming and action.', 'Search for a secret artifact to save the jungle.', 'An expanded jungle adventure with new levels and secrets.', 'George of the Jungle and the Search for the Secret features fast-paced platforming. Explore hidden areas, master George''s jungle skills, and enjoy a humorous story as you search for a mysterious treasure on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('germanys-next-topmodel---das-offizielle-spiel-zur-show-germany', 'NDS', 'Germany''s Next Topmodel - Das Offizielle Spiel zur Show (Germany)', '2009', 'Simulation', 'DTP Entertainment', '1', 'Casual', 'Fashion and lifestyle simulation.', 'Complete modeling challenges to become Germany''s next top model.', 'The official game based on the hit German reality TV show.', 'Germany''s Next Topmodel lets you experience the life of a rising star. Practice your runway walk, choose the perfect outfits for photoshoots, and impress the judges to climb the ranks in this glamorous simulation for NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('germanys-next-topmodel---das-offizielle-spiel-zur-staffel-2009-germany', 'NDS', 'Germany''s Next Topmodel - Das Offizielle Spiel zur Staffel 2009 (Germany)', '2009', 'Simulation', 'DTP Entertainment', '1', 'Casual', 'Fashion and lifestyle simulation.', 'Win the 2009 season through style and personality.', 'The official NDS game for the 2009 season of the TV show.', 'Germany''s Next Topmodel 2009 offers updated fashion trends and challenges. Manage your model''s daily routine, participate in high-stakes castings, and prove you have what it takes to be the face of the year.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('germanys-next-topmodel---das-offizielle-spiel-zur-staffel-2010-germany-ndsi-enhanced', 'NDS', 'Germany''s Next Topmodel - Das Offizielle Spiel zur Staffel 2010 (Germany) (NDSi Enhanced)', '2010', 'Simulation', 'DTP Entertainment', '1', 'Casual', 'Fashion and lifestyle simulation.', 'Master the 2010 season with enhanced DSi features.', 'The official 2010 season game with NDSi camera support.', 'Germany''s Next Topmodel 2010 utilizes DSi features for a personalized experience. Create your model, take photos to customize your style, and compete in the most realistic modeling simulation of the series yet.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gesundheits-coach-der---wohlfuehlen-jeden-tag-germany', 'NDS', 'Gesundheits Coach, Der - Wohlfuehlen Jeden Tag (Germany)', '2009', 'Education', 'DTP Entertainment', '1', 'Wellness', 'Health and wellness coaching.', 'Follow daily exercises and nutrition tips to feel better.', 'A German wellness coach for everyday healthy living.', 'Der Gesundheits Coach on NDS provides a personal plan for well-being. Track your activity, learn about balanced nutrition, and follow simple daily routines designed to improve your physical and mental health.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('geurigo-malhago-sijakaja!---monster-farm-ds-korea', 'NDS', 'Geurigo, Malhago, Sijakaja! - Monster Farm DS (Korea)', '2008', 'Simulation', 'Marvelous', '1', 'Casual', 'Monster breeding and battling.', 'Raise powerful monsters and win world tournaments.', 'The Korean edition of the popular Monster Rancher series.', 'Monster Farm DS (Korea) lets you create monsters using the touch screen. Train your creatures, manage their diet and stress, and enter intense battles to prove you are the best monster rancher in the land.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('geuryeora-touch!---naega-mandeuneun-sesang-korea', 'NDS', 'Geuryeora, Touch! - Naega Mandeuneun Sesang (Korea)', '2007', 'Simulation', 'Joymax', '1', 'Casual', 'Creative drawing and adventure.', 'Draw your own hero and tools to save the world.', 'A Korean version of the creative "Drawn to Life" game.', 'Geuryeora, Touch! (Drawn to Life) allows you to use the stylus to design everything. From your protagonist to the platforms you walk on, your creativity is the key to restoring light to a dying world on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('geuryeora-touch!---spongebob-nemobaji-korea', 'NDS', 'Geuryeora, Touch! - SpongeBob Nemobaji (Korea)', '2007', 'Platformer', 'THQ', '1', 'Cartoon', 'Creative drawing and adventure.', 'Help SpongeBob by drawing items and heroes.', 'A SpongeBob-themed creative adventure game.', 'Geuryeora, Touch! SpongeBob brings the Bikini Bottom cast to NDS. Draw your own sea-themed hero and use the touch screen to create objects that help SpongeBob and Patrick through their underwater journey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ghost-trick---phantom-detective-europe-enfrdeesit', 'NDS', 'Ghost Trick - Phantom Detective (Europe) (En,Fr,De,Es,It)', '2011', 'Adventure', 'Capcom', '1', 'Mystery', 'Puzzle and supernatural mystery.', 'Solve your own murder by manipulating objects as a ghost.', 'A brilliant mystery-puzzle game from the creator of Ace Attorney.', 'Ghost Trick: Phantom Detective is a masterpiece on NDS. Play as Sissel, a ghost who can "possess" and "trick" objects to alter fate. Solve complex Rube Goldberg-style puzzles to uncover the truth behind your death before sunrise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ghost-trick---phantom-detective-usa-enfrdeesit', 'NDS', 'Ghost Trick - Phantom Detective (USA) (En,Fr,De,Es,It)', '2011', 'Adventure', 'Capcom', '1', 'Mystery', 'Puzzle and supernatural mystery.', 'Solve your own murder by manipulating objects as a ghost.', 'A brilliant mystery-puzzle game from the creator of Ace Attorney.', 'Ghost Trick: Phantom Detective is a masterpiece on NDS. Play as Sissel, a ghost who can "possess" and "trick" objects to alter fate. Solve complex Rube Goldberg-style puzzles to uncover the truth behind your death before sunrise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ghost-trick-japan', 'NDS', 'Ghost Trick (Japan)', '2010', 'Adventure', 'Capcom', '1', 'Mystery', 'Puzzle and supernatural mystery.', 'Solve your own murder by manipulating objects as a ghost.', 'A brilliant mystery-puzzle game from the creator of Ace Attorney.', 'Ghost Trick: Phantom Detective is a masterpiece on NDS. Play as Sissel, a ghost who can "possess" and "trick" objects to alter fate. Solve complex Rube Goldberg-style puzzles to uncover the truth behind your death before sunrise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ghostbusters---the-video-game-europe-enfrdeesitnl', 'NDS', 'Ghostbusters - The Video Game (Europe) (En,Fr,De,Es,It,Nl)', '2009', 'Action', 'Terminal Reality', '1', 'Cinematic', 'Action adventure and ghost hunting.', 'Trap ghosts and save the city from a paranormal outbreak.', 'A stylized action game based on the Ghostbusters franchise.', 'Ghostbusters: The Video Game on NDS puts you in the role of a new recruit. Use your Proton Pack to weaken ghosts and throw traps with the stylus in this engaging adventure featuring the original movie cast''s likenesses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ghostbusters---the-video-game-usa-enfres', 'NDS', 'Ghostbusters - The Video Game (USA) (En,Fr,Es)', '2009', 'Action', 'Terminal Reality', '1', 'Cinematic', 'Action adventure and ghost hunting.', 'Trap ghosts and save the city from a paranormal outbreak.', 'A stylized action game based on the Ghostbusters franchise.', 'Ghostbusters: The Video Game on NDS puts you in the role of a new recruit. Use the touch screen to manage your equipment and trap iconic spirits across haunted locations in this portable supernatural adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('giana-sisters-ds-europe-enfrdeesit', 'NDS', 'Giana Sisters DS (Europe) (En,Fr,De,Es,It)', '2009', 'Platformer', 'Spellbound', '1', 'Retro', '2D Platforming.', 'Rescue the sisters and defeat enemies in a classic world.', 'A modern revival of the legendary 8-bit platformer.', 'Giana Sisters DS brings the cult-classic series to the modern era. Explore over 80 levels, use unique power-ups like the "Punk" girl, and enjoy polished graphics and tight controls in this challenging and nostalgic platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gijeogui-100-kan-gyesanbeop-korea', 'NDS', 'Gijeogui 100-kan Gyesanbeop (Korea)', '2007', 'Education', 'Digital Bros', '1', 'Training', 'Educational and math drills.', 'Solve 100-cell math grids to improve calculation speed.', 'A Korean math trainer based on the 100-cell method.', 'Gijeogui 100-kan Gyesanbeop is a specialized educational tool for NDS. Master addition, subtraction, and multiplication through daily timed challenges designed to sharpen mental math skills for students.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gilde-ds-die-europe-enfrde', 'NDS', 'Gilde DS, Die (Europe) (En,Fr,De)', '2008', 'Strategy', 'Haemimont Games', '1', 'Economic', 'Strategy and life simulation.', 'Build a business dynasty in a medieval city.', 'A deep economic and social simulation set in the Middle Ages.', 'Die Gilde DS (The Guild) lets you choose a profession and build your family''s influence. Manage businesses, engage in politics, and ensure your lineage prospers in this complex and atmospheric medieval strategy game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gina-lisa-powershopping-germany', 'NDS', 'Gina-Lisa Powershopping (Germany)', '2010', 'Simulation', 'Bitfield', '1', 'Casual', 'Shopping simulation and mini-games.', 'Go on a shopping spree and master fashion challenges.', 'A German lifestyle game featuring celebrity Gina-Lisa Lohfink.', 'Gina-Lisa Powershopping on NDS is all about the "glam" life. Navigate the city''s boutiques, manage your budget, and complete fashion mini-games to stay on trend with the help of Germany''s famous TV personality.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ginga-tetsudou-999-ds-japan', 'NDS', 'Ginga Tetsudou 999 DS (Japan)', '2009', 'Adventure', 'Nippon Animation', '1', 'Anime', 'Interactive adventure and RPG.', 'Travel through space on the legendary train 999.', 'A nostalgic journey based on the classic Leiji Matsumoto anime.', 'Ginga Tetsudou 999 DS allows you to experience the epic space opera. Join Tetsuro and Maetel on their journey to the Andromeda Galaxy, featuring beautiful artwork and a deep narrative that honors the original series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gintama---gintama-quest---gin-san-ga-tenshoku-shitari-sekai-o-sukuttari-japan', 'NDS', 'Gintama - Gintama Quest - Gin-san ga Tenshoku shitari Sekai o Sukuttari (Japan)', '2009', 'RPG', 'Banpresto', '1', 'Anime', 'RPG and humor.', 'Complete wacky quests and save the Kabukicho district.', 'A hilarious RPG based on the irreverent Gintama anime.', 'Gintama Quest for NDS features the Yorozuya gang in a parody-filled adventure. Engage in turn-based battles, complete absurd jobs for residents, and enjoy the series'' signature meta-humor and fourth-wall breaking.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gintama---gintoki-vs-hijikata!---kabukichou-gintama-daisoudatsusen!!-japan', 'NDS', 'Gintama - Gintoki vs Hijikata! - Kabukichou Gintama Daisoudatsusen!! (Japan)', '2008', 'Action', 'Banpresto', '1', 'Anime', 'Card battle and action.', 'Fight rivals and collect cards to dominate the neighborhood.', 'A strategic card-battle game featuring the Gintama cast.', 'Gintoki vs Hijikata! focuses on the rivalry between the Yorozuya and the Shinsengumi. Use character cards to perform special attacks and win strategic duels in this high-energy Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gintama-ds---yorozuya-daisoudou-japan', 'NDS', 'Gintama DS - Yorozuya Daisoudou (Japan)', '2006', 'Action', 'Banpresto', '1', 'Anime', 'Mini-game collection.', 'Solve the Yorozuya''s problems through various challenges.', 'A fun and chaotic collection of mini-games starring Gintoki.', 'Gintama DS: Yorozuya Daisoudou offers dozens of wacky touch-screen challenges. From catching runaway pets to absurd combat scenarios, this game captures the pure chaos and comedy of the Gintama universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('girl-time---everything-you-need-for-a-hip-happening-life!-usa', 'NDS', 'Girl Time - Everything You Need for a Hip, Happening Life! (USA)', '2009', 'Simulation', 'Destineer', '1', 'Casual', 'Lifestyle simulation and organizer.', 'Manage your social life, style, and daily schedule.', 'An all-in-one lifestyle app and game for girls.', 'Girl Time on NDS is the ultimate digital companion. Use the calendar to track events, play fashion mini-games, and use the "Friend Finder" to stay organized while expressing your unique personality through custom avatars.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('girls-life---fashion-addict-europe-enfrdeesitnl-ndsi-enhanced', 'NDS', 'Girls Life - Fashion Addict (Europe) (En,Fr,De,Es,It,Nl) (NDSi Enhanced)', '2010', 'Simulation', 'Eidos', '1', 'Fashion', 'Fashion simulation.', 'Design outfits and build your career in the fashion world.', 'A deep fashion design sim with DSi camera features.', 'Girls Life: Fashion Addict lets you run your own boutique on NDS. Choose fabrics, cut patterns, and style your models for the runway. Use the DSi camera to find color inspiration from the real world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('girls-life---jewellery-style-europe-enfrdeesitnl-ndsi-enhanced', 'NDS', 'Girls Life - Jewellery Style (Europe) (En,Fr,De,Es,It,Nl) (NDSi Enhanced)', '2010', 'Simulation', 'Eidos', '1', 'Fashion', 'Jewelry design simulation.', 'Create stunning jewelry and manage your own store.', 'A creative design game focused on accessories and gems.', 'Girls Life: Jewellery Style allows you to craft unique rings, necklaces, and bracelets. Use the stylus as your jeweler''s tool, choose from hundreds of gemstones, and build a successful brand in this detailed creative sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('girls-life---makeover-europe-enfrdeesitnl-ndsi-enhanced', 'NDS', 'Girls Life - Makeover (Europe) (En,Fr,De,Es,It,Nl) (NDSi Enhanced)', '2010', 'Simulation', 'Eidos', '1', 'Fashion', 'Beauty and makeup simulation.', 'Apply makeup and style hair for various clients.', 'A comprehensive makeover and beauty salon simulator.', 'Girls Life: Makeover turns your NDS into a beauty parlor. Use the touch screen to apply lipstick, eyeshadow, and style hair. Meet your clients'' specific requests to earn rewards and unlock new beauty products.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('girls-only-europe-enfrdeesitnl', 'NDS', 'Girls Only (Europe) (En,Fr,De,Es,It,Nl)', '2009', 'Simulation', 'Micro Application', '1', 'Casual', 'Mini-game collection and lifestyle.', 'Play a variety of games designed for girls'' interests.', 'A fun and diverse collection of games for young girls.', 'Girls Only on NDS features a mix of fashion, cooking, and puzzle mini-games. It’s a perfect title for casual play, offering a safe and creative environment to explore different hobbies and styles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('glory-days---yuugeki-no-hero-japan', 'NDS', 'Glory Days - Yuugeki no Hero (Japan)', '2006', 'Action', 'Odenis Studio', '1', 'Military', 'Action and flight simulation.', 'Pilot a plane and lead your troops to victory.', 'A fast-paced tactical flight-action game.', 'Glory Days: Yuugeki no Hero (Glory Days 2) is a unique blend of dogfighting and strategy. Command your army while flying a fighter jet or helicopter, using the dual screens to oversee the battlefield and crush the enemy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('glory-days-2-europe-enfrdeesit', 'NDS', 'Glory Days 2 (Europe) (En,Fr,De,Es,It)', '2008', 'Action', 'Odenis Studio', '1', 'Military', 'Action and flight simulation.', 'Pilot a plane and lead your troops to victory.', 'A fast-paced tactical flight-action game.', 'Glory Days 2 on NDS combines side-scrolling action with real-time strategy. Control powerful aircraft, drop paratroopers, and destroy enemy bases in a series of intense, high-stakes military campaigns.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('glory-days-2-usa-enfres', 'NDS', 'Glory Days 2 (USA) (En,Fr,Es)', '2008', 'Action', 'Odenis Studio', '1', 'Military', 'Action and flight simulation.', 'Pilot a plane and lead your troops to victory.', 'A fast-paced tactical flight-action game.', 'Glory Days 2 on NDS combines side-scrolling action with real-time strategy. Control powerful aircraft, drop paratroopers, and destroy enemy bases in a series of intense, high-stakes military campaigns.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('glory-of-heracles-usa', 'NDS', 'Glory of Heracles (USA)', '2010', 'RPG', 'Data East', '1', 'Fantasy', 'Turn-based RPG.', 'Guide an immortal hero through a world of Greek myths.', 'An epic RPG based on Greek mythology and a classic series.', 'Glory of Heracles on NDS features a deep story and a unique battle system. Customize your skills with ether and embark on a grand quest alongside legendary figures in this beautifully crafted fantasy adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('go-west!---a-lucky-luke-adventure-europe-enfrdeesitnl', 'NDS', 'Go West! - A Lucky Luke Adventure (Europe) (En,Fr,De,Es,It,Nl)', '2007', 'Adventure', 'Infogrames', '1', 'Cartoon', 'Platforming and adventure.', 'Help Lucky Luke escort the Daltons to New York for trial.', 'A Wild West adventure based on the animated film.', 'Go West! A Lucky Luke Adventure on NDS brings the famous cowboy to the dual screen. Navigate obstacles, engage in target shooting, and experience a humorous journey through the frontier to capture the Dalton brothers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('go-diego-go!---great-dinosaur-rescue-europe-enfrnl', 'NDS', 'Go, Diego, Go! - Great Dinosaur Rescue (Europe) (En,Fr,Nl)', '2008', 'Adventure', 'Amaze Entertainment', '1', 'Educational', 'Educational and adventure.', 'Rescue baby dinosaurs and return them to their families.', 'A prehistoric rescue mission for young explorers.', 'Go, Diego, Go! Great Dinosaur Rescue for NDS teaches children about dinosaurs while they help Diego. Use the stylus and microphone to solve puzzles, climb mountains, and save various species in this interactive educational quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('go-diego-go!---great-dinosaur-rescue-usa', 'NDS', 'Go, Diego, Go! - Great Dinosaur Rescue (USA)', '2008', 'Adventure', 'Amaze Entertainment', '1', 'Educational', 'Educational and adventure.', 'Rescue baby dinosaurs and return them to their families.', 'A prehistoric rescue mission for young explorers.', 'Go, Diego, Go! Great Dinosaur Rescue for NDS teaches children about dinosaurs while they help Diego. Use the stylus and microphone to solve puzzles, climb mountains, and save various species in this interactive educational quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('go-diego-go!---safari-rescue-europe', 'NDS', 'Go, Diego, Go! - Safari Rescue (Europe)', '2009', 'Adventure', 'Amaze Entertainment', '1', 'Educational', 'Educational and adventure.', 'Save the animals of the Safari and stop the Mean Magician.', 'A wild animal rescue adventure set in Africa.', 'Go, Diego, Go! Safari Rescue on NDS lets kids explore the savanna. Use high-tech gadgets, track animal footprints, and help Diego save the elephants and giraffes through fun, educational mini-games.');
