INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('go!-go!-cosmo-cops!-europe-enfrdeesit', 'NDS', 'Go! Go! Cosmo Cops! (Europe) (En,Fr,De,Es,It)', '2009', 'Action', 'Namco', '1', 'Arcade', 'Platforming and action.', 'Climb skyscrapers and defeat aliens using grappling skills.', 'A unique vertical platformer with physics-based movement.', 'Go! Go! Cosmo Cops! on NDS features an innovative control scheme. Use your character’s wire to swing and propel yourself upward, battling space invaders in a colorful and fast-paced vertical adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('godzilla-unleashed---double-smash-usa', 'NDS', 'Godzilla Unleashed - Double Smash (USA)', '2007', 'Fighting', 'Pipeworks', '4', 'Kaiju', 'Side-scrolling action and flight.', 'Control Godzilla and defeat rival Kaijus on two screens.', 'A dual-screen monster brawler featuring the King of Monsters.', 'Godzilla Unleashed: Double Smash for NDS utilizes the top and bottom screens simultaneously. Battle flying enemies and ground monsters at the same time, using Godzilla''s iconic atomic breath to dominate the city.');
