INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gokujou!!-mecha-mote-iinchou---girls-mote-kawa-box-japan', 'NDS', 'Gokujou!! Mecha Mote Iinchou - Girls ''Mote Kawa'' Box (Japan)', '2009', 'Simulation', 'Konami', '1', 'Anime', 'Fashion and lifestyle.', 'Help Mimi become the most popular and stylish student.', 'A girl-centric lifestyle game based on the anime.', 'Mecha Mote Iinchou: Girls ''Mote Kawa'' Box on NDS offers fashion challenges and makeup tips. Learn how to be the perfect student leader while mastering style and personality in this Japanese sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gokujou!!-mecha-mote-iinchou---mecha-mote-days-hajimemasuwa!-japan', 'NDS', 'Gokujou!! Mecha Mote Iinchou - Mecha Mote Days, Hajimemasuwa! (Japan)', '2008', 'Simulation', 'Konami', '1', 'Anime', 'Fashion and lifestyle.', 'Manage your daily life as a stylish class president.', 'A day-to-day life simulation featuring Mimi.', 'Mecha Mote Iinchou: Mecha Mote Days on NDS lets you experience the busy life of Mimi. Balance school responsibilities, friendship, and fashion through various mini-games and social interactions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gokujou!!-mecha-mote-iinchou---mm-town-de-miracle-change!-japan', 'NDS', 'Gokujou!! Mecha Mote Iinchou - MM Town de Miracle Change! (Japan)', '2009', 'Simulation', 'Konami', '1', 'Anime', 'Life simulation and city builder.', 'Build your dream town and interact with anime characters.', 'A town-building and social sim based on the series.', 'MM Town de Miracle Change! for NDS allows you to customize your own city. Interact with characters from Mecha Mote Iinchou, decorate buildings, and unlock new outfits in this creative social experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('golden-balls-europe', 'NDS', 'Golden Balls (Europe)', '2008', 'GameShow', 'Endemol', '1', 'TV', 'Trivia and game show.', 'Win the most money while avoiding the "Killer" balls.', 'The official game of the British TV game show.', 'Golden Balls on NDS replicates the tension of the show. Test your luck and strategy in "Split or Steal" to see if you can walk away with the jackpot or leave empty-handed in this psychological trivia game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('golden-compass-the---the-official-videogame-europe-enfrdeesit', 'NDS', 'Golden Compass, The - The Official Videogame (Europe) (En,Fr,De,Es,It)', '2007', 'Adventure', 'Shiny Entertainment', '1', 'Cinematic', 'Action-adventure and puzzle.', 'Lead Lyra and her daemon to the far north to save her friend.', 'An epic adventure based on the movie and book.', 'The Golden Compass for NDS takes you to a steampunk fantasy world. Switch between Lyra and the polar bear Iorek to solve puzzles, engage in combat, and use the alethiometer to discover the truth.');
