INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('golden-nugget-casino-ds-europe-enfrde', 'NDS', 'Golden Nugget Casino DS (Europe) (En,Fr,De)', '2008', 'Casino', 'Oxygen Studios', '1', 'Gambling', 'Casino simulation.', 'Play various casino games and build your virtual fortune.', 'A collection of classic casino floor games.', 'Golden Nugget Casino DS offers Blackjack, Roulette, Craps, and Slots on the go. Manage your bankroll and experience the sights and sounds of a Las Vegas casino in this portable gambling simulation.');
