INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('goldeneye---au-service-du-mal-france', 'NDS', 'GoldenEye - Au Service du Mal (France)', '2005', 'Action', 'EA', '1', 'Shooter', 'First-person shooter (FPS).', 'Become a villain and take over the criminal underworld.', 'A dark spin on the Bond universe where you play the rogue.', 'GoldenEye: Rogue Agent on NDS lets you experience the dark side. Use your cybernetic eye to manipulate the environment and outgun enemies in intense FPS combat featuring classic Bond villains.');
