INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('golgo-13---file-g13-o-oe-japan', 'NDS', 'Golgo 13 - File G13 o Oe (Japan)', '2008', 'Action', 'Media.Vision', '1', 'Anime', 'Visual novel and mystery.', 'Track down the legendary assassin Duke Togo.', 'A thriller adventure based on the classic Golgo 13 manga.', 'Golgo 13: File G13 for NDS puts you in the middle of a high-stakes investigation. Uncover global conspiracies and follow the trail of the world''s most dangerous sniper in this suspenseful Japanese narrative.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('goosebumps-horrorland-europe', 'NDS', 'Goosebumps HorrorLand (Europe)', '2008', 'Adventure', 'Altron', '1', 'Horror', 'Mini-game collection and horror.', 'Survive the attractions of the creepy HorrorLand park.', 'A spooky mini-game collection based on R.L. Stine''s books.', 'Goosebumps HorrorLand on NDS takes you to a theme park where the scares are real. Win tickets in creepy carnival games, avoid monsters, and uncover the park''s dark secrets in this kid-friendly horror title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('goosebumps-horrorland-usa', 'NDS', 'Goosebumps HorrorLand (USA)', '2008', 'Adventure', 'Altron', '1', 'Horror', 'Mini-game collection and horror.', 'Survive the attractions of the creepy HorrorLand park.', 'A spooky mini-game collection based on R.L. Stine''s books.', 'Goosebumps HorrorLand on NDS takes you to a theme park where the scares are real. Win tickets in creepy carnival games, avoid monsters, and uncover the park''s dark secrets in this kid-friendly horror title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gopets---vacation-island!-usa', 'NDS', 'GoPets - Vacation Island! (USA)', '2009', 'Simulation', 'Quantic Dream', '1', 'Casual', 'Virtual pet simulation.', 'Care for your pets and travel to exotic vacation islands.', 'A social pet simulation with online features.', 'GoPets: Vacation Island! on NDS lets you dress up and train your digital pets. Compete in mini-games, travel to tropical resorts, and share your creations with friends in this cute and customizable pet sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gormiti---the-lords-of-nature!-europe-enfrdeesit', 'NDS', 'Gormiti - The Lords of Nature! (Europe) (En,Fr,De,Es,It)', '2008', 'Action', 'Climax Studios', '1', 'Fantasy', 'Action-adventure and combat.', 'Defeat the evil Magmion and save the island of Gorm.', 'An action game based on the popular Gormiti toy line.', 'Gormiti: The Lords of Nature! on NDS lets you control the elemental lords. Switch between Earth, Sea, Air, and Forest characters to use their unique powers, solve puzzles, and defeat Magmion''s lava minions in this heroic adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gormiti---the-lords-of-nature!-usa-enfrdeesit', 'NDS', 'Gormiti - The Lords of Nature! (USA) (En,Fr,De,Es,It)', '2008', 'Action', 'Climax Studios', '1', 'Fantasy', 'Action-adventure and combat.', 'Defeat the evil Magmion and save the island of Gorm.', 'An action game based on the popular Gormiti toy line.', 'Gormiti: The Lords of Nature! on NDS lets you control the elemental lords. Switch between Earth, Sea, Air, and Forest characters to use their unique powers, solve puzzles, and defeat Magmion''s lava minions in this heroic adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gotouchi-kentei-ds-japan', 'NDS', 'Gotouchi Kentei DS (Japan)', '2006', 'Educational', 'Success', '1', 'Quiz', 'Trivia and quiz.', 'Test your knowledge about various Japanese prefectures.', 'A regional trivia game focused on Japanese culture.', 'Gotouchi Kentei DS challenges you to become an expert on Japan. Answer thousands of questions about local food, history, and landmarks across all prefectures in this educational and fun trivia experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gouma-reifu-den-izuna-japan', 'NDS', 'Gouma Reifu Den Izuna (Japan)', '2006', 'RPG', 'Success', '1', 'Anime', 'Roguelike RPG.', 'Cleanse the world of evil spirits as the ninja girl Izuna.', 'A challenging dungeon crawler with a humorous story.', 'Izuna: Legend of the Unemployed Ninja on NDS features classic roguelike mechanics. Explore randomly generated dungeons, manage your equipment, and use powerful talismans to defeat spirits in this vibrant and difficult RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gouma-reifu-den-izuna-ni-japan', 'NDS', 'Gouma Reifu Den Izuna Ni (Japan)', '2008', 'RPG', 'Success', '1', 'Anime', 'Roguelike RPG.', 'Search for your missing friends in dangerous dungeons.', 'The polished sequel to the cult-classic ninja roguelike.', 'Izuna 2: The Unemployed Ninja Returns expands on the original with a tag-team system. Control two characters at once, master deep equipment customization, and enjoy the series'' signature wit and challenging dungeon-crawling gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gourmet-chef---cook-your-way-to-fame-usa-enfres', 'NDS', 'Gourmet Chef - Cook Your Way to Fame (USA) (En,Fr,Es)', '2010', 'Simulation', 'Big Blue Bubble', '1', 'Cooking', 'Cooking simulation.', 'Cook exquisite dishes and rise to become a star chef.', 'A professional cooking sim focused on gourmet cuisine.', 'Gourmet Chef for NDS puts you in a high-end kitchen. Use the stylus to chop, sauté, and plate complex recipes. Manage your time and precision to impress food critics and build your culinary reputation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('grand-galop-europe-enfr', 'NDS', 'Grand Galop (Europe) (En,Fr)', '2007', 'Sports', 'Kalisto', '1', 'Horse', 'Horse simulation and adventure.', 'Care for your horse and win riding competitions.', 'A charming equestrian game based on the Grand Galop series.', 'Grand Galop on NDS lets you experience the bond between rider and horse. Groom your animal, train in various disciplines, and compete in tournaments while following an engaging story filled with friendship and nature.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('grand-theft-auto---chinatown-wars-europe-enfrdeesit', 'NDS', 'Grand Theft Auto - Chinatown Wars (Europe) (En,Fr,De,Es,It)', '2009', 'Action', 'Rockstar Leeds', '1', 'OpenWorld', 'Open world action.', 'Solve the mystery of your father''s murder and regain honor.', 'An incredible top-down GTA experience built for NDS.', 'GTA: Chinatown Wars is a technical masterpiece on NDS. Use the touch screen to hotwire cars, craft Molotovs, and trade goods in a massive, living Liberty City. A mature, high-octane adventure with an engaging crime plot.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('grand-theft-auto---chinatown-wars-japan', 'NDS', 'Grand Theft Auto - Chinatown Wars (Japan)', '2009', 'Action', 'Rockstar Leeds', '1', 'OpenWorld', 'Open world action.', 'Solve the mystery of your father''s murder and regain honor.', 'An incredible top-down GTA experience built for NDS.', 'GTA: Chinatown Wars is a technical masterpiece on NDS. Use the touch screen to hotwire cars, craft Molotovs, and trade goods in a massive, living Liberty City. A mature, high-octane adventure with an engaging crime plot.');
