INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('grand-trucker-aniki---shigoto-to-kenka-to-koi-moyou-japan', 'NDS', 'Grand Trucker Aniki - Shigoto to Kenka to Koi Moyou (Japan)', '2009', 'Adventure', 'D3 Publisher', '1', 'Drama', 'Driving and life simulation.', 'Deliver goods across Japan and manage your truck life.', 'A unique "Dekotora" truck driving and social simulation.', 'Grand Trucker Aniki on NDS lets you customize massive, neon-lit Japanese trucks. Balance your delivery schedule with social interactions and occasional brawls to become the legendary king of the road in this eccentric title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('grease---the-official-video-game-europe-ndsi-enhanced', 'NDS', 'Grease - The Official Video Game (Europe) (NDSi Enhanced)', '2010', 'Music', 'Zoë Mode', '1', 'Rhythm', 'Rhythm and dance.', 'Perform classic songs and win Sandy''s heart as Danny.', 'The official musical game based on the hit movie Grease.', 'Grease for NDS brings Rydell High to your console. Use the stylus to keep the rhythm to iconic songs like "You''re the One That I Want." Featuring DSi-enhanced features for a more personalized musical experience.');
