INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('green-lantern---rise-of-the-manhunters-europe-enfrdeesitnl', 'NDS', 'Green Lantern - Rise of the Manhunters (Europe) (En,Fr,De,Es,It,Nl)', '2011', 'Action', 'Double Helix', '1', 'Superhero', 'Action brawler.', 'Use the power ring to defeat the Manhunters.', 'A cosmic action game based on the Green Lantern film.', 'Green Lantern: Rise of the Manhunters for NDS lets you create hard-light constructs to battle enemies. Fight through interstellar levels, upgrade your powers, and save the Guardians in this fast-paced superhero adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('green-lantern---rise-of-the-manhunters-usa-enfrdeesitnl', 'NDS', 'Green Lantern - Rise of the Manhunters (USA) (En,Fr,De,Es,It,Nl)', '2011', 'Action', 'Double Helix', '1', 'Superhero', 'Action brawler.', 'Use the power ring to defeat the Manhunters.', 'A cosmic action game based on the Green Lantern film.', 'Green Lantern: Rise of the Manhunters for NDS lets you create hard-light constructs to battle enemies. Fight through interstellar levels, upgrade your powers, and save the Guardians in this fast-paced superhero adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('greg-hastings-tournament-paintball-maxd-europe', 'NDS', 'Greg Hastings'' Tournament Paintball Max''d (Europe)', '2006', 'Sports', 'The Whole Experience', '4', 'Shooter', 'Sports simulation and action.', 'Compete in professional paintball tournaments.', 'A realistic and fast-paced paintball simulation game.', 'Greg Hastings'' Paintball Max''d on NDS offers tactical sports action. Manage your team, use cover effectively, and eliminate opponents in various game modes, providing a portable version of the extreme tournament experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('greg-hastings-tournament-paintball-maxd-usa', 'NDS', 'Greg Hastings'' Tournament Paintball Max''d (USA)', '2006', 'Sports', 'The Whole Experience', '4', 'Shooter', 'Sports simulation and action.', 'Compete in professional paintball tournaments.', 'A realistic and fast-paced paintball simulation game.', 'Greg Hastings'' Paintball Max''d on NDS offers tactical sports action. Manage your team, use cover effectively, and eliminate opponents in various game modes, providing a portable version of the extreme tournament experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gremlins---gizmo-usa-enfrespt', 'NDS', 'Gremlins - Gizmo (USA) (En,Fr,Es,Pt)', '2010', 'Adventure', 'Fun Labs', '1', 'Cartoon', 'Virtual pet simulation.', 'Care for Gizmo and play fun mini-games.', 'A cute pet sim featuring the lovable Mogwai from Gremlins.', 'Gremlins: Gizmo on NDS lets you interact with the iconic character. Play music, feed him (not after midnight!), and engage in fun activities. Just be careful not to get him wet or you''ll have a gremlin problem on your hands!');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('greys-anatomy---the-video-game-europe-enfrdeesit', 'NDS', 'Grey''s Anatomy - The Video Game (Europe) (En,Fr,De,Es,It)', '2009', 'Adventure', 'White Birds', '1', 'Drama', 'Adventure and visual novel.', 'Manage medical cases and balance relationships at the hospital.', 'An interactive drama based on the hit TV show.', 'Grey''s Anatomy: The Video Game on NDS lets you play as your favorite doctors. Perform surgeries using the stylus and navigate the complex social lives of Seattle Grace Hospital in this dramatic adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('greys-anatomy---the-video-game-usa-enfres', 'NDS', 'Grey''s Anatomy - The Video Game (USA) (En,Fr,Es)', '2009', 'Adventure', 'White Birds', '1', 'Drama', 'Adventure and visual novel.', 'Manage medical cases and balance relationships at the hospital.', 'An interactive drama based on the hit TV show.', 'Grey''s Anatomy: The Video Game on NDS lets you play as your favorite doctors. Perform surgeries using the stylus and navigate the complex social lives of Seattle Grace Hospital in this dramatic adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('grid-usa-enfres', 'NDS', 'Grid (USA) (En,Fr,Es)', '2009', 'Racing', 'Codemasters', '1', 'Simulation', 'Professional racing.', 'Compete in various racing disciplines and win the season.', 'A high-performance racing game with realistic physics.', 'Grid on NDS brings professional motor racing to life. Compete in touring cars, drift events, and street races. With detailed tracks and a robust career mode, it’s one of the most comprehensive racers on the system.');